use std::io::Write;
use std::cmp::max;
use std::cmp::min;

pub struct Scanner {
  buffer: Vec<String>
}

impl Scanner {
  pub fn new() -> Scanner {
    Scanner { buffer: Vec::new() }
  }

  pub fn next<T: std::str::FromStr>(&mut self) -> T {
    loop {
      if let Some(token) = self.buffer.pop() {
          return token.parse().ok().expect("Failed parse");
      }
      let mut input = String::new();
      std::io::stdin().read_line(&mut input).expect("Failed read");
      self.buffer = input.split_whitespace().rev().map(String::from).collect();
    }
  }
}

struct Square {
 x1: u32,
 y1: u32,
 x2: u32,
 y2: u32,
}

impl Square {
  fn from(scan: &mut Scanner) -> Square {
    Square::new(scan.next(), scan.next(), scan.next(), scan.next())
  }

  fn new(x1: u32, y1: u32, x2: u32, y2: u32) -> Square {
    if x1 <= x2 && y1 <= y2 {
      Square { x1, y1, x2, y2 }
    } else {
      Square { x1: 0, y1: 0, x2: 0, y2: 0 }
    }
  }

  fn intersect(&self, other: &Square) -> Square {
    Square::new(max(self.x1, other.x1), max(self.y1, other.y1),
                min(self.x2, other.x2), min(self.y2, other.y2))
  }

  fn area(&self) -> u64 {
    ((self.x2 - self.x1) as u64) * ((self.y2 - self.y1) as u64)
  }
}

fn main() {
  let stdout = std::io::stdout();
  let mut out = std::io::BufWriter::new(stdout.lock());
  let mut scan = Scanner::new();

  let white = Square::from(&mut scan);
  let black1 = Square::from(&mut scan);
  let black2 = Square::from(&mut scan);
  let intersect1 = white.intersect(&black1);
  let intersect2 = white.intersect(&black2);
  let covered = intersect1.area() + intersect2.area()
                - intersect1.intersect(&intersect2).area();
  if white.area() > covered {
    writeln!(out, "YES").unwrap();
  } else {
    writeln!(out, "NO").unwrap();
  }
}

