const BIG_STACK_SIZE: bool = true;
#[allow(dead_code)]
fn main() {
    use std::thread;
    if BIG_STACK_SIZE {
        thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .name("solve".into())
            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}
fn solve() {
    input!{
        w0: (i64,i64,i64,i64),
        b0: (i64,i64,i64,i64),
        b1: (i64,i64,i64,i64),
    }

    let mut xs = vec![];
    xs.push(w0.0);
    xs.push(w0.2);
    xs.push(b0.0);
    xs.push(b0.2);
    xs.push(b1.0);
    xs.push(b1.2);
    xs.sort();
    let mut x_compress = HashMap::new();
    let mut x_decompress = HashMap::new();
    let mut cur_x=0;
    for x in xs {
        if !x_compress.contains_key(&x) {
            x_compress.entry(x).or_insert(cur_x);
            x_decompress.entry(cur_x).or_insert(x);
            cur_x+=1;
        }
    }

    let mut ys = vec![];
    ys.push(w0.1);
    ys.push(w0.3);
    ys.push(b0.1);
    ys.push(b0.3);
    ys.push(b1.1);
    ys.push(b1.3);
    ys.sort();
    let mut y_compress = HashMap::new();
    let mut y_decompress = HashMap::new();
    let mut cur_y=0;
    for y in ys {
        if !y_compress.contains_key(&y) {
            y_compress.entry(y).or_insert(cur_y);
            y_decompress.entry(cur_y).or_insert(y);
            cur_y+=1;
        }
    }

    let mut table = vec![vec![false; cur_y-1]; cur_x-1];
    let x_comp = |x: i64| {
        x_compress.get(&x).unwrap().clone() as usize
    };
    let y_comp = |y: i64| {
        y_compress.get(&y).unwrap().clone() as usize
    };
    for x in x_comp(b0.0)..x_comp(b0.2) {
        for y in y_comp(b0.1)..y_comp(b0.3) {
            table[x][y]=true;
        }
    }
    for x in x_comp(b1.0)..x_comp(b1.2) {
        for y in y_comp(b1.1)..y_comp(b1.3) {
            table[x][y]=true;
        }
    }
    let mut ok = false;
    for x in x_comp(w0.0)..x_comp(w0.2) {
        for y in y_comp(w0.1)..y_comp(w0.3) {
            if !table[x][y] {
                ok=true;
                break;
            }
        }
    }

    if ok {
        println!("YES");
    } else {
        println!("NO");
    }
}

