struct SlidingWindowQ<F> {
    q: VecDeque<usize>,
    window: usize,
    f: F
}

impl<F> SlidingWindowQ<F>
where
    F: Fn(usize,usize) -> bool
{
    fn new(window: usize, f: F) -> Self
    {
        SlidingWindowQ {
            q: VecDeque::new(),
            window: window,
            f: f
        }
    }

    fn push(&mut self, i: usize) {
        while self.q.len() > 0 {
            let j = *self.q.back().unwrap();

            if (self.f)(i, j) {
                self.q.pop_back();
            } else {
                break;
            }
        }
        self.q.push_back(i);

        let j = *self.q.front().unwrap();
        if i >= self.window && j == i - self.window {
            self.q.pop_front();
        }
    }

    fn front(&self) -> usize {
        *self.q.front().unwrap()
    }
}


