fn next_width(w : u64) -> u64 {
    2 * w
}

fn next_interval(h : u64, w : u64) -> (u64, u64) {
    (h + 1, h + w)
}

fn within_interval(l : u64, h : u64, n : u64) -> bool {
    (n >= l) && (n <= h)
}

fn drinks_nth(n : u64) -> String {
    let mut l = 1;
    let mut h = 5;
    let mut w = h - l + 1;
    loop {
        if within_interval(l, h, n) {
            break;
        } else {
            w = next_width(w);
            let (x, y) = next_interval(h, w); 
            l = x;
            h = y;
        }
    }
    let b = w / 5;
    let i = ((n - l) / b) + 1;
    String::from(NAMES[i as usize])
}

