fn get_cycle_rate(c: u32) -> u64 {
    (2 as u64).pow(c)
}

fn get_cycle_person_width(c: u32) -> u64 {
    5 * get_cycle_rate(c)
}

/// return cycle number and cycle offset
fn get_cycle(n: u64) -> Option<(u32, u64)> {
    let mut total = 0;

    for i in 0..100 {
        if n < (total + get_cycle_person_width(i)) {
            return Some((i, total));
        }

        total = total + get_cycle_person_width(i);
    }

    return None;
}

