pub struct Scanner<U: Sized + Read> {
    pub buffer: Vec<String>,
    pub reader: U,
}
impl<U: Sized + Read> Scanner<U> {
    pub fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_to_string(&mut input).expect("Failed read");
            self.buffer = input.lines().rev().map(String::from).collect();
        }
    }

    pub fn new(reader: U) -> Self {
        return Scanner {
            buffer: vec![],
            reader,
        };
    }
}
pub fn solution_of_p112a(input: &mut Read, out: &mut Write) {
    let mut scanner = Scanner::new(input);
    let arr1: Vec<char> = scanner
        .next::<String>()
        .to_ascii_lowercase()
        .chars()
        .collect();
    let arr2: Vec<char> = scanner
        .next::<String>()
        .to_ascii_lowercase()
        .chars()
        .collect();

    let res = lexicographical_order(arr1, arr2);
    write!(out, "{}\n", res).ok();
}

pub fn lexicographical_order(arr1: Vec<char>, arr2: Vec<char>) -> i32 {
    let l = arr1.len(); // assume the 2 string has the same length
    for i in 0..l {
        let u1 = arr1[i] as u8;
        let u2 = arr2[i] as u8;
        if u1 < u2 {
            return -1;
        } else if u1 > u2 {
            return 1;
        }
    }
    return 0;
}

