        .split(' ')
        .map(|s| s.parse::<i32>().unwrap());

    let _ = nums.next().unwrap();
    let mut b = nums.next().unwrap();

    let line = read_line()?;

    let nums = line
        .split(' ')
        .map(|s| s.parse::<i32>().unwrap())
        .collect::<Vec<_>>();

    let evency = nums
        .iter()
        .map(|n| if n % 2 == 0 { 1 } else { -1 })
        .collect::<Vec<_>>();

    let mut split_points = HashSet::new();
    let mut s = 0;

    for (i, e) in evency[..evency.len() - 1].iter().enumerate() {
        s += e;

        // println!("{}, {}, {}", i, s, e);

        if s == 0 {
            split_points.insert(i);
        }
    }

    let mut diffs = nums
        .iter()
        .zip(&nums[1..])
        .map(|(&prev, &curr)| (curr - prev).abs())
        .enumerate()
        .collect::<Vec<_>>();

    diffs.sort_unstable_by_key(|&(_, diff)| diff);

    // println!("diffs: {:?}", diffs);
    // println!("split_points: {:?}", split_points);

    let mut ans = 0;

    for (i, diff) in diffs {
        if split_points.contains(&i) && b >= diff {
            // println!("split at {}, price {}, current budget: {}", i, diff, b);

            ans += 1;
            b -= diff;
        }
    }


    println!("{}", ans);

    Ok(())
}

use std::io::{self, Read};
use std::cmp::Ordering;

fn cut( accum: &Vec<(i64,i64)>, nums: &Vec<i64>, s: usize, e: usize ) -> (i64,i64) {
    //println!("cut range: {},{}", s,e);
    for idx in s..e {
        let b = ( accum[e-1].0 - accum[idx].0, accum[e-1].1 - accum[idx].1 );
        let a = if s > 0 {
            ( accum[idx].0 - accum[s-1].0, accum[idx].1 - accum[s-1].1 )
        } else {
            ( accum[idx].0, accum[idx].1 )
        };
        //println!("idx:{}, a: {:?}, b: {:?}", idx, a, b );
        if b.0 == b.1 && b.0 != 0 && a.0 == a.1 && a.0 != 0 {
            //make a cut between (idx, idx+1)
            //println!("make a cut between {}, {}", idx, idx+1 );
            return (idx as i64,idx as i64 + 1) 
        }
    }
    return (-1,-1)
}

fn main() {

    use std::collections::{HashMap,HashSet, BinaryHeap};

    let mut buffer = String::new();
    let stdin = io::stdin();
    let mut handle = stdin.lock();

    handle.read_to_string(&mut buffer).unwrap();

    let input_strs = buffer.split_whitespace().map( |x| x.parse::<i64>().unwrap() ).collect::< Vec<i64> >();

    let n = *input_strs.iter().nth(0).unwrap();
    let b = *input_strs.iter().nth(1).unwrap();

    let nums = input_strs.iter().skip(2).cloned().collect::< Vec<i64> >();

    //println!( "{:?}", nums );


    let mut eo = nums.iter().map( |x| if *x % 2 == 0 { true } else { false } ).collect::<Vec< bool >>();

    let mut count_e = 0;
    let mut count_o = 0;
    let accum = eo.iter().enumerate().map(|(k,x)| {
        if *x == true { count_e += 1; } else { count_o += 1; }
        ( count_e, count_o )
    } ).collect::< Vec< (i64,i64) > >();

    //println!( "{:?}", accum );

    let mut cut_idxs = cut( &accum, &nums, 0, nums.len() );
    let mut accum_cost = 0;
    let mut num_cuts = 0;

    let mut possible_cuts = vec![];
    loop {
        if cut_idxs.0 == -1 || cut_idxs.1 == -1 {
            break;
        }
        let cost_cut = (nums[cut_idxs.0 as usize] - nums[cut_idxs.1 as usize]).abs();

        cut_idxs = cut( &accum, &nums, cut_idxs.1 as usize, nums.len() );
        possible_cuts.push( ( cost_cut, cut_idxs ) );
    }

    possible_cuts.sort();

    // println!( "{:?}", possible_cuts );

    for i in possible_cuts.iter() {
        if accum_cost + i.0 <= b {
            accum_cost += i.0;
            num_cuts += 1;
        } else {
            break;
        }
    }

    println!( "{}", num_cuts );
}

