use std::collections::HashMap;
use std::io;

fn to_pairs(line: &str) -> Vec<(i32, i32)> {
	let mut iter = line.trim().split_whitespace();
	let mut ret = Vec::new();
	while let Some(x) = iter.next() {
		ret.push((x.parse().unwrap(),
		          iter.next().unwrap().parse().unwrap()));
	}
	ret.sort();
	return ret
}

fn get_unique(s1: (i32, i32), s2: (i32, i32)) -> Option<i32> {
	let mut v = Vec::new();
	v.push(s1.0);
	v.push(s1.1);
	v.push(s2.0);
	v.push(s2.1);
	v.sort();
	v.dedup();
	if v.len() != 3 { return None; }
	for x in v {
		if (x == s1.0 || x == s1.1) && (x == s2.0 || x == s2.1) {
			return Some(x);
		}
	}
	return None;
}

fn get_only_bit(x: i32) -> Option<i32> {
	let mut count = 0;
	let mut last = 0;
	for i in 1..10 {
		if (x >> i & 1) != 0 {
			count += 1;
			last = i;
		}
	}
	if count == 1 { return Some(last); }
	return None;
}

fn solve(s1: Vec<(i32, i32)>, s2: Vec<(i32, i32)>) -> i32 {
	let mut va: HashMap<(i32, i32), i32> = HashMap::new();
	let mut vb: HashMap<(i32, i32), i32> = HashMap::new();
	let mut vab = 0;
	for a in s1.iter() {
		for b in s2.iter() {
			if let Some(x) = get_unique(*a, *b) {
				va.entry(*a)
					.and_modify(|e| { *e |= 1 << x })
					.or_insert(1 << x);
				vb.entry(*b)
					.and_modify(|e| { *e |= 1 << x })
					.or_insert(1 << x);
				vab |= 1 << x;
			}
		}
	}
	if let Some(x) = get_only_bit(vab) { return x; }
	for (_, v) in va.iter() {
		if let None = get_only_bit(*v) { return -1; }
	}
	for (_, v) in vb.iter() {
		if let None = get_only_bit(*v) { return -1; }
	}
	return 0;
}

fn main() -> io::Result<()> {
	let f = io::stdin();
	let mut line = String::new();
	f.read_line(&mut line)?;
	line.clear();
	f.read_line(&mut line)?;
	let s1 = to_pairs(&line);
	line.clear();
	f.read_line(&mut line)?;
	let s2 = to_pairs(&line);
	println!("{}", solve(s1, s2));

	Ok(())
}

