pub fn read_word() -> String {
	use std::io::prelude::*;
	let mut word: Vec<u8> = vec![];

	for c in ::std::io::stdin().bytes() {
		let c = c.unwrap();
		if (c as char).is_whitespace() {
			if !word.is_empty() {
				break;
			}
		} else {
			word.push(c);
		}
	}
	::std::str::from_utf8(&word).unwrap().to_string()
}

