fn substring(sentence: &str, word: &str) -> bool {
	if word.len() == 0 {
		return true;
	}
	else if sentence.len() == 0 {
		return false;
	}
	if sentence.chars().next() == word.chars().next() {
		return substring(&sentence[1..], &word[1..]);
	}
	else {
		return substring(&sentence[1..], &word[0..]);
	}
}

