fn to_fraction(num: i64, denom: i64) -> (i64, i64) {
    let g = gcd(num, denom);
    (num / g, denom / g)
}

fn max_fraction(num1: i64, denom1: i64, num2: i64, denom2: i64) -> (i64, i64) {
    if num1 * denom2 < num2 * denom1 {
        to_fraction(num2, denom2)
    }
    else {
        to_fraction(num1, denom1)
    }
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
    let a: i64 = scan.token();
    let b: i64 = scan.token();
    let c: i64 = scan.token();
    let d: i64 = scan.token();

    let num1 = a * d - b * c;
    let denom1 = a * d;
    let num2 = b * c - a * d;
    let denom2 = b * c;

    let ans = max_fraction(num1, denom1, num2, denom2);
    writeln!(out, "{}/{}", ans.0, ans.1).ok();
}

