fn binary_exponentiation(a: i64, b: u64, mod_: i64) -> i64 {
	let mut ans: i64 = 1;
	let mut a = a % mod_;
	let mut b = b;
	while b != 0 {
		if (b & 1) == 1 {
			ans = ans * a % mod_;
		}
		a = a * a % mod_;
		b >>= 1;
	}
	return ans;
}
