fn base_number(x:usize, n:usize)->Vec<usize>{
    let mut x = x;
    let mut n = n;
    let mut r = 1;
    let mut q = x;
    let mut res = vec![];
    while(q>=n){
        r = q%n;
        res.push(r);
        q = q/n;
    }
    r = q%n;
    res.push(r);
    res.reverse();
    return res
}

