fn smallest_prime_factor(n:usize)->Vec<usize>{
    let mut spf = vec![0;n+1];
    for i in 0..n+1{
        spf[i] = i;
    }
    for i in 2..INFu{
        if i*i>n{
            break;
        }
        if spf[i] == i{
            let mut j = i*i;
            while(j<=n){
                if spf[j] == j{
                    spf[j] = i;
                }
                j+=i;
            }
        }
    }

    return spf;
}
fn factorization(x:usize, spf:&Vec<usize>)->Vec<usize>{
    let mut res = vec![];
    let mut x = x;
    while(x != 1){
        res.push(spf[x]);
        x/=spf[x];
    }
    res.sort();
    return res;
}





























