use std::io::{self, Write};

const MOD: i64 = 1e9 as i64 + 7;

fn pow(mut a: i64, mut b: i64) -> i64 {
    let mut ans: i64 = 1;
    while b > 0 {
        if b & 1 == 1 {
            ans = (ans as i64 * a as i64) % MOD;
        }
        a = (a * a) % MOD;
        b >>= 1;
    }
    ans
}

