    let pc = |a: &[char]| {
        10 * (a[0] as u8 as i32) + a[1] as u8 as i32 - 48 * 11
    };
    let p = |a: Vec<char>| {
        60 * pc(&a[0..2]) + pc(&a[3..5])
    };
    let mid = (p(a) + p(b)) / 2;
