fn binary_search(d:i64) -> f64 {
    let mut left = 0.0;
    let mut right = d as f64;

    while (right-left).abs() > 1e-12 {
        let a = (right+left)/2.0;
        let b = d as f64 - a;
        //debug!(left,mid,right,s[mid]);
        if a*b >= d as f64 { left = a; }
        else { right = a; }
    }
    left
}

