// IO

struct CPReader<R> {
    read: R,
    buf: Vec<u8>,
    iter: str::SplitAsciiWhitespace<'static>,
}

impl<R: io::BufRead> CPReader<R> {
    fn new(read: R) -> Self {
        Self { read, buf: vec![], iter: "".split_ascii_whitespace() }
    }
    fn update(&mut self) {
        self.buf.clear();
        self.read.read_until(b'\n', &mut self.buf).unwrap();
        self.iter = unsafe {
            let slice = str::from_utf8_unchecked(& self.buf);
            std::mem::transmute(slice.split_ascii_whitespace())
        }
    }
    fn getstr(&mut self) -> & str {
        loop {
            if let Some(ret) = self.iter.next() {
                break ret;
            }
            self.update();
        }
    }
    fn get<T: str::FromStr>(&mut self) -> T {
        return self.getstr().parse().ok().unwrap();
    }
}

