struct IO {
    reader: BufReader<Stdin>,
    writer: BufWriter<Stdout>,
}

impl Drop for IO {
    fn drop(&mut self) {
        self.flush();
    }
}

impl IO {
    pub fn new() -> IO {
        IO {
            reader: BufReader::new(stdin()),
            writer: BufWriter::new(stdout()),
        }
    }

    pub fn read_i32(&mut self) -> i32 {
        let mut res = String::new();
        self.reader.read_line(&mut res).expect("error read");
        return res.trim().parse().unwrap();
    }

    pub fn read_array_i32(&mut self, split: &str) -> Vec<i32> {
        let mut res = String::new();
        self.reader.read_line(&mut res).expect("error read");
        return res.trim().split(split).map(|x| x.parse().expect("not is i32")).collect::<Vec<i32>>();
    }

    pub fn read_array_i64(&mut self, split: &str) -> Vec<i64> {
        let mut res = String::new();
        self.reader.read_line(&mut res).expect("error read");
        return res.trim().split(split).map(|x| x.parse().expect("not is i64")).collect::<Vec<i64>>();
    }

    pub fn read_str(&mut self) -> String {
        let mut res = String::new();
        self.reader.read_line(&mut res).expect("error read");
        res
    }

    pub fn write<T: Display>(&mut self, value: T, end: &str) {
        self.writer.write(value.to_string().as_bytes()).expect("error write");
        self.writer.write(end.as_bytes()).expect("error write");
    }

    pub fn flush(&mut self) {
        self.writer.flush().expect("error flush");
    }
}

