fn max_ones(xs : &Vec<i8>) -> i8 {
    let s = xs.iter().sum::<i8>();
    let mut ys = vec![];
    let one = 1;
    let minus_one = -1;
    for &x in xs.iter() {
        if x == 0 {
            ys.push(one);
        } else {
            ys.push(minus_one);
        }
    }
    let mut max_upto_i = ys[0];
    let mut max_ending_at_i = ys[0];
    for i in 1 .. ys.len() {
        let y = ys[i];
        max_ending_at_i = max(y, max_ending_at_i + y);
        max_upto_i = max(max_ending_at_i, max_upto_i);
    }
    s + max_upto_i
}

