fn num_of_1_before(i: &Vec<u32>, idx: usize) -> u32 {
    i.iter().take(idx).sum()
}

fn num_of_1_after(i: &Vec<u32>, idx: usize) -> u32 {
    i.iter().skip(idx + 1).sum()
}

fn max_num_of_1_flipped_after(i: &Vec<u32>, idx: usize) -> u32 {
    if 1 == *i.iter().nth(idx).unwrap() {
        return 0;
    }
    let targets = i.iter().skip(idx);
    let mut current_score = 0;
    let mut scores = Vec::new();
    for (local_index, value) in targets.enumerate() {
        if *value == 0 {
            current_score = current_score + 1;
        }
        scores.push(current_score + num_of_1_after(i, idx + local_index));
    }
    scores.into_iter().max().unwrap_or(0)
}

fn max_score(i: &Vec<u32>, idx: usize) -> u32 {
    num_of_1_before(i, idx) + max_num_of_1_flipped_after(i, idx)
}

fn main() {
    input! {
        n: usize,
        a: [u32; n],
    }

    let v = Vec::from(a);

    println!(
        "{}",
        (0..n).map(|idx| max_score(&v, idx)).max().unwrap_or(0)
    );
}

