fn main() {
    let num_cases: usize = 1;//read();

    for _case_num in 1..=num_cases {
        let n = read!(usize);
        let k = read!(usize);

        let mut ans = mi(0);
        if min(n, k) == 1 { ans = mi(1); }
        else {
            let mc = ModCombinatorics::new(min(n, k));
            let ff = ModFft::new(min(n, k) * 2);
            let mu = FactorMap::new_with_mobius(n).1;

            let mut m = 0usize;
            let mut A = mi(0);
            let P = veci!(min(n, k)+1, j: if j & 1 == 1 { -mc.inv_factorial(j) } else { mc.inv_factorial(j) });

            for i in 1..=n {
                if mu[i] == 0 { continue; }
                let mn = n.div_ceil(i);
                if m != mn {
                    m = mn;
                    let l = min(m, k);
                    let Q = veci!(l+1, j: mi(j).pow(m as _) * mc.inv_factorial(j));
                    let R = ff.mul(&P[..=l], &Q);
                    A = R[2..=l].iter().sum();
                }
                if mu[i] == 1 { ans += A; } else { ans -= A; }
            }
        }

        println!(ans);
    }

