// F(a, k): a の要素の個数をk倍にして前|a|個だけ取り出した数列
// G(a, x, y): a中の値x, yを入れ替えたもの
// 列aが列bの親であるというのは
// F(a, k) = b or G(a, x, y) = b
// なるk またはx, y が存在する時
// aがbの祖先であるというのはaに捜査し続けてbにできる時
//
// n, k が与えられる
// 長さnの列で値が1..=k の全ての列を生成できるような元の最小値をmod9982244353で求めて
//
// G は可逆な操作
//
// F は？
//

fn run() {
    input!(n: usize, k: usize);
    if k == 1 || n == 1 {
        println!("1");
        return;
    }
    let pc = precalc::Precalc::new(n + k);
    let mut memo = vec![M::zero(); n + 1];
    for i in 1..=n {
//        let len = n / i;
        let len = (n + i - 1) / i;
        let mut a = vec![M::zero(); len + 1];
        let mut b = vec![M::zero(); len + 1];
        for i in 0..=len {
            a[i] = M::from(i).pow(len as u64) * pc.ifact(i);
            b[i] = M::from(-1i64).pow(i as u64) * pc.ifact(i);
        }
        let mut c = a.multiply(&b);
        c.truncate((len + 1).min(k + 1));
        memo[i] = c.iter().fold(M::zero(), |s, a| s + *a) - M::one();
    }
    enumerate_prime(n, |p| {
        for i in 1..=(n / p) {
            memo[i] = memo[i] - memo[i * p];
        }
    });
    println!("{}", memo[1]);
}

fn main() {
    run();
}

