pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write_all(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn usize0(&mut self) -> usize {
        self.read::<usize>() - 1
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::collections::BTreeSet;
use std::io::{self, prelude::*};
use std::iter;

fn solve<R: BufRead, W: Write>(scan: &mut input::Scanner<R>, out: &mut W) {
    let mut keys: BTreeSet<usize> = iter::once(scan.token()).collect();
    let doors: Vec<_> = (1..=3).map(|_| scan.token::<usize>()).collect();
    loop {
        let prev = keys.clone();
        for key in &prev {
            if doors[key - 1] != 0 {
                keys.insert(doors[key - 1]);
            }
        }
        if prev.len() == keys.len() {
            break;
        }
    }
    let answer = if keys.len() == 3 { "YES" } else { "NO" };
    writeln!(out, "{answer}").unwrap();
}

