fn main() {
    let mut stdin = io::stdin();
    // From https://keens.github.io/blog/2017/10/05/rustdekousokunahyoujunshutsuryoku/
    let stdout = io::stdout();
    let mut output = BufWriter::new(stdout.lock());
    let mut input_str = String::new();
    let _ = stdin.read_to_string(&mut input_str);
    let mut input_iter = input_str.split_ascii_whitespace();
    // From https://github.com/rust-lang-ja/atcoder-rust-resources/wiki/2020-Update#proconio
    sub_main(&mut input_iter, &mut output);
