fn sub_main(input_iter: &mut dyn Iterator<Item = &str>, output: &mut dyn Write) {
    macro_rules! read(() => (input_iter.next().unwrap().parse().unwrap()));
    macro_rules! print(( $( $x:expr ),*) => (write!(output, $($x,)*).unwrap()));
    macro_rules! println(( $( $x:expr ),*) => (writeln!(output, $($x,)*).unwrap()));
    // Deal with each case
    let n: usize = read!();
    let non_cyclic = ModP(2).pow(n - 1);
    let mut total_num = ModP(1);
    for i in 1..=n {
        total_num = total_num * ModP(i as u64);
    }
    let ans = total_num - non_cyclic;
    println!("{}", ans.0);
}

use std::ops::{Add, Div, Mul, Sub};

const MODULUS: u64 = 1000000007;

#[derive(Clone, Copy, PartialEq, Debug)]
struct ModP(u64);

impl Add for ModP {
    type Output = Self;
    fn add(self, rhs: Self) -> Self {
        return ModP((self.0 + rhs.0) % MODULUS);
    }
}
impl Sub for ModP {
    type Output = Self;
    fn sub(self, rhs: Self) -> Self {
        return ModP((self.0 + MODULUS - rhs.0) % MODULUS);
    }
}
impl Mul for ModP {
    type Output = Self;
    fn mul(self, rhs: Self) -> Self {
        return ModP((self.0 * rhs.0) % MODULUS);
    }
}
impl Div for ModP {
    type Output = Self;
    fn div(self, rhs: Self) -> Self {
        if rhs.0 == 0 {
            panic!("Tried to divide by ModP(0)!");
        }
        let rhs_inv = rhs.pow((MODULUS - 2) as usize);
        return self * rhs_inv;
    }
}

impl ModP {
    fn pow(&self, n: usize) -> Self {
        if n == 0 {
            return ModP(1);
        } else if n == 1 {
            return *self;
        } else {
            let half = self.pow(n / 2);
            if n % 2 == 0 {
                return half * half;
            } else {
                return half * half * (*self);
            }
        }
    }
}

