fn raw_input() -> String {
    let mut buf = String::new();
    std::io::stdin().read_line(&mut buf).unwrap();
    buf.trim().to_string()
}

fn find(row: &[char; 10], letter: char) -> Result<usize, ()> {
    for i in 0..row.len() {
        if row[i] == letter {
            return Ok(i);
        }
    }
    Err(())
}

fn shift_message(message: &String, kb: &Keyboard, dir: isize) -> String {
    let mut new_message = String::with_capacity(message.len());
    for letter in message.chars() {
        for row in kb.iter() {
            if let Ok(index) = find(row, letter) {
                new_message.push(row[(index as isize + dir) as usize]);
                break;
            }
        }
    }
    new_message
}

