struct IO {
    tokens: Vec<String>,
}

impl IO {
    fn new() -> IO {
        IO { tokens: Vec::new() }
    }

    fn read<T: std::str::FromStr>(&mut self) -> T {
        self.read_token().parse::<T>().ok().unwrap()
    }

    fn read_token(&mut self) -> String {
        if self.tokens.is_empty() {
            self.tokens = self
                .read_line()
                .split_whitespace()
                .map(|x| x.to_string())
                .collect();
            self.tokens.reverse();
        }
        self.tokens.pop().unwrap()
    }

    fn read_line(&mut self) -> String {
        let mut s = String::new();
        std::io::stdin().read_line(&mut s).expect("die");
        s.trim_right().to_string()
    }
}

