fn solve_zeroes(s: &Vec<u8>, count: &Vec<usize>) -> usize {
    if count[0] < 2 {
        return std::usize::MAX;
    }
    let mut first = true;
    let mut result = 0;
    for i in 0..s.len() {
        if s[i] != 0 {
            continue;
        }
        if first {
            first = false;
            result += i;
        }else if !first {
            result += i - 1;
            break;
        }
    }
    return result;
}

fn solve_half(s: &Vec<u8>, count: &Vec<usize>) -> usize {
    if count[5] == 0 || count[0] == 0 {
        return std::usize::MAX;
    }
    if s[0] == 0 && s[1] == 5 {
        return 0;
    }
    if s[0] == 5 && s[1] == 0 {
        return 1;
    }
    if count[5] == 1 && count[0] + 1 == s.len() {
        return std::usize::MAX;
    }
    let mut result = 0;
    let mut first = [std::usize::MAX, std::usize::MAX];
    let mut other = std::usize::MAX;
    for i in 0..s.len() {
        if s[i] != 0 && s[i] != 5 || s[i] == 5 && first[1] != std::usize::MAX {
            other = i;
        }
        if first[0] == std::usize::MAX && s[i] == 0 {
            result += i;
            first[0] = i;
        }
        if first[1] == std::usize::MAX && s[i] == 5 {
            result += i - 1;
            first[1] = i;
        }
    }
    if first[0] > first[1] {
        result += 1;
    }
    if first[1] + 1 == s.len() {
        if s[s.len() - 2] == 0 || first[0] + 2 == s.len() && s[s.len() - 3] == 0 {
            result += s.len() - other - 2;
            if first[0] > other {
                result -= 1;
            }
        }
    }
    return result;
}

fn solve_one(s: &Vec<u8>, count: &Vec<usize>, b: usize, a: usize) -> usize {
    if count[a] == 0 || count[b] == 0 {
        return std::usize::MAX;
    }
    if s[0] == a as u8 && s[1] == b as u8 {
        return 0;
    }
    if s[0] == b as u8 && s[1] == a as u8 {
        return 1;
    }
    if count[a] == 1 && count[b] == 1 && count[0] + 2 == s.len() {
        return std::usize::MAX;
    }
    let mut result = 0;
    let mut first = [std::usize::MAX, std::usize::MAX];
    let mut other = std::usize::MAX;
    for i in 0..s.len() {
        if s[i] != 0 && s[i] != a as u8 && s[i] != b as u8 ||
            s[i] == a as u8 && first[0] != std::usize::MAX ||
            s[i] == b as u8 && first[1] != std::usize::MAX {
            other = i;
        }
        if first[0] == std::usize::MAX && s[i] == a as u8 {
            result += i;
            first[0] = i;
        }
        if first[1] == std::usize::MAX && s[i] == b as u8 {
            result += i - 1;
            first[1] = i;
        }
    }
    if first[0] > first[1] {
        result += 1;
    }
    if first[1] + 1 == s.len() {
        if s[s.len() - 2] == 0 || first[0] + 2 == s.len() && s[s.len() - 3] == 0 {
            result += s.len() - other - 2;
            if first[0] > other {
                result -= 1;
            }
        }
    }else if first[0] + 1 == s.len() {
        if s[s.len() - 2] == 0 || first[1] + 2 == s.len() && s[s.len() - 3] == 0 {
            result += s.len() - other - 2;
            if first[1] > other {
