}

fn move_digits(from : usize, to : usize, dgts : &mut Vec<u64>) -> u64 {
    let mut num_swaps = 0;
    let dgt_from = dgts[from];
    let mut idx = from - 1;
    loop {
        if idx == to {
            dgts[idx + 1] = dgts[idx];
            dgts[idx] = dgt_from;
            num_swaps = num_swaps + 1;
            break;
        } else {
            dgts[idx + 1] = dgts[idx];
            idx = idx - 1;
            num_swaps = num_swaps + 1;
        }
    }
    num_swaps
}

fn swap_zero_out(from : usize, to : usize, dgts : &mut Vec<u64>) -> Option<u64> {
    if from < 2 {
        None
    } else {
        let mut found = false;
        let mut idx = from - 2;
        if idx < to {
            None
        } else {
            loop {
                if idx == to {
                    if dgts[idx] == 0 {
                        // Do nothing ...
                    } else {
                        found = true;
                    }
                    break;
                } else {
                    if dgts[idx] == 0 {
                        idx = idx - 1;
                    } else {
                        found = true;
                        break;
                    }
                }
            }
            if found {
                let num_swaps = move_digits(from - 1, idx, dgts);
                Some(num_swaps)
            } else {
                None
            }
        }
    }
}

fn swap_to_index(from : usize, to : usize, dgts : &mut Vec<u64>) -> Option<u64> {
    if from < to {
        panic!("Check failed: from({}) >= to({}).", from, to);
    } else if from == to {
        Some(0)
    } else {
        let num_dgts = dgts.len();
        if from == (num_dgts - 1) {
            // From is the highest digit, we have to check whether
            // the digit immediately to the right of it is a zero.
            if dgts[from - 1] == 0 {
                // We have to swap zero out of its location.
                match swap_zero_out(from, to, dgts) {
                    None => None,
                    Some(x) => { 
                        let y = move_digits(from, to, dgts);
                        let num_swaps = x + y;
                        Some(num_swaps)
                    },
                }
            } else {
                // We don't have to worry about swapping a zero into
                // the highest digit.
                let num_swaps = move_digits(from, to, dgts);
                Some(num_swaps)
            }
        } else {
            // From is not the highest digit, so we need not
            // worry about swapping a zero into its place.
            let num_swaps = move_digits(from, to, dgts);
            Some(num_swaps)
        }
    }
}

