        if (dgt_indxs[7].len() >= 1) && (dgt_indxs[5].len() >= 1) {
            let mut could_swap = true;
            let mut num_swaps = u64::max_value();
            match swap_to_index(dgt_indxs[5][0], 0, &mut dgts) {
                None => {
                    could_swap = false;
                },
                Some(x) => {
                    num_swaps = x;
                },
            };
            if could_swap {
                let mut could_swap_2 = true;
                digit_indices(&dgts, &mut dgt_indxs);
                match swap_to_index(dgt_indxs[7][0], 1, &mut dgts) {
                    None => {
                        could_swap_2 = false;
                    },
                    Some(x) => {
                        num_swaps = num_swaps + x;
                    },
                };
                if could_swap_2 {
                    if num_swaps < min_num_swaps {
                        min_num_swaps = num_swaps;
                    }
                }
            }
        } 
        if min_num_swaps < u64::max_value() {
            Some(min_num_swaps)
        } else {
            None
        }
    }
}

