        println!("-1");
        return;
    }

    let p = vec![
        try(&num, '5', '2'),
        try(&num, '5', '7'),
        try(&num, '0', '0'),
        try(&num, '0', '5'),
    ];

    println!("{}", match p.iter().min() {
        Some(&::std::usize::MAX) => -1,
        Some(&result) => result as i32,
        _ => unreachable!(),
    });
