fn try(num: &String, s0: char, s1: char) -> usize {

    let mut num = num.clone();
    let mut swaps = 0usize;

    // find first

    let pos = num.rfind(s0);
    if let Some(pos) = pos {

        swaps += num.len() - pos - 1;

        num.remove(pos);

        // find second

        let pos = num.rfind(s1);

        if let Some(pos) = pos {

            swaps += num.len() - pos - 1;

            num.remove(pos);
            num.push(s1);
            num.push(s0);

            // correct leading zeroes, if necessary and possible

            if num.starts_with('0') {
                let pos = num.find(|c| c != '0');
                if let Some(pos) = pos {
                    if pos < num.len() - 2 {
                        swaps += pos;
                        return swaps;
                    }
                }
            } else {
                return swaps;
            }
        }
    }

    ::std::usize::MAX
}

