fn bin_pow_rem(mut a: u128, mut b: u128, rem: u128) -> u128 {
    a %= rem;
    let mut res = 1;

    while b != 0 {
        if b&1 == 1 {
            res = res*a%rem;
        }
        a = a*a%rem;
        b >>= 1;
    }
    res
}

