const REM: usize = 1_000_000_007;

fn bin_pow_rem(mut a: u64, mut b: u64, rem: u64) -> u64 {
    a %= rem;
    let mut res = 1;

    while b != 0 {
        if b&1 == 1 {
            res = res*a%rem;
        }
        a = a*a%rem;
        b >>= 1;
    }
    res
}

#[inline]
unsafe fn solve(r: &mut Reader, w: &mut BufWriter<StdoutLock>) {
    let n = read!(r, u64);
    wl!(w, "{}", bin_pow_rem(4, (1 << n) -2, REM as u64)*6 % REM as u64);
}

use std::io::stdin;

fn log2(mut input: u128) -> i32 {
    let mut count = -1;
    while input != 0 {
        input = input >> 1;
        count += 1;
    }
    return count
}
fn main() {
    let stdin = stdin();
    let mut string = String::new();

    stdin.read_line(&mut string).unwrap();

    let n = string.trim().parse::<usize>().unwrap();

    let mut nodes = 2u128.pow(n as u32) - 2;
    let mut re = 1;
    loop {
        let mut inner_re = 4;
        if nodes == 0 {
            break;
        }

        let times = log2(nodes) as u32;
        for _ in 0..times {
            inner_re = inner_re * inner_re;
            if inner_re > (1e9 as u128 + 7) {
                inner_re = inner_re % (1e9 as u128 + 7)
            }
        }

        re = re * inner_re % (1e9 as u128 + 7);
        nodes = nodes - 2u128.pow(times);
    }
    println!("{}", re * 6 % (1e9 as u128 + 7))
}

