    let mut ans: Vec<i64> = vec![0; n + 1];
    for i in 1..=n {
        ans[i] = (div[i] + dp[i - 1]) % MOD;
        dp[i] = (ans[i] + dp[i - 1]) % MOD;
    }
    writeln!(out, "{}", ans[n]).unwrap();
}

