const MOD:i32 = 998244353;

fn solve(n: usize) -> i32 {
    let mut ans = vec![0i32; n + 1];
    let mut sum = 0i32;
    let mut presum = 0i32;
    for i in 1..n+1 {
        let mut j = i;
        while j <= n {
            ans[j] += 1;
            j+=i;
        }
        // println!("ans[{}]: {}, sum: {}, presum: {}", i, ans[i], sum, presum);
        if ans[i] + presum > MOD {
            sum = ans[i] + presum - MOD;
            presum += ans[i] + presum - MOD;
        } else {
            sum = ans[i] + presum;
            presum += ans[i] + presum;
        }
        if presum > MOD {
            presum -= MOD
        }
    }
    return sum
}

fn run<W: Write>(sc: &mut scanner::Scanner, out: &mut std::io::BufWriter<W>) {
    let n: usize = sc.next();
    writeln!(out, "{}", solve(n));
}

use std::io::{prelude::*, stdin, stdout, BufReader, BufWriter};

fn main() {
    let std_in = stdin();
    let in_lock = std_in.lock();
    let input = BufReader::new(in_lock);

    let std_out = stdout();
    let out_lock = std_out.lock();
    let mut output = BufWriter::new(out_lock);

    let mut lines = input.lines().map(|r| r.unwrap());

    let n = lines.next().unwrap().parse::<usize>().unwrap();

    let mut c: Vec<_> = (0..=n).collect();
    for p in (2..).take_while(|&p| p * p <= n) {
        if c[p] != p {
            continue;
        }

        for i in (1..).take_while(|&i| p * i <= n) {
            c[p * i] = p;
        }
    }

    let ndivisors = |mut n: usize| -> u64 {
        let mut r = 1;
        while n > 1 {
            let p: usize = c[n];
            let mut q = 0;
            while n > 1 && c[n] == p {
                n /= p;
                q += 1;
            }

            r *= q + 1;
        }

        r
    };

    let mut t0 = 0;
    let mut t1 = 1;

    const P: u64 = 998244353;

    for i in 2..=n {
        t0 = t1;
        t1 = (2 * t1 + ndivisors(i)) % P;
    }

    let ans = if t0 <= t1 { t1 - t0 } else { (t1 + P) - t0};

    writeln!(&mut output, "{}", ans).unwrap();
}

