fn run() {
    input! {
        n: usize,
    }
    let mut dp = vec![M::zero(); n + 1];
    for i in 1..=n {
        for j in 1..=(n / i) {
            dp[i * j] += M::one();
        }
    }
    let mut sum = M::zero();
    for i in 1..=n {
        dp[i] = dp[i] + sum;
        sum += dp[i];
    }
    println!("{}", dp[n]);
}

fn main() {
    run();
