fn getline() -> String {
    let mut ret = String::new();
    std::io::stdin().read_line(&mut ret).ok();
    return ret;
}
fn get_word() -> String {
    let mut stdin = std::io::stdin();
    let mut u8b: [u8; 1] = [0];
    loop {
        let mut buf: Vec<u8> = Vec::with_capacity(16);
        loop {
            let res = stdin.read(&mut u8b);
            if res.is_err() || res.ok().unwrap() == 0 || u8b[0] <= ' ' as u8 {
                break;
            } else {
                buf.push(u8b[0]);
            }
        }
        if buf.len() >= 1 {
            let ret = std::string::String::from_utf8(buf).unwrap();
            return ret;
        }
    }
}
fn parse<T: std::str::FromStr>(s: &str) -> T { s.parse::<T>().ok().unwrap() }

#[allow(dead_code)]
fn get<T: std::str::FromStr>() -> T { parse(&get_word()) }

fn main() {
    let n: i64 = get();
    let m: i64 = get();
    let nn = n as usize;
    let mm = m as usize;
    let k: i64 = get();
    let x: usize = get::<usize>() - 1;
    let y: usize = get::<usize>() - 1;
    let mut tbl = vec![vec![0; mm]; nn];
    let div = if n == 1 { m } else { 2 * (n - 1) * m };
    let ascension = k / div;
    let rem = k % div;
    for i in 0 .. nn {
        for j in 0 .. mm {
            tbl[i][j] = ascension * if i == 0 || i == nn - 1 { 1 } else { 2 };
        }
    }
    for i in 0 .. (rem as usize) {
        let p = i / mm;
        let q = i % mm;
        tbl[if p >= nn { 2 * nn - 2 - p } else { p }][q] += 1;
    }
    let mut ma = 0;
    let mut mi = tbl[0][0];
    for i in 0 .. nn {
        ma = max(ma, *tbl[i].iter().max().unwrap());
        mi = min(mi, *tbl[i].iter().min().unwrap());
    }
    println!("{} {} {}", ma, mi, tbl[x][y]);
}

use std::collections::HashMap;
use std::io::stdin;

fn read_int() -> i32 {
    let mut line = String::new();
    stdin().read_line(&mut line).unwrap();
    return line.trim().parse().unwrap();
}

fn read_ints() -> Vec<i32> {
    let mut line = String::new();
    stdin().read_line(&mut line).unwrap();
    return line
        .trim()
        .split(" ")
        .map(|x| x.parse::<i32>().unwrap())
        .collect();
}

fn uniq_nums(v: Vec<i32>) -> Vec<i32> {
    let mut dict = HashMap::new();
    for num in v {
        dict.insert(num, true);
    }

    let mut uniqs = Vec::<i32>::new();
    for key in dict.keys() {
        uniqs.push(*key);
    }
    uniqs.sort();
    return uniqs;
}

fn case_2(v: Vec<i32>) {
    assert_eq!(v.len(), 2);

    let mid = (v[0] + v[1]) / 2;
    if mid - v[0] == v[1] - mid {
        println!("{}", mid - v[0]);
    } else {
        println!("{}", v[1] - v[0]);
    }
}

fn case_3(v: Vec<i32>) {
    assert_eq!(v.len(), 3);
    if v[2] - v[1] == v[1] - v[0] {
        println!("{}", v[2] - v[1]);
    } else {
        println!("-1")
    }
}

fn main() {
    let n = read_int();
    let nums = read_ints();
    let mut uniqs = uniq_nums(nums);

    match uniqs.len() {
        1 => println!("0"),
        2 => case_2(uniqs),
        3 => case_3(uniqs),
        _ => println!("-1"),
    }
}

