fn main() {
    use std::io::Read;
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut sc = scanner::Scanner::new(&s);
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    run(&mut sc, &mut out);
}

fn run<W: Write>(sc: &mut scanner::Scanner, out: &mut std::io::BufWriter<W>) {
    let T = sc.size()/2;
    for kase in 0..T {
        let n: usize = sc.next();
        let x: usize = sc.next();
        let mut qu = VecDeque::new();
        let mut st = BTreeSet::new();
        qu.push_back((x, 0));
        st.insert(x);
        let mut f = false;
        while let Some((u, dp)) = qu.pop_front() {
            if u.to_string().len() > n {
                break;
            }
            if u.to_string().len() == n {
                f = true;
                writeln!(out, "{}", dp);
                break;
            }
            for c in u.to_string().as_bytes() {
                if c < &b'2' {
                    continue;
                }
                let v = u * ((c - b'0') as usize);
                if st.insert(v) {
                    qu.push_back((v, dp + 1));
                }
            }
        }
        if !f {
            writeln!(out, "-1");
        }
    }
}

