const MAX: i64 = 1e9 as i64 + 10;

fn solve(input: &mut io::Input, output: &mut BufWriter<StdoutLock>) {
    let n: usize = input.next();
    let x: i64 = input.next();
    let mut map = HashMap::<i64, i64>::new();
    let mut ans = dfs(n, x, &mut map);
    ans = if ans == MAX { -1 } else { ans };

    writeln!(output, "{ans}");
}


fn dfs(n: usize, x: i64, map: &mut HashMap<i64, i64>) -> i64 {
    let s = x.to_string();
    let ss: HashSet<char> = s.chars().collect();
    let mut min = MAX;
    if s.len() > n { return MAX }
    if s.len() == n { return 0 }
    if let Some(&result) = map.get(&x) { return result }

    for c in ss {
        let i = c as u8 - '0' as u8;
        if i > 1 {
            let p = x * i as i64 ;
            min = min.min(1 + dfs(n, p, map));
        }
    }
    *map.entry(x).or_insert(0) = min;
    min
}

