            x_t = x;
            while x_t > 0 {
            if (x_t % 10) > 1 {
                let y = x * (x_t % 10);
                if !s.contains(&y) {
                    s.insert(y);
                    q.push_back((y, c+1));
                }
            }
            x_t /= 10;
            }
        }
    }
    if ret == std::i32::MAX {
        writeln!(sout, "-1").ok();
    } else {
