                unsafe {
                    $get::INSTANCE = Box::into_raw(Box::new(value));
                }
            }
    
            pub fn $get() -> &'static mut $type {
                unsafe { $get::INSTANCE.as_mut().unwrap() }
            }
        };
    }
    
