    pub struct Scanner {
        reader: Box<dyn BufRead>,
        buffer: Vec<String>,
    }
    
    impl Default for Scanner {
        fn default() -> Self {
            let mut reader_opt: Option<Box<dyn BufRead>> = None;
            for arg in std::env::args().skip(1) {
                if let Ok(fd) = std::fs::File::open(arg) {
                    reader_opt = Some(Box::new(BufReader::new(fd)));
                    break;
                }
            }
            let reader = reader_opt.unwrap_or_else(|| Box::new(BufReader::new(std::io::stdin())));
            Scanner {
                reader,
                buffer: vec![],
            }
        }
    }
    
    singleton!(Scanner, Scanner::default());
    
    // global scanner
    #[macro_export]
    macro_rules! scanner_impl {
        ( $name2:ident, $name:ident
            $(< $( $lt:tt : $clt:tt ),+ >)?
            ( $scanner:ident ) -> $ret_type:ty
            $body:block
        )
             =>
        {
            fn $name2 $(< $( $lt : $clt ),+ >)? ($scanner: &mut Scanner) -> $ret_type
                $body
    
            pub fn $name $(< $( $lt : $clt ),+ >)? () -> $ret_type {
                $name2(crate::scanner::instance())
            }
    
            impl Scanner {
                pub fn $name $(< $( $lt : $clt ),+ >)? ( &mut self ) -> $ret_type {
                    $name2(self)
                }
            }
        };
        ( $name2:ident, $name:ident
            $(< $( $lt:tt : $clt:tt ),+ >)?
            ( $scanner:ident, $( $arg:ident : $type:ty ),* ) -> $ret_type:ty
            $body:block
        )
             =>
        {
            fn $name2 $(< $( $lt : $clt ),+ >)? ( $scanner: &mut Scanner, $( $arg : $type ),* ) -> $ret_type
                $body
    
            pub fn $name $(< $( $lt : $clt ),+ >)? ( $( $arg : $type ),* ) -> $ret_type {
                $name2(crate::scanner::instance(), $( $arg ),* )
            }
    
            impl Scanner {
                pub fn $name $(< $( $lt : $clt ),+ >)? ( &mut self, $( $arg : $type ),* ) -> $ret_type {
                    $name2( self, $( $arg ),* )
                }
            }
        };
    }
    
    scanner_impl!(_scan, scan<T: Token>(sc) -> T {
        use std::io::Write;
        crate::debug!(sc.buffer);
        loop {
            if let Some(token) = sc.buffer.pop() {
                debug_scan(&token);
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            sc.reader.read_line(&mut input).expect("Failed read");
            sc.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    });
    
    #[rustfmt::skip]
    macro_rules! scanner_impl_for_type {
        ($ty:ty, $name:ident) => {
            impl Scanner {
                pub fn $name(&mut self) -> $ty {
                    self.scan()
                }
            }
            impl Token for $ty {
            }
            pub fn $name() -> $ty {
                instance().$name()
            }
        };
        ($ty:ty, $name:ident, $name1:ident) => { 
            scanner_impl_for_type!($ty, $name);
            impl TokenNum for $ty {
            }
            impl Scanner {
                pub fn $name1(&mut self, ofs: $ty) -> $ty { 
                    self.scan1(ofs)
                }
            }
            pub fn $name1(ofs: $ty) -> $ty {
                instance().$name1(ofs)
            }
        };
    }
    
    pub trait Token: std::str::FromStr + std::fmt::Debug {}
    pub trait TokenNum: Token + std::ops::Sub<Output = Self> {}
    
    scanner_impl_for_type!(usize, scan_usize, scan1_usize);
    scanner_impl_for_type!(isize, scan_isize, scan1_isize);
    scanner_impl_for_type!(i32, scan_i32, scan1_i32);
    scanner_impl_for_type!(i64, scan_i64, scan1_i64);
    scanner_impl_for_type!(u32, scan_u32, scan1_u32);
    scanner_impl_for_type!(u64, scan_u64, scan1_u64);
    scanner_impl_for_type!(String, scan_string);
    
    fn debug_scan<T: ToString>(val: T) {
        if crate::output_writer::macro_use::do_debug_scan() {
            let instance = crate::output_writer::macro_use::instance();
            instance.push_tok(val.to_string());
        }
    }
    
    // extensions
    scanner_impl!(_scan1, scan1<T: TokenNum>(sc, ofs: T) -> T {
        sc.scan::<T>() - ofs
    });
    scanner_impl!(_scan_vector, scan_vector<T: Token>(sc, n: usize) -> Vec<T> {
        debug_scan("[");
        let mut v = Vec::with_capacity(n);
        for _ in 0..n { v.push(sc.scan()); }
        debug_scan("]");
        v
    });
    scanner_impl!(_scan_pair, scan_pair<T1: Token, T2: Token>(sc) -> (T1, T2) {
        debug_scan("#p[");
        let t1 = sc.scan();
        let t2 = sc.scan();
        debug_scan("]");
        (t1,t2)
    });
    
