mod output_writer {
    pub mod macro_use {
        use std::io::stdout;
        use std::io::BufWriter;
        use std::io::Stdout;
        use std::io::Write;
        use std::ops::Deref;
        use std::ops::DerefMut;
    
        static mut DEBUG: bool = false;
        static mut DEBUG_SCAN: bool = false;
    
        // OutputWriterImpl
        pub struct OutputWriterImpl {
            inner: BufWriter<Stdout>,
            pending_tokens: Vec<String>,
        }
    
        impl Default for OutputWriterImpl {
            fn default() -> Self {
                unsafe {
                    for arg in std::env::args().skip(1) {
                        match arg.as_str() {
                            "debug" => DEBUG = true,
                            "scan" => DEBUG_SCAN = true,
                            _ => {}
                        }
                    }
                }
                OutputWriterImpl {
                    inner: BufWriter::new(stdout()),
                    pending_tokens: vec![],
                }
            }
        }
        singleton!(OutputWriterImpl, OutputWriterImpl::default());
    
        impl OutputWriterImpl {
            pub fn push_tok(&mut self, tok: String) {
                self.pending_tokens.push(tok);
            }
        }
    
        impl Deref for OutputWriterImpl {
            type Target = BufWriter<Stdout>;
    
            fn deref(&self) -> &Self::Target {
                &instance().inner
            }
        }
    
        impl DerefMut for OutputWriterImpl {
            fn deref_mut(&mut self) -> &mut Self::Target {
                &mut instance().inner
            }
        }
    
        #[rustfmt::skip]
        pub fn start_debug() -> bool {
            crate::output_writer::macro_use::flush_pending_tokens();
            
            let res = unsafe { DEBUG };
            if res { instance().write(b"\x1B[33m").ok(); }
            res
        }
    
        #[rustfmt::skip]
        pub fn do_debug_scan() -> bool {
            unsafe { DEBUG_SCAN }
        }
    
        pub fn end_debug() {
            instance().write(b"\x1B[0m").ok();
        }
    
        pub fn flush_pending_tokens() {
            if do_debug_scan() {
                let mut any = false;
                for (i, ref tok) in instance().pending_tokens.drain(..).enumerate() {
                    let sep = if i == 0 {
                        instance().write(b"\x1B[34m").ok();
                        "DEBUG_SCAN\t"
                    } else {
                        " "
                    };
    
                    let instance = crate::output_writer::macro_use::instance();
                    write!(instance, "{}{}", sep, &tok).ok();
                    any = true;
                }
                if any {
                    crate::output_writer::macro_use::end_debug();
                    let instance = crate::output_writer::macro_use::instance();
                    write!(instance, "\n").ok();
                }
            }
        }
    
        impl Drop for crate::OutputWriter {
            fn drop(&mut self) {
                crate::output_writer::macro_use::flush_pending_tokens();
                instance().inner.flush().expect("flush");
            }
        }
    }
    
    // OutputWriter
    pub struct OutputWriter;
    
    #[macro_export]
    macro_rules! debug {
        () => {
            if crate::output_writer::macro_use::start_debug() {
                let instance = crate::output_writer::macro_use::instance();
                write!(instance, "DEBUG [{}:{}]",
                    file!(), line!()).ok();
                crate::output_writer::macro_use::end_debug();
                write!(instance, "\n").ok();
                instance.flush().ok();
            }
        };
        ($val:expr) => {
            if crate::output_writer::macro_use::start_debug() {
                let instance = crate::output_writer::macro_use::instance();
                write!(instance, "DEBUG [{}:{}] {} = {:?}",
                    file!(), line!(), stringify!($val), &$val).ok();
                crate::output_writer::macro_use::end_debug();
                write!(instance, "\n").ok();
                instance.flush().ok();
            }
        };
        ($val0:expr, $($val:expr),* $(,)?) => {
            if crate::output_writer::macro_use::start_debug() {
                let instance = crate::output_writer::macro_use::instance();
                write!(instance, "DEBUG [{}:{}] {} = {:?}",
                    file!(), line!(), stringify!($val0), &$val0).ok();
                $(write!(instance, "\nDEBUG [{}:{}] {} = {:?}",
                    file!(), line!(), stringify!($val), &$val).ok(); )*
                crate::output_writer::macro_use::end_debug();
                write!(instance, "\n").ok();
                instance.flush().ok();
            }
        };
    }
    
    #[macro_export]
    macro_rules! pp {
        () => {
            crate::output_writer::macro_use::flush_pending_tokens();
            let instance = crate::output_writer::macro_use::instance();
            writeln!(instance).ok()
        };
        ($e:expr $(,)?) => {
            crate::output_writer::macro_use::flush_pending_tokens();
            let instance = crate::output_writer::macro_use::instance();
            writeln!(instance, "{}", $e).ok()
        };
        ($($e:expr),+  $(,)?) => {
            crate::output_writer::macro_use::flush_pending_tokens();
            let instance = crate::output_writer::macro_use::instance();
            $( write!(instance, "{} ", $e).ok(); )+
            writeln!(instance).ok()
        };
        ($($e:expr),*;!) => {
            pp!($($e),*);
            let instance = crate::output_writer::macro_use::instance();
            instance.flush().ok();
        };
    }
    
    #[macro_export]
    macro_rules! pf {
        ($fmt:tt, $($e:expr),*  $(,)?) => {
            crate::output_writer::macro_use::flush_pending_tokens();
            let instance = crate::output_writer::macro_use::instance();
            writeln!(instance, $fmt, $($e),*).ok();
        };
        ($fmt:tt, $($e:expr),*  $(,)?; !) => {
            pf!($fmt,$($e),+);
            let instance = crate::output_writer::macro_use::instance();
            instance.flush().ok();
        };
    }
    
    #[macro_export]
    macro_rules! pps {
        ($v:expr, $ofs:expr) => {
            crate::output_writer::macro_use::flush_pending_tokens();
            let instance = crate::output_writer::macro_use::instance();
            for (i, x) in $v.iter().enumerate() {
                let e = if i + 1 == $v.len() { "\n" } else { " " };
                write!(instance, "{}{}", *x + $ofs, e).ok();
            }
        };
        ($v:expr) => {
            pps!($v, 0)
        };
    }
    
    #[macro_export]
    macro_rules! output_init {
        () => {
            #[warn(unused_variables)]
            let __OUTPUT__ = OutputWriter;
            let _ = instance();
        };
    }
    
