#[allow(dead_code)]
struct Precalc {
    n: usize,
    inv: Vec<ModInt>,
    fact: Vec<ModInt>,
    ifact: Vec<ModInt>,
}

#[allow(dead_code)]
impl Precalc {
    pub fn new(n: usize) -> Precalc {
        let mut inv = vec![ModInt::one(); n + 1];
        let mut fact = vec![ModInt::one(); n + 1];
        let mut ifact = vec![ModInt::one(); n + 1];
        for i in 2..(n + 1) {
            inv[i] = -inv[MOD as usize % i] * ModInt(MOD / i as u32);
            fact[i] = fact[i - 1] * ModInt(i as u32);
            ifact[i] = ifact[i - 1] * inv[i];
        }
        Precalc {
            n: n,
            inv: inv,
            fact: fact,
            ifact: ifact,
        }
    }
    pub fn fact(&self, n: usize) -> ModInt {
        self.fact[n]
    }
    pub fn ifact(&self, n: usize) -> ModInt {
        self.ifact[n]
    }
    pub fn comb(&self, n: usize, k: usize) -> ModInt {
        self.fact[n] * self.ifact[k] * self.ifact[n - k]
    }
    pub fn inv(&self, n: usize) -> ModInt {
        self.inv[n]
    }
}

// ---------- end Precalc ----------
// ---------- begin NTT ----------
fn ntt(f: &mut [ModInt]) {
    let n = f.len();
    assert!(n.count_ones() == 1);
    let len = n.trailing_zeros() as usize;
    for i in 1..(n - 1){
        let mut x = i;
        let mut j = 0;
        for _ in 0..len {
            j = (j << 1) | (x & 1);
            x >>= 1;
        }
        if i < j {
            f.swap(i, j);
        }
    }
    for k in 0..(n.trailing_zeros() as usize) {
        let m = 1 << k;
        let z = ModInt(3).pow((MOD - 1) >> (k + 1) as u32);
        for f in f.chunks_mut(2 * m) {
            let mut q = ModInt::one();
            let (x, y) = f.split_at_mut(m);
            for (x, y) in x.iter_mut().zip(y.iter_mut()) {
                let a = *x;
                let b = q * *y;
                *x = a + b;
                *y = a - b;
                q *= z;
            }
        }
    }
}

fn intt(f: &mut [ModInt]) {
    ntt(f);
    f[1..].reverse();
    let ik = ModInt(f.len() as u32).inv();
    for f in f.iter_mut() {
        *f *= ik;
    }
}

fn multiply(a: &[ModInt], b: &[ModInt]) -> Vec<ModInt> {
    let n = a.len() + b.len() - 1;
    let mut k = 1;
    while k < n {
        k *= 2;
    }
    assert!(k <= (1 << 23));
    let mut f = Vec::with_capacity(k);
    let mut g = Vec::with_capacity(k);
    f.extend_from_slice(a);
    f.resize(k, ModInt::zero());
    ntt(&mut f);
    g.extend_from_slice(b);
    g.resize(k, ModInt::zero());
    ntt(&mut g);
    for (f, g) in f.iter_mut().zip(g.iter()) {
        *f *= *g;
    }
    intt(&mut f);
    f.truncate(n);
    f
}

// ---------- end NTT ----------

fn calc(n: usize, p: ModInt, k: usize) -> Vec<ModInt> {
    if n == 1 {
        let mut ans = vec![ModInt::one()];
        for _ in 1..=k {
            ans.push(p);
        }
        ans
    } else if n % 2 == 1 {
        let mut dp = calc(n - 1, p, k);
        let mut v = calc(1, p, k);
        let pc = Precalc::new(2 * k);
        for i in 0..=k {
            dp[i] *= pc.ifact(i);
            v[i] *= pc.ifact(i);
        }
        let mut ans = multiply(&dp, &v);
        for i in 0..=k {
            ans[i] *= pc.fact(i);
        }
        ans.truncate(k + 1);
        ans
    } else {
        let mut dp = calc(n / 2, p, k);
        let pc = Precalc::new(2 * k);
        for i in 0..=k {
            dp[i] *= pc.ifact(i);
        }
        let mut ans = multiply(&dp, &dp);
        for i in 0..=k {
            ans[i] *= pc.fact(i);
        }
        ans.truncate(k + 1);
        ans
    }
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let m: u32 = it.next().unwrap().parse().unwrap();
    let k: usize = it.next().unwrap().parse().unwrap();
    let ans = calc(n, ModInt(m).inv(), k);
    println!("{}", ans[k]);
}

fn main() {
    run();
}

