    pub fn comb(&self, n: usize, k: usize) -> ModInt {
        if k > n {
            return ModInt::zero();
        }
        self.fact[n] * self.ifact[k] * self.ifact[n - k]
    }
}
// ---------- end ModInt ----------

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let k: usize = it.next().unwrap().parse().unwrap();
    let l: u32 = it.next().unwrap().parse().unwrap();
    let pc = Precalc::new(2 * n + 1);
    let mut dp = vec![ModInt::zero(); 2 * n + 1];
    dp[0] = ModInt::one();
    for i in 0..n {
        for j in (0..=(2 * i)).rev() {
            let p = dp[j];
            dp[j + 2] -= ModInt(2) * p;
            dp[j + 1] += ModInt(2) * p;
            dp[j] = ModInt(0);
        }
    }
    let mut ans = ModInt::zero();
    for i in (k..=n).rev() {
        let mut eval = ModInt::zero();
        for j in 0..=(2 * n) {
            eval += dp[j] * pc.inv(j + 1)
        }
        ans += pc.comb(n, i) * eval;
        let f = ModInt(2).inv();
        let mut next = vec![ModInt::zero(); 2 * n + 1];
        for j in (2..=(2 * n)).rev() {
            let v = dp[j];
            dp[j - 1] += v;
            next[j - 2] = -v * f;
        }
        dp = next;
        for j in (0..=(2 * (n - 1))).rev() {
            let v = dp[j];
            dp[j + 2] += ModInt(2) * v;
            dp[j + 1] -= ModInt(2) * v;
        }
    }
    ans *= ModInt(l);
    println!("{}", ans.0);
}

fn main() {
    run();
}

