fn min_possible_invert(n: u64) -> u64 {
  if n == 0 { return 0; }
  let (top, bot) = (n / 10, n % 10);
  let inv = 9 - bot;
  if top == 0 && inv == 0 {
    bot
  } else {
    min_possible_invert(top) * 10 + std::cmp::min(bot, inv)
  }
}

