fn cols_frequency(cols : &Vec<u64>, freq : &mut Vec<(u64, u64)>) {
    let mut prev_col = cols[0];
    let mut f = 1;
    for i in 1 .. cols.len() {
        let col = cols[i];
        if col == prev_col {
            f = f + 1;
        } else {
            freq.push((prev_col, f));
            f = 1;
            prev_col = col;
        }
    }
    freq.push((prev_col, f));
}

fn host_guest(home_freq : &Vec<(u64, u64)>, away_freq : &Vec<(u64, u64)>) -> u64 {
    let home_len = home_freq.len();
    let away_len = away_freq.len();
    let mut num_clashes = 0;
    let mut i = 0;
    let mut j = 0;
    loop {
        if (i >= home_len) || (j >= away_len) {
            break;
        } else {
            let (h, f_h) = home_freq[i];
            let (a, f_a) = away_freq[j];
            if h == a {
                num_clashes = num_clashes + (f_h * f_a);
                i = i + 1;
                j = j + 1;
            } else if h > a {
                j = j + 1;
            } else {
                i = i + 1;
            }
        }
    }
    num_clashes
}

