        away_cols.push(cols[1]);
    }
    home_cols.sort();
    away_cols.sort();
    let mut home_freq = vec![];
    let mut away_freq = vec![];
    cols_frequency(&home_cols, &mut home_freq);
    cols_frequency(&away_cols, &mut away_freq);
    println!("{}", host_guest(&home_freq, &away_freq));
}

