use std::io::stdin;
use std::cmp::min;
use std::collections::HashMap;
use std::collections::hash_map::Entry;

fn explore(visited: &mut HashMap<i32, i32>, start: i32, finish: i32, dist: i32) -> i32 {
	match visited.entry(start) {
		Entry::Occupied(mut o) => {
			if o.get() > &dist {
				o.insert(dist);
			} else {
				return std::i32::MAX;
			}
		},

		Entry::Vacant(v) => {
			v.insert(dist);
		}
	}

	if start >= finish {
		dist + start - finish
	} else if start == 1 {
		explore(visited, 2, finish, dist + 1)
	} else {
		min(
			explore(visited, start - 1, finish, dist + 1),
			explore(visited, start * 2, finish, dist + 1)
		)
	}
}

