const ARRAY_SIZE: usize = 20000;

fn update_array(f: &mut [Option<usize>; ARRAY_SIZE], x: usize, m: usize, x_stack: &mut Vec<usize>) {
    if x == 0 {
        return;
    }

    if x >= ARRAY_SIZE {
        return;
    }

    let old_value: Option<usize> = f[x];
    let mut new_value: Option<usize> = old_value;
    if x == m {
        new_value = Some(0);
    } else {
        if x > 1 {
            let value_sub1: Option<usize> = f[x + 1];
            if let Some(value_sub1_real) = value_sub1 {
                if let Some(new_value_real) = new_value {
                    if (value_sub1_real + 1) < new_value_real {
                        new_value = Some(value_sub1_real + 1);
                    }
                } else {
                    new_value = Some(value_sub1_real + 1);
                }
            }
        }

        if (x % 2) == 0 {
            let value_mul2: Option<usize> = f[x / 2];
            if let Some(value_mul2_real) = value_mul2 {
                if let Some(new_value_real) = new_value {
                    if (value_mul2_real + 1) < new_value_real {
                        new_value = Some(value_mul2_real + 1);
                    }
                } else {
                    new_value = Some(value_mul2_real + 1);
                }
            }
        }
    }

    f[x] = new_value;

    if new_value != old_value {
        x_stack.push(x - 1);
        x_stack.push(x * 2);
    }
}

fn get_min_path_length(m: usize, n: usize) -> usize {
    if m > n {
        return m - n;
    }

    let mut f: [Option<usize>; ARRAY_SIZE] = [None; ARRAY_SIZE];

    let mut x_stack: Vec<usize> = vec![m];

    while let Some(x) = x_stack.pop() {
        update_array(&mut f, x, m, &mut x_stack);
    }

    return f[n].unwrap();
}

