const MAX_N: i32 = 20000;
const INF: i32 = 10000;

fn main() {
    let input = readln();
    let n = input[0];
    let m = input[1];

    let mut count_clicks: [i32; (MAX_N + 1) as usize] = [INF; (MAX_N + 1) as usize];
    let mut queue: Vec<i32> = vec![n];
    count_clicks[n as usize] = 0;

    let mut i: usize = 0;
    while i < queue.len() {
        let number = queue[i] as i32;
        let index = number as usize;

        if number  - 1 >= 0 && count_clicks[index - 1] > count_clicks[index] + 1 {
            count_clicks[index - 1] = count_clicks[index] + 1;
            queue.push(number - 1);
        }

        if number * 2 <= MAX_N && count_clicks[index * 2] > count_clicks[index] + 1 {
            count_clicks[index * 2] = count_clicks[index] + 1;
            queue.push(number * 2);
        }

        i += 1;
    }

    println!("{}", count_clicks[m as usize]);
}

