        if a == b {
            Ordering::Equal
        } else if a == 1 {
            Ordering::Less
        } else if b == 1 {
            Ordering::Greater
        } else if a == 3 {
            Ordering::Greater
        } else if b == 3 {
            Ordering::Less
        } else if a == 2 || a == 4 {
            if b == 2 || b == 4 {
                Ordering::Equal
            } else {
                Ordering::Greater
            }
        } else if b == 2 || b == 4 {
            Ordering::Less
        } else {
            b.cmp(&a)
        }
    }

    let ans = f_cmp(x, y);
