fn main() {
    let mut input = String::new();
    use std::io::{self, prelude::*};
    io::stdin().read_to_string(&mut input).unwrap();

    let mut it = input.split_whitespace();

    let x: u32 = it.next().unwrap().parse().unwrap();
    let y: u32 = it.next().unwrap().parse().unwrap();

    // x^y <?> y^x
    // exp(y * ln(x)) <?> exp(x * ln(y))
    // y * ln(x) <?> x * ln(y)
    // ln(x) / x <?> ln(y) / y

    struct F {
        x: u32,
    }

    use std::cmp::{Ordering, self};

    impl PartialEq for F {
        fn eq(&self, other: &F) -> bool {
            match (self.x, other.x) {
                (2, 4) | (4, 2) => true,
                (a, b) => a.eq(&b),
            }
        }
    }

    impl Eq for F {}

    impl PartialOrd for F {
        fn partial_cmp(&self, other: &F) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for F {
        fn cmp(&self, other: &F) -> Ordering {
            match (self.x, other.x) {
                (a, b) if F { x: a } == F { x: b } => Ordering::Equal,
                (3, _) => Ordering::Greater,
                (_, 3) => Ordering::Less,
                (2, _) => Ordering::Greater,
                (_, 2) => Ordering::Less,
                (1, _) => Ordering::Less,
                (_, 1) => Ordering::Greater,
                (a, b) => b.cmp(&a),
            }
        }
    }

    let x = F { x: x };
    let y = F { x: y };
    let ans = x.cmp(&y);
    let txt = match ans {
        Ordering::Less => '<',
        Ordering::Equal => '=',
        Ordering::Greater => '>',
    };

    println!("{}", txt);
}

