    impl std::iter::Sum for ModInt {
        #[inline] fn sum<I: Iterator<Item = Self>>(iter: I) -> Self {
            iter.fold(Self::raw(0), std::ops::Add::add)
        }
    }
    impl std::iter::Product for ModInt {
        #[inline] fn product<I: Iterator<Item = Self>>(iter: I) -> Self {
            iter.fold(1.into(), std::ops::Mul::mul)
        }
    }
    impl<'a> std::iter::Sum<&'a Self> for ModInt {
        #[inline] fn sum<I: Iterator<Item = &'a Self>>(iter: I) -> ModInt {
            iter.fold(Self::raw(0), |a, &b| a + b)
        }
    }
    impl<'a> std::iter::Product<&'a Self> for ModInt {
        #[inline] fn product<I: Iterator<Item = &'a Self>>(iter: I) -> ModInt {
            iter.fold(1.into(), |a, &b| a * b)
