        for i in (4..s).step_by(2) {
            a[i] = false;
        }
        for i in (3..s).step_by(2) {
            if !a[i] {
                continue;
            }
            t.push(i);
            if i * i < s {
                for j in ((i * i)..s).step_by(i * 2) {
                    a[j] = false;
                }
            }
        }
        let al = a.len();
        Prime { a, al, t }
    }

    fn is_prime(&self, x: usize) -> bool {
        if x < self.al {
            return self.a[x];
        }

        for c in self.t.iter() {
            if x % c == 0 {
                return false;
            }
        }

        true
    }
}

