    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let read_in = buf.split_whitespace().map(|c| c.trim().parse::<usize>().unwrap()).collect::<Vec<usize>>();
    let (k, n, w) = (read_in[0], read_in[1], read_in[2]);
    let cost = w * (w + 1) / 2 * k;
    let ret: usize;
    if cost <= n {
        ret = 0;
    } else {
        ret = cost - n;
    }
    println!("{}", ret);
}

use std::io::{Read, Write, stdin, stdout};

pub struct Scanner<U: Sized + Read> {
    pub buffer: Vec<String>,
    pub reader: U,
}
impl<U: Sized + Read> Scanner<U> {
    pub fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_to_string(&mut input).expect("Failed read");
            self.buffer = input.lines().rev().map(String::from).collect();
        }
    }

    pub fn new(reader: U) -> Self {
        return Scanner {
            buffer: vec![],
            reader,
        };
    }
}

pub fn solution_of_p546a(input: &mut Read, out: &mut Write) {
    let mut scanner = Scanner::new(input);
    let arr: Vec<usize> = scanner.next::<String>().split(' ').map(|e| {
        e.parse::<usize>().unwrap()
    }).collect();
    let k = arr[0];
    let n = arr[1];
    let w = arr[2];
    let mut s = 0;
    for i in 1..=w {
        s += i * k;
    }
    if s > n {
        write!(out, "{}", s - n).ok();
    } else {
        write!(out, "{}", 0).ok();
    }
}

fn main() {
    solution_of_p546a(&mut stdin(), &mut stdout());
}

