use std::io;
use std::str;

pub struct Scanner<R> {
    reader: R,
    buffer: Vec<String>,
}

impl<R: io::BufRead> Scanner<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![],
        }
    }

    pub fn token<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}

fn get_divisors(n: i64) -> Vec<i64> {
    let mut ans = vec![1];
    if n > 1 {
        ans.push(n);
    }
    let mut d = 2;
    while d * d <= n {
        if n % d == 0 {
            ans.push(d);
            if d * d < n {
                ans.push(n / d);
            }
        }
        d += 1;
    }
    ans.sort();
    ans
}

fn kth_smallest_divisor(n: i64, k: i64) -> i64 {
    let k = k as usize;
    let divisors = get_divisors(n);
    if k >= divisors.len() {
        return -1;
    }
    divisors[k]
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
    let n: i64 = scan.token();
    let k: i64 = scan.token();
    let ans = kth_smallest_divisor(n, k - 1);    
    writeln!(out, "{}", ans).ok();
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());
    solve(&mut scan, &mut out);
}

use std::io;

fn main() {
    let mut input_str = String::new();
    io::stdin().read_line(&mut input_str).expect("read error");

    let input: Vec<i64>  = input_str.split_whitespace()
        .map(|x| x.parse::<i64>().expect("parse error"))
        .collect();

    let n = input[0];
    let k = input[1];

    let mut divisors: Vec<i64> = vec![];
    for divisor in 1..n+1 {
        if divisor * divisor > n { break; }
        if n % divisor == 0 { divisors.push(divisor); }
    }

    let another_divisors: Vec<i64>;
    another_divisors = divisors.iter().map(|x| n / x).filter(|x| x * x != n).rev().collect();

    divisors.extend(another_divisors);

    if (divisors.len() as i64) < k {
        println!("-1");
    } else {
        println!("{}", divisors[k as usize - 1]);
    }
}

fn calculate_nth_divisor(n: i64, k: i64) -> Option<i64> {
    if k > n {
        return None;
    }

    let mut divisors = Vec::<i64>::new();
    let max_small_divisor = (n as f64).sqrt().trunc() as i64;
    let mut count = k;

    for x in 1..=max_small_divisor {
        if n % x == 0 {
            count -= 1;
            divisors.push(x);
        }
        if count == 0 {
            return Some(x);
        }
    }

    let size = divisors.len() as i64;
    let n_is_square = n == divisors.last().unwrap().pow(2);
    if count > size || count == size && n_is_square {
        None
    } else {
        let mut idx = (size as i64 - count) as usize;
        if n_is_square {
            idx -= 1;
        }
        Some(n / divisors[idx])
    }
}

