fn calc_remain(left: i64, k: i64, l: i64, r: i64, a: i64) -> (i64, i64, i64, i64) {
    if (r - l) * k + left < a {
        return (-1, -1, -1, -1);
    }
    let ck = max(0, ((a - left) + k - 1) / k);
    let remain = k * ck + left - a;
    if ck + l < r {
        return (ck, remain, ck+1, k);
    }
    else {
        return (ck, remain, -1, -1);
    }
}

fn main() {
