fn f(k: i64) -> i64 {
    let mut res: i64 = 0;
    let mut n = k;
    loop {
        if n == 0 {
            break;
        }
        if n % 2 == 0 {
            res += n;
        } else {
            res -= n;
        }
        n -= 1;
    }
    return res;

}

fn f_(k: i64) -> i64 {
    let r = (k + 1) / 2;
    if k % 2 == 1 {
        return -r;
    }
    return r;
}

