use std::io::{Read, Write, stdin, stdout};
pub struct Scanner<U: Sized + Read> {
    pub buffer: Vec<String>,
    pub reader: U,
}
impl<U: Sized + Read> Scanner<U> {
    pub fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_to_string(&mut input).expect("Failed read");
            self.buffer = input.lines().rev().map(String::from).collect();
        }
    }

    pub fn new(reader: U) -> Self {
        return Scanner {
            buffer: vec![],
            reader,
        };
    }
}

pub fn solution_of_p122a(input: &mut Read, out: &mut Write) {
    let mut scanner = Scanner::new(input);
    let num = scanner.next::<String>().parse::<usize>().unwrap();
    let lucky_nums = vec![4, 7, 44, 47, 74, 77, 444, 447, 474, 477, 744, 747, 774, 777];
    if is_almose_lucky(num, lucky_nums) {
        write!(out, "YES").ok();
    } else {
        write!(out, "NO").ok();
    }
}

fn is_almose_lucky(num: usize, arr: Vec<usize>) -> bool {
    if arr.contains(&num) {
        return true;
    }
    for item in &arr {
        if num % (*item) == 0 {
            return true;
        }
    }
    return false;
}

fn main() {
    solution_of_p122a(&mut stdin(), &mut stdout());
}

