fn max_moves(moves : &str) -> usize {
    let lrud = "LRUD".as_bytes();
    let left = lrud[0];
    let right = lrud[1];
    let up = lrud[2];
    let down = lrud[3];
    let mut num_left = 0;
    let mut num_right = 0;
    let mut num_up = 0;
    let mut num_down = 0;
    for &b in moves.as_bytes().iter() {
        if b == left {
            num_left = num_left + 1;
        } else if b == right {
            num_right = num_right + 1;
        } else if b == up {
            num_up = num_up + 1;
        } else if b == down {
            num_down = num_down + 1;
        } else {
            panic!("Unknown move!");
        }
    }
    let x = min(num_left, num_right);
    let y = min(num_up, num_down);
    x + x + y + y
}

fn main() {
    let stdin = io::stdin();
    let _ : usize = read_t(&stdin);
    let mut moves = String::new();
    read_line(&stdin, &mut moves);
    let moves = moves.trim();
    let x = max_moves(moves);
    println!("{}", x);
}

