#[derive(Debug, Copy, Clone)]
enum Command {
    U,
    D,
    L,
    R,
}

fn parse() -> Vec<Command> {
    let mut text = String::new();
    stdin().read_line(&mut text).unwrap();
    let fu = |e: char| -> Command {
        match e {
            'U' => Command::U,
            'D' => Command::D,
            'L' => Command::L,
            _ => Command::R,
        }
    };
    let text: Vec<Command> = text.trim().chars().map(fu).collect();
    text
}
fn command_counter(arr: Vec<Command>) -> (usize, usize, usize, usize) {
    let mut uc = 0;
    let mut dc = 0;
    let mut lc = 0;
    let mut rc = 0;
    for i in arr {
        match i {
            Command::U => uc += 1,
            Command::D => dc += 1,
            Command::L => lc += 1,
            Command::R => rc += 1,
        }
    }
    (uc, dc, rc, lc)
}

