    io::stdin().read_to_string(&mut input_text).unwrap();
    let mut iter = input_text.split_whitespace().map(|x| x.parse::<i32>().unwrap());
    let year = iter.next().unwrap();
    let mut new_year = year;
    let mut acc = 0;
    loop {
        new_year += 1;
        acc += if is_leap(new_year) {366 % 7} else {365 % 7};
        if acc >= 7 {
            acc -= 7;
        }
        // println!("year = {}, acc = {}", new_year, acc);
        if acc == 0 && is_leap(year) == is_leap(new_year) {
            break;
        }
    }
    println!("{}", new_year);

}

fn is_leap(year: i32) -> bool {
    year % 400 == 0 || (year % 4 == 0 && year % 100 != 0)
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let y: u32 = s.trim().parse().unwrap();
    let leap = |x: u32| -> bool {
        x % 400 == 0 || (x % 4 == 0 && x % 100 != 0)
    };
    let mut p = 1 + leap(y) as usize;
    let mut q = y + 1;
    while p != 0 || leap(q) != leap(y) {
        p = (p + 1) % 7;
        if leap(q) {
            p = (p + 1) % 7;
        }
        q += 1;
    }
    println!("{}", q);
}

