fn is_leap(n: usize) -> bool {
    n % 400 == 0 || (n % 4 == 0 && n % 100 != 0)
}

fn solve() {
    let n = parse_line!(usize);
    let mut result = n;
    let mut shift = 0;
    loop {
        if is_leap(result) {
            shift = (shift + 366) % 7;
        }else{
            shift = (shift + 365) % 7;
