const W: char = 'W';
const B: char = 'B';

fn parse_problem<B: BufRead>(input: B) -> io::Result<[[u8; 8]; 8]> {
    let mut matrix = [[0; 8]; 8];
    for (i, maybe_line) in input.lines().enumerate().take(8) {
        let line = maybe_line?;
        for (j, c) in line.chars().enumerate().take(8) {
            match c {
                B => matrix[i][j] = 1,
                W => {},
                _ => return Err(io::Error::new(io::ErrorKind::InvalidInput,
                                               "not a B or W")),
            }
        }
    }
    Ok(matrix)
}

