        for j in 0..8 {
            if board[i][j] == 0 {
                continue 'outer_row;
            }
        }
        r += 1;
    }
    'outer_col: for j in 0..8 {
        for i in 0..8 {
            if board[i][j] == 0 {
                continue 'outer_col;
            }
        }
        c += 1;
    }
    let result = if r < 8 && c < 8 { r + c } else { 8 };
