fn div2(x: u64) -> u64{
    if x % 2 == 0 {
        return x / 2;
    } else {
        return x / 2 + 1;
    }
}

fn get_n(n: u64, k: u64) -> u64 {
    if k == n && n % 2 == 0 {
        return n;
    }
    if k <= div2(n) {
        return k * 2 - 1;
    } else {
        return k % div2(n) * 2;
    }
}

