enum BoyOrGirl {
    Boy,
    Girl,
}

impl BoyOrGirl {
    fn new(c : char) -> BoyOrGirl {
        match c {
            'B' => BoyOrGirl::Boy,
            'G' => BoyOrGirl::Girl,
            x => panic!("Cannot convert {} to a BoyOrGirl!", x),
        }
    }
}

impl Debug for BoyOrGirl {
    fn fmt(&self, f : &mut Formatter) -> fmt::Result {
        match *self {
            BoyOrGirl::Boy => write!(f, "B"),
            BoyOrGirl::Girl => write!(f, "G"),
        }
    }
}

fn step(curr : &Vec<BoyOrGirl>, next : &mut Vec<BoyOrGirl>) {
    let l = curr.len();
    let mut i = 0;
    while i <  l {
        match curr[i] {
            BoyOrGirl::Boy => {
                if (i + 1) < l {
                    match curr[i + 1] {
                        BoyOrGirl::Girl => {
                            next.push(BoyOrGirl::Girl);
                            next.push(BoyOrGirl::Boy);
                            i = i + 2;
                        },
                        BoyOrGirl::Boy => {
                            next.push(BoyOrGirl::Boy);
                            i = i + 1;
                        },
                    }
                } else {
                    next.push(BoyOrGirl::Boy);
                    i = i + 1;
                }
            },
            BoyOrGirl::Girl => {
                next.push(BoyOrGirl::Girl);
                i = i + 1;
            }
        }
    }
}

fn print_queue(q : &Vec<BoyOrGirl>) {
    for bg in q {
        print!("{:?}", bg);
    }
    println!();
}

fn main() {
    let stdin = io::stdin();
    let mut n_t : Vec<u64> = vec![];
    read_ts(&stdin, &mut n_t);
    let t = n_t[1];
    let mut s = String::new();
    read_line(&stdin, &mut s);
    let mut queue : Vec<BoyOrGirl> = s.trim().chars().map(|c| BoyOrGirl::new(c)).collect();
    for _ in 0 .. t {
        let mut next = vec![];
        step(&queue, &mut next); 
        queue = next;
    }
    print_queue(&queue);
}

