fn next_round(k: usize, a: &mut [u32]) -> u32 {
    let mut participants = 0;
    let pivot = a[k - 1];
    for i in a {
        if *i > 0 {
            if *i >= pivot {
                participants += 1;
            }
            else {
                break;
            }
        }
    }
    participants
}

