#[derive(PartialEq, Eq, Clone, Debug)]
pub struct Rev<T>(pub T);

impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}

impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn divs(n: i64) -> Vec<i64> {
    let r = (n as f64).sqrt().ceil() as i64;

    let mut xs = vec![];

    for k in 1..r + 1 {
        if n % k == 0 {
            xs.push(k);
        }
    }

    xs
}

fn solve_core(a: i64, b: i64) -> i64 {
    let mut ts = divs(a);
    let ss = ts.iter().rev().map(|&t| a / t).vec();
    ts.extend(ss);

    let ys = divs(a + b);

    // debug!((a, b), ts, ys);

    let mut l = 0;
    let mut r = 0;
    let mut q: BinaryHeap<(Rev<i64>, usize)> = BinaryHeap::new();
    let mut mi = std::i64::MAX;

    for ti in 0..ts.len() {
        let t = ts[ti];

        while l < ys.len() && ys[l] < t {
            l += 1;
        }

        r = max(r, l);

        while r < ys.len() && (a + b) / ys[r] >= a / t {
            let y = ys[r];
            let x = (a + b) / y;
            q.push((Rev(2 * (y + x)), r));

            r += 1;
        }

        while let Some(&(_, yi)) = q.peek() {
            if l <= yi {
                break;
            }

            q.pop();
        }

        // debug!((ti, t, l, r));

        if let Some((Rev(p), _)) = q.pop() {
            // debug!(p);
            mi = min(mi, p);
        }
    }

    mi
}

fn solve(a: i64, b: i64) -> i64 {
    let mut mi = solve_core(a, b);
    if a != b {
        mi = min(mi, solve_core(b, a));
    }
    mi
}

