struct Scanner {
    curr_iter: std::vec::IntoIter<String>,
}

impl Scanner {
    fn get_iter() -> std::vec::IntoIter<String> {
        read().split_whitespace().map(|x| x.to_string())
            .collect::<Vec<_>>().into_iter()
    }

    fn next <E:std::fmt::Debug,T:FromStr<Err=E>> (&mut self) -> T {
        let x = self.curr_iter.next();
        match x {
            Some(y) => { y.parse().unwrap() }
            None => {
                self.curr_iter = Self::get_iter();
                self.next()
            }
        }
    }

    fn new() -> Self {
        Self { curr_iter: Self::get_iter() }
    }
}

