fn bin_pow(n: u64, power: u32) -> u64 {
    if power == 0 {
        return 1;
    } else if power % 2 == 0 {
        return bin_pow(n * n, power / 2);
    } else {
        return n * bin_pow(n, power - 1);
    }
}

