        if s == 0 {
            if m == 1 {
                max_num.push(0);
            } else {
                // Do nothing ...
            }
        } else {
            let mut cur_sum = 0;
            for _ in 0 .. m {
                let diff = s - cur_sum; 
                if diff >= 9 {
                    max_num.push(9);
                    cur_sum = cur_sum + 9;
                } else {
                    max_num.push(diff as u8);
                    cur_sum = cur_sum + diff;
                }
            }
        }
    }
}

