fn main() -> Result<(), Box<dyn std::error::Error>> {
    let data = read_input();
    let (len, sum) = (data[0], data[1]);

    if 9 * len < sum {
        println!("-1 -1");
        return Ok(());
    }

    if sum == 0 {
        if len > 1 {
            println!("-1 -1");
        } else {
            println!("0 0");
        }
        return Ok(());
    }

    if sum == 1 {
        let mut ans = String::with_capacity(len);
        ans.push('1');

        for _ in 1..len {
            ans.push('0');
        }
        println!("{} {}", ans, ans);
        return Ok(());
    }

    if (sum >= 1 && sum <= 9) && (len == 1) {
        println!("{} {}", sum, sum);
        return Ok(());
    }

    if sum % 9 == 0 && sum / 9 == len {
        let mut ans = String::with_capacity(len);
        for _ in 0..len {
            ans.push('9')
        }
        println!("{} {}", ans, ans);
        return Ok(());
    }

    let mut digits = vec![0; len];
    let mut max_digits = vec![0; len];

    let nines = sum / 9;
    let rem = sum % 9;

    let start = len - nines;
    for i in (start..len).rev() {
        digits[i] = 9;
    }

    if len - nines > 1 {
        if rem > 0 {
            digits[start - 1] = rem - 1;
            digits[0] = 1;
        } else {
            digits[start] -= 1;
            digits[0] = 1;
        }
    } else {
        if rem > 0 {
            digits[0] = rem;
        } else {
            digits[start] -= 1;
            digits[0] = 1;
        }
    }

    for i in 0..nines {
        max_digits[i] = 9;
    }
    if rem != 0 {
        max_digits[nines] = rem;
    }

    for d in digits {
        print!("{}", d);
    }
    print!(" ");

    for d in max_digits {
        print!("{}", d);
    }
    println!();

    Ok(())
}

