use std::cmp;

use std::error::Error;

fn solve(mut n: i32, mut m: i32) -> i32 {
    n = cmp::min(n, m);

    let mut res: i32 = 0;
    while m > 0 {
        res += m / n;
        m %= n;
        n = cmp::min(n, m);
    }

    res
}

