macro_rules! read {
    ($stdin:expr, [$t:tt; $n:expr]) => {
        (0..$n).map(|_| read!($stdin, $t)).collect::<Vec<_>>()
    };
    ($stdin:expr, [$t:tt]) => {
        input($stdin)
            .split_whitespace()
            .map(|x| parse!(x, $t))
            .collect::<Vec<_>>()    
    };
    ($stdin:expr, ($($t:tt),*)) => {
        {
            let input = input($stdin);
            let mut iter = input.split_whitespace();    
            ( $( parse!(iter.next().unwrap(), $t) ),* )
        }
    };
    ($stdin:expr, $t:tt) => {
        parse!(input($stdin).trim(), $t)
    };
}

macro_rules! parse {
    ($s:expr, chars) => {
        $s.chars().collect::<Vec<_>>()
    };
    ($s:expr, usize1) => {
        parse!($s, usize) - 1
    };
    ($s:expr, $t:ty) => {
        $s.parse::<$t>().unwrap()
    }
}

