#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct ModInt(i64);

impl ModInt {
    const MOD: i64 = 998_244_353;

    fn new(x: i64) -> ModInt {
        Self(x % Self::MOD)
    }
}

impl std::ops::Add for ModInt {
    type Output = Self;

    fn add(self, other: Self) -> Self {
        let x = self.0 + other.0;
        if x < Self::MOD { Self(x) } else { Self(x - Self::MOD) }
    }
}

impl std::ops::AddAssign for ModInt {
    fn add_assign(&mut self, other: Self) {
        *self = *self + other;
    }
}

impl std::ops::Sub for ModInt {
    type Output = Self;

    fn sub(self, other: Self) -> Self {
        if self.0 < other.0 {
            Self(self.0 + Self::MOD - other.0)
        } else {
            Self(self.0 - other.0)
        }
    }
}

impl std::ops::SubAssign for ModInt {
    fn sub_assign(&mut self, other: Self) {
        *self = *self - other;
    }
}

impl std::ops::Mul for ModInt {
    type Output = Self;

    fn mul(self, other: Self) -> Self {
        Self::new(self.0 * other.0)
    }
}

impl std::ops::MulAssign for ModInt {
    fn mul_assign(&mut self, other: Self) {
        *self = *self * other;
    }
}

impl std::fmt::Display for ModInt {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl std::str::FromStr for ModInt {
    type Err = std::num::ParseIntError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let x = s.parse()?;
        Ok(ModInt(x))
    }
}

impl From<usize> for ModInt {
    fn from(x: usize) -> Self {
        Self(x as i64)
    }
}

impl ModInt {
    fn pow(mut self, mut n: i64) -> Self {
        assert!(n >= 0);
        let mut res = Self(1);
        while n != 0 {
            if n & 1 != 0 {
                res *= self;
            }
            self *= self;
            n >>= 1;
        }
        res
    }

    fn inv(self) -> Self {
        self.pow(Self::MOD - 2)
    }
}

fn solve(stdin: &mut StdinLock, writer: &mut BufWriter<StdoutLock>) {
    let n = read!(stdin, usize);

    let mut sum = [ModInt(0), ModInt(0)];
    let mut a = vec![ModInt(0); n + 1];
    a[0] = ModInt(1);
    for i in 1..=n {
        a[i] = a[i] + a[i - 1];
        if i >= 3 {
            sum[i % 2] += a[i - 3];
            a[i] += sum[i % 2];
        }
    }

    writer.writeln(a[n] * ModInt(2).pow(n as i64).inv());
}

fn main() {
    let stdin = std::io::stdin();
    let mut stdin = stdin.lock();

    let stdout = std::io::stdout();
    let mut writer = BufWriter::new(stdout.lock());

    solve(&mut stdin, &mut writer);
}

