impl Solver {
    fn solve(&mut self, scan: &mut Scanner, out: &mut BufWriter<Stdout>) {
        // 1452d
        let n = scan.u();
        let mut dp = vec![M0;n+2]; // dp[i] : 都市i までが制約を満たす
        let mut dpsum = vec![M0;n+2]; // = dp[i] + dp[i-2] + dp[i-4] + ...

        dp[0] = M1;
        dpsum[0] = dp[0];

        let mut div = M1;
        for i in 1..=n {
            // dp[i] = dp[i-1] + dp[i-3] + dp[i-5] + ... 
            dp[i] = dp[i-1] + if i >= 3 {dpsum[i-3]} else {M0};
            dpsum[i] = dp[i] + if i >= 2 { dpsum[i-2] } else {M0};
            div *= 2;
        }
        //writeln!(out, "{} {} ", dp[n] , div).ok();

        writeln!(out, "{}", dp[n] / div).ok();
    }
}

fn solve() {
    let mut scan = Scanner::new();
    let out = &mut BufWriter::new(stdout());

    let testcase = 1;
    //let testcase: usize = scan.cin();
    for _ in 0..testcase {
        let mut s: Solver = Default::default();
        s.solve(&mut scan, out);
    }
}

fn main() {
    let th = std::thread::Builder::new().stack_size(64 * 1024 * 1024);
    th.spawn(|| solve()).unwrap().join().unwrap()
}

