fn main() -> Result<(), Box<dyn std::error::Error>> {
    let modulo = 998244353;
    let n = read_usize();
    let mut num = 1;
    let mut denom = 4;
    let mut a = 1;
    let mut b = 1;
    for _ in 3..=n {
        let tmp = a + b;
        a = b;
        b = tmp % modulo;
        num = b;
        denom *= 2;
        denom %= modulo;
    }
    if n == 1 {
        denom = 2;
    }
    let (_g, mut denom_inv, _y) = egcd(denom, modulo);
    if denom_inv < 0 {
        denom_inv += modulo;
    }
    println!("{}", (num * denom_inv) % modulo);

    Ok(())
}

