const MOD: u64 = 998244353;

struct Fibo {
    memo: HashMap<u64, u64>,
}

impl Fibo {
    fn new() -> Self {
        let mut memo = HashMap::new();
        memo.insert(0, 1);
        memo.insert(1, 1);
        Self { memo }
    }

    fn get(&mut self, index: u64) -> u64 {
        if let Some(value) = self.memo.get(&index) {
            return *value;
        } else {
            let a = index / 2;
            let b = index - a;
            let result = (self.get(a) * self.get(b) + self.get(a - 1) * self.get(b - 1)) % MOD;
            self.memo.insert(index, result);
            result
        }
    }
}

fn modpow(mut value: u64, mut exp: u64) -> u64 {
    let mut res = 1;

    while exp > 0 {
        if exp & 1 == 1 {
            res = value * res % MOD;
        }
        value = value * value % MOD;
        exp >>= 1;
    }

    res
}

fn run() {
    input! {
        n: u64,
    }

    let result = Fibo::new().get(n - 1) * modpow(modpow(2, n), MOD - 2) % MOD;
    println!("{:?}", result);
}

fn main() {
    run();
}

struct Scanner {
    buffer : std::collections::VecDeque<String>
 }

 impl Scanner {

    fn new() -> Scanner {
       Scanner {
          buffer: std::collections::VecDeque::new()
       }
    }

    fn next<T : std::str::FromStr >(&mut self) -> T {
       if self.buffer.len() == 0 {
          let mut input = String::new();
          std::io::stdin().read_line(&mut input).ok();
          for word in input.split_whitespace() {
             self.buffer.push_back(word.to_string())
          }
       }
       let front = self.buffer.pop_front().unwrap();
       front.parse::<T>().ok().unwrap()
    }

}

fn main() {
    let mut scanner = Scanner::new();
    let n : usize = scanner.next();
    let mut r: Vec<i32> = Vec::new();
    let (mut r_win, mut b_win) = (0, 0);
    for _ in 0..n {
        let num : i32 = scanner.next();
        r.push(num);
    }
    for i in 0..n {
        let num : i32 = scanner.next();
        if num > r[i] {
            b_win += 1;
        } else if num < r[i] {
            r_win += 1;
        }
    }
    if r_win == 0 {
        println!("-1");
    } else {
        println!("{}", b_win / r_win + 1);
    }
}

