    let ra: Vec<usize> = get_input().trim().split(' ').map(|x| x.parse::<usize>().unwrap()).collect();
    let rb: Vec<usize> = get_input().trim().split(' ').map(|x| x.parse::<usize>().unwrap()).collect();
    let mut badv = 0;
    let mut rchn = 0;
    for (rv, bv) in ra.iter().zip(rb) {
        if *rv == 0 && bv == 1 {
            badv += 1;
        } else if *rv == 1 && bv == 0 {
            rchn += 1;
        }
    }

    if rchn == 0 {
        println!("{}", -1);
    } else if badv == 0 {
        println!("{}", 1);
    } else {
        let rwin = badv + 1;
        if rwin % rchn != 0 {
