use std::io::stdin;

#[derive(Default)]
struct Scanner {
    buffer: Vec<String>,
}

impl Scanner {
    fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            stdin().read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}
fn main() {
    let mut scan = Scanner::default();
    let responses = scan.next::<usize>();
    let mut robo_coder_s = String::new();
    stdin().read_line(&mut robo_coder_s).expect("Failed read");
    let robo_coder = robo_coder_s.split_whitespace().collect::<Vec<&str>>();
    let mut bionic_solver_s = String::new();
    stdin()
        .read_line(&mut bionic_solver_s)
        .expect("Failed read");
    let bionic_solver = bionic_solver_s.split_whitespace().collect::<Vec<&str>>();

    let mut only_robo_coder_wins = 0.0;
    let mut only_bionic_solver_wins = 0.0;
    for response in 0..responses {
        match (robo_coder[response], bionic_solver[response]) {
            ("1", "0") => only_robo_coder_wins += 1.0,
            ("0", "1") => only_bionic_solver_wins += 1.0,
            _ => (),
        }
    }
    let robo_code_minimum_points: f64 = if only_robo_coder_wins == 0.0 {
        -1.0
    } else {
        (only_bionic_solver_wins + 1.0) / only_robo_coder_wins
    };
    println!("{}", robo_code_minimum_points.ceil() as i32);
}

