struct ArithSeq {
    a: i64,
    b: i64,
}
impl ArithSeq {
    pub fn new(a: i64, b: i64) -> ArithSeq {
        assert!(b > 0);
        ArithSeq { a: a, b: b }
    }
    #[doc = "a+bi >= x"]
    pub fn next(&self, x: i64) -> i64 {
        if x >= self.a {
            let d = x - self.a;
            let i = (d - 1 + self.b) / self.b;
            self.a + self.b * i
        } else {
            let d = self.a - x;
            let i = d / self.b;
            self.a - self.b * i
        }
    }
    #[doc = "a+bi <= x"]
    pub fn prev(&self, x: i64) -> i64 {
        let next = self.next(x);
        if next == x {
            x
        } else {
            next - self.b
        }
    }
    #[doc = "[a+bi, n] <= [l, u]"]
    pub fn range(&self, l: i64, u: i64) -> Option<(i64, i64)> {
        if l > u {
            return None;
        }
        let x = self.next(l);
        let y = self.prev(u);
        if x > y {
            return None;
        }
        assert!(x <= y);
        if l <= x && x <= u {
            let cnt = (y - x) / self.b;
            Some((x, cnt + 1))
        } else {
            None
        }
    }
}

