    let mut scan = Scanner::default();
    let n = scan.next::<usize>();
    let mut a = Vec::with_capacity(n);
    for _ in 0..n {
        a.push(scan.next::<i32>());
    }
    let mut b = Vec::with_capacity(n);
    for _ in 0..n {
        b.push(scan.next::<i32>());
    }
    let mut num_a = 0;
    let mut num_b = 0;
    for i in 0..n {
        if b[i] == 0 && a[i] == 1 {
