pub fn solve( a: Vec<i32>, b: Vec<i32>) -> Option<i32> {
    let b_score = a.iter().zip(b.iter()).fold(0, |mut acc, (x,y)| {
        if x < y {
            acc += 1;
        }
        acc
    });
    let outperform = a.iter().zip(b.iter()).fold(0, |mut acc, (x,y)| {
        if x > y {
            acc += 1;
        }
        acc
    });
    match outperform {
        0 => None,
        r => Some(b_score / outperform + 1),
    }
}

