fn get_max_division_size(n: u16, a: u16, b: u16, c: u16) -> u16 {
    let mut max_division_size: u16 = 0;

    for num_a in 0..(n / a + 1) {
        let size_left1: u16 = n - num_a * a;
        for num_b in 0..(size_left1 / b + 1) {
            let size_left2: u16 = size_left1 - num_b * b;
            if (size_left2 % c) == 0 {
                let num_c: u16 = size_left2 / c;
                let division_size = num_a + num_b + num_c;
                if division_size > max_division_size {
                    max_division_size = division_size;
                }
            }
        }
    }

    return max_division_size;
}

