use std::collections::HashMap;
use std::io::*;

fn reads<T: std::str::FromStr>(i: &mut StdinLock) -> Vec<T> {
    let mut s = String::new();
    i.by_ref().read_line(&mut s).ok();
    s.trim()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn main() {
    // initialize stdin
    let sin = std::io::stdin();
    let mut sin = sin.lock();
    let sin = &mut sin;

    let params: Vec<i64> = reads(sin);

    let n = params[0];
    let a = params[1];
    let b = params[2];
    let c = params[3];

    let lengths: Vec<i64> = vec![a, b, c];

    let min = *(lengths.iter().min().unwrap());
    if n % min == 0 {
        println!("{}", n / min);
        return;
    }

    let mut memo = HashMap::new();
    memo.insert(0, 0);

    (min..n + 1).for_each(|x| {
        let mut tmp: Vec<i64> = Vec::new();
        for length in &lengths {
            if let Some(val) = memo.get(&(x - length)) {
                tmp.push(val + 1);
            }
        }
        if tmp.len() == 0 {
            return;
        }

        let max_ribons: i64 = tmp.into_iter().max().unwrap();

        memo.insert(x, max_ribons);
    });

    println!("{}", memo.entry(n).or_insert(0));
}

