use std::collections::HashMap;
fn main() {
    let v: Vec<i32> = {
        let mut line = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.trim().split(" ").map(|s| s.parse::<i32>().unwrap()).collect()
    };
    let (n, a, b, c) = (v[0], v[1], v[2], v[3]);

    let mut dp: HashMap<i32, i32> = HashMap::new();
    dp.insert(0, 0);

    for i in 0..n + 1 {
        let mut m = 0;
        if dp.contains_key(&(i - a)) {
            m = std::cmp::max(m, dp[&(i - a)] + 1);
        }
        if dp.contains_key(&(i - b)) {
            m = std::cmp::max(m, dp[&(i - b)] + 1);
        }
        if dp.contains_key(&(i - c)) {
            m = std::cmp::max(m, dp[&(i - c)] + 1);
        }
        if m != 0 {
            dp.insert(i, m);
        }
    }
    println!("{:?}", dp[&n]);
}

