fn minimun_cuts(n: i32, options: &[i32]) -> i32 {
    let mut table = vec![vec![-1; options.len()]; n as usize + 1];

    fn traverse(mut n: i32, options: &[i32], table: &mut Vec<Vec<i32>>) -> i32 {
        for (i, option) in options.iter().enumerate() {
            if table[n as usize][i] == -1 {
                let mut push_value = -5000;
                let conditional = n - option;
                if conditional == 0 {
                    push_value = 1;
                } else if conditional > 0 {
                    n -= option;
                    push_value = 1 + traverse(n, options, table);
                    n += option;
                }
                table[n as usize][i] = push_value;
            }
        }
        *table[n as usize].iter().max().unwrap()
    }

    traverse(n, options, &mut table)
}

