use std::collections::HashSet;
use std::io::stdin;

fn solve(n: i32) -> i32 {
    let mut set = HashSet::new();
    for i in 1i128..=((n as f64).sqrt().floor() as i128) {
        set.insert(i*i);
        if i*i*i <= n as i128 {
            set.insert(i * i * i);
        }
    }
    set.len() as i32
}

