macro_rules! init_lockedio {
    ($cin: expr, $cout: expr) => {{
        (BufReader::new($cin.lock()), BufWriter::new($cout.lock()))
    }};
}
macro_rules! scanf {
    ($buf: expr, $div: expr, $($x: ty), +) => {{
        let mut iter = $buf.split($div);
        ($(iter.next().and_then(|token| token.parse::<$x>().ok()),)*)
    }};
}
macro_rules! scan_array {
    ($buf: expr, $div: expr, $x: ty) => {{
        $buf.split($div)
            .filter(|tok| tok.parse::<$x>().is_ok())
            .map(|tok| tok.parse::<$x>().unwrap())
            .collect::<Vec<$x>>()
    }};
}
macro_rules! getline {
    ($cin: expr, $buf: expr) => {{
        $buf.clear();
        $cin.read_line(&mut $buf)?;
    }};
}
macro_rules! map_or_insert {
    ($map: expr, $key: expr, $fn: expr, $val: expr) => {{
        match $map.get_mut(&$key) {
            Some(v) => {
                $fn(v);
            }
            None => {
                $map.insert($key, $val);
            }
        }
    }};
}
macro_rules! lowbit {
    ($x: expr) => {{
        $x & (!$x + 1)
    }};
}
macro_rules! index {
    ($ch: expr) => {{
        ($ch - b'a') as usize
    }};
}

