                    if cu.pow(3) > x {
                        break;
                    }
                    cu += 1;
                }
                if cu.pow(3) > x { cu -= 1 };
                for _ in 0..x {
                    if sq.pow(2) > x {
                        break;
                    }
                    sq += 1;
                }
                if sq.pow(2) > x { sq -= 1 };
                writeln!(cout, "{0}", sq + cu - si)?;
            }
            n -= 1;
        }
    }
