fn bsearch<F: Fn(i64) -> bool>(mut lo: i64, mut hi: i64, f: F) -> i64 {
    while lo < hi {
        let mi = lo + (hi - lo) / 2;
        if f(mi) {
            hi = mi;
        } else {
            lo = mi + 1;
        }
    }
    hi
}

fn count(m: i64, n: i64) -> i64 {
    bsearch(1, m + 1, |x| {
        let mut y = m;
        for _ in 0..n {
            y /= x
        }
        y == 0
    }) - 1
}

