pub struct Scanner<U: Sized + Read> {
    pub buffer: Vec<String>,
    pub reader: U,
}
impl<U: Sized + Read> Scanner<U> {
    pub fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_to_string(&mut input).expect("Failed read");
            self.buffer = input.lines().rev().map(String::from).collect();
        }
    }

    pub fn new(reader: U) -> Self {
        return Scanner {
            buffer: vec![],
            reader,
        };
    }
}

pub fn solution_of_p131a(input: &mut Read, out: &mut Write) {
    let mut scanner = Scanner::new(input);
    let line = scanner.next::<String>();
    if line.len() == 1 {
        let c = line.chars().nth(0).unwrap();
        if c.is_ascii_uppercase() {
            write!(out, "{}", line.to_ascii_lowercase()).ok();
        } else {
            write!(out, "{}", line.to_ascii_uppercase()).ok();
        }
    } else if only_uppercase(&line) {
        write!(out, "{}", line.to_ascii_lowercase()).ok();
    } else if uppercase_except_first(&line) {
        write!(out, "{}{}", &line[0..1].to_ascii_uppercase(), &line[1..].to_ascii_lowercase()).ok();
    } else {
        write!(out, "{}", line).ok();
    }
}

fn only_uppercase(s: &str) -> bool {
    for c in s.chars() {
        if c.is_ascii_lowercase() {
            return false;
        }
    }
    return true;
}

fn uppercase_except_first(s: &str) -> bool {
    let first_c = s.chars().nth(0).unwrap();
    if first_c.is_ascii_uppercase() {
        return false;
    }
    for c in (&s[1..]).chars() {
        if c.is_ascii_lowercase() {
            return false;
        }
    }
    return true;
}

