const P: i32 = 998244353;

fn mul(x: i32, y: i32) -> i32 {
    ((x as i64) * (y as i64) % (P as i64)) as i32
}

fn add_mul(z: i32, x: i32, y: i32) -> i32 {
    ((z as i64 + (x as i64) * (y as i64)) % (P as i64)) as i32
}

#[allow(unused_variables)]
fn solve(input: &mut FastDynInput<'_>, output: &mut dyn Write) -> io::Result<()> {

    let n = input.iread();
    let x = input.iread();
    let mut res: Vec<Vec<i32>> = vec![vec![0; (x+1) as usize]; (n+1) as usize];
    let mut bin: Vec<Vec<i32>> = vec![vec![0;(n+1) as usize]; (n+1) as usize];
    for i in 0..=n {
        bin[0 as usize][i as usize] = 1;
    }
    for i in 1..=n {
        bin[i as usize][0 as usize] = 1;
        for j in 1..=n {
            bin[i as usize][j as usize] = (bin[(i - 1) as usize][j as usize] + bin[i as usize][(j - 1) as usize]) % P;
        }
    }
    for i in 2..=n {
        for j in 1..=x {
            let mut cur = 1i32;
            if i - 1 >= j {
                for _ in 0..i {
                    cur = mul(cur, j);
                }
            } else {
                for _ in 0..i {
                    cur = mul(cur, i - 1);
                }
                let mut mult = 1i32;
                for left in (2..=i).into_iter().rev() {
                    let next = res[left as usize][(j - i + 1) as usize];
                    cur = add_mul(cur, next, mul(mult, bin[left as usize][(i - left) as usize]));
                    mult = mul(mult, i - 1);
                }
            }
            res[i as usize][j as usize] = cur;
        }
    }
    writeln!(output, "{}", res[n as usize][x as usize])?;
    Ok(())
}

