    let mut dp: Vec<Vec<i64>> = vec![vec![0;MAX];n+1];
    let mut binom: Vec<Vec<i64>> = vec![vec![0;MAX+1];MAX+1];
    let mut pow_mod: Vec<Vec<i64>> = vec![vec![0;MAX+1];MAX+1];
    for a in 1..MAX {
        let mut val = 1;
        for x in 0..MAX {
            pow_mod[a][x] = val;
            val *= a as i64;
            val %= MOD;
        }
    }
    binom[0][0] = 1;
    for i in 1..=MAX {
        binom[i][0] = 1;
        binom[i][i] = 1;
        for j in 1..i {
            binom[i][j] += binom[i-1][j-1];
            binom[i][j] %= MOD;
            binom[i][j] += binom[i-1][j];
            binom[i][j] %= MOD;
        }
    }
    dp[n][0] = 1;
    for r in (1..=n).rev() {
        for lx in 0..=x {
            for y in 0..=(n-r) {
                if lx >= y+r-1 {
                    let d = max(0, min(x-lx+(y+r-1), y+r-1));
                    dp[r][lx] += (((dp[r+y][lx-(y+r-1)]*binom[y+r][y])%MOD)*pow_mod[d][y])%MOD;
                    dp[r][lx] %= MOD;
                }
            }
        }
    }
    let mut all = pow_mod[x][n];
    for lx in 0..=x {
