const MOD: i64 = 998_244_353;

const fn pow(b: i64, mut x: i64) -> i64 {
    let mut m = b;
    let mut ret = 1;
    while x > 0 {
        if (x & 1) > 0 {
            ret = ret * m % MOD;
        }
        m = m * m % MOD;
        x >>= 1;
    }

    ret
}

const fn inverse(n: i64) -> i64 {
    pow(n, MOD - 2)
}

const fn make_factorials() -> ([i64; 501], [i64; 501]) {
    let mut fact = [0; 501];
    let mut inv = [0; 501];

    fact[0] = 1;
    inv[0] = 1;

    let mut i = 1;
    while i <= 500 {
        let j = i as i64;
        fact[i] = fact[i - 1] * j % MOD;
        i += 1;
    }

    inv[500] = inverse(fact[500]);

    let mut i = 499;
    while i > 0 {
        let j = i as i64;
        inv[i] = inv[i + 1] * (j + 1) % MOD;
        i -= 1;
    }

    (fact, inv)
}

fn make_powers() -> [[i64; 501]; 501] {
    let mut powers = [[0; 501]; 501];

    for b in 1..=500 {
        let bi64 = b.try_into().unwrap();
        powers[b][1] = bi64;
        for x in 2..=500 {
            powers[b][x] = powers[b][x - 1] * bi64 % MOD;
        }
    }

    powers
}

const FACTORIALS: ([i64; 501], [i64; 501]) = make_factorials();

fn main() -> Result<()> {
    let mut scanner = Scanner::default();
    let out = &mut std::io::BufWriter::new(std::io::stdout());

    let (fact, inv) = FACTORIALS;
    let powers = make_powers();

    let c = |n, k| fact[n] * inv[k] % MOD * inv[n - k] % MOD;

    let n: usize = scanner.next();
    let x = scanner.next();

    let mut dp = vec![vec![0; x + 1]; n + 1];
    for i in 1..=x {
        dp[1][i] = n.try_into().unwrap();
    }

    for i in 1..n {
        for j in 1..x {
            for k in (i + 1)..=n {
                // dp[i][j] -> dp[k][?]
                let max = (x - j) / (k - 1);
                for l in 1..=max {
                    let nj = j + l * (k - 1);
                    debug_assert!(nj <= x);
                    dp[k][nj] = (dp[k][nj] + dp[i][j] * c(n - i, k - i) % MOD * powers[k - 1][k - i] % MOD) % MOD;
                }
            }
        }
    }

    let sum = dp[n].iter().fold(0, |acc, x| (acc + x) % MOD);
    let ret = (pow(x.try_into().unwrap(), n.try_into().unwrap()) + MOD - sum) % MOD;

    writeln!(out, "{}", ret)?;

    Ok(())
}

