#[derive(Copy, Clone)]
struct ModGroup {
    val: usize,
}
impl ModGroup {
    const MOD: usize = 998244353;
    const MOD64: i64 = Self::MOD as i64;

    fn new(v: usize) -> Self {
        Self { val: v }
    }

    fn from_usize(v: usize) -> Self {
        Self { val: v % Self::MOD }
    }

    fn from_i64(v: i64) -> Self {
        Self {
            val: (v % Self::MOD64) as usize,
        }
    }

    fn pow(self, mut p: usize) -> Self {
        let mut base = self;
        let mut res = Self::new(1);
        while p > 0 {
            if p % 2 > 0 {
                res = res * base;
            }
            base = base * base;
            p /= 2;
        }

        res
    }

    fn inv(self) -> Self {
        self.pow(Self::MOD - 2)
    }
}

impl ops::Add<usize> for ModGroup {
    type Output = Self;

    fn add(self, other: usize) -> Self {
        Self::from_usize(self.val + other)
    }
}
impl ops::Add<ModGroup> for ModGroup {
    type Output = Self;

    fn add(self, other: Self) -> Self {
        self + other.val
    }
}
impl ops::Sub<usize> for ModGroup {
    type Output = Self;

    fn sub(self, other: usize) -> Self {
        Self::new(if self.val >= other {
            self.val - other
        } else {
            self.val + Self::MOD - other
        })
    }
}
impl ops::Sub<ModGroup> for ModGroup {
    type Output = Self;

    fn sub(self, other: Self) -> Self {
        self - other.val
    }
}
impl ops::Mul<usize> for ModGroup {
    type Output = Self;

    fn mul(self, other: usize) -> Self {
        Self::from_i64(self.val as i64 * other as i64)
    }
}
impl ops::Mul<ModGroup> for ModGroup {
    type Output = Self;

    fn mul(self, other: Self) -> Self {
        self * other.val
    }
}
impl ops::Div<usize> for ModGroup {
    type Output = Self;

    fn div(self, other: usize) -> Self {
        self * Self::new(other).inv()
    }
}
impl ops::Div<ModGroup> for ModGroup {
    type Output = Self;

    fn div(self, other: Self) -> Self {
        self * other.inv()
    }
}

fn main() -> io::Result<()> {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout);

    const N: usize = 501;

    let fact = {
        let mut fact = vec![ModGroup::from_usize(1); N];
        for i in 1..N {
            fact[i] = fact[i - 1] * i;
        }
        fact
    };
    let bin_coef = {
        let mut bin_coef = vec![vec![ModGroup::from_usize(0); N]; N];
        for i in 1..N {
            for j in 1..=i {
                bin_coef[i][j] = fact[i] / (fact[j] * fact[i - j]);
            }
        }
        bin_coef
    };
    let pow_n = {
        let mut pow_n = vec![vec![ModGroup::from_usize(1); N]; N];
        for i in 1..N {
            for j in 1..N {
                pow_n[i][j] = pow_n[i][j - 1] * i;
            }
        }
        pow_n
    };

    let (n, m): (usize, usize) = (scan.t(), scan.t());
    let mut dp = vec![vec![ModGroup::from_usize(0); m + 1]; m + 1];
    for h in 1..=m {
        dp[h][h] = pow_n[h - 1][h - 1] * h;
        for d in 2..h {
            let mut cur = dp[d][d];
            let h1 = h - d + 1;
            for k in 2..=d {
                cur = cur + dp[h1][k] * bin_coef[d][k] * pow_n[d - 1][d - k];
            }

            dp[h][d] = cur;
        }
    }

    let mut res = ModGroup::from_usize(0);
    if m >= n {
        for i in 1..=m {
            res = res + dp[i][n];
        }
    }
    res = pow_n[m][n] - res;
    writeln!(out, "{}", res.val)?;

    io::Result::Ok(())
}

