            for next_alive in cur_alive..=n {
                let cur_dp = dp[cur_alive][cur_max_hp];
                let new_people = next_alive - cur_alive;
                let damage = next_alive - 1;
                if cur_max_hp + damage > x {
                    break;
                }

                let c = comb.get(n - cur_alive, new_people);
                let d = ModInt::from(damage).pow(new_people);
                dp[next_alive][cur_max_hp + damage] += cur_dp * c * d;
            }
        }
    }

    let mut ans = ModInt::from(0);
    for x in 0..=x {
        ans += dp[n][x];
    }
    println!("{}", ans.value());

