const MOD: u64 = 998244353;

fn fastpow(mut a: u64, mut x: u64) -> u64 {
    let mut r = 1;
    while x != 0 {
        if x & 1 != 0 {
            r = (r * a) % MOD;
        }

        a = (a * a) % MOD;
        x >>= 1;
    }
    r
}

fn modinv(x: u64) -> u64 {
    fastpow(x, MOD - 2)
}

fn solve(io: &mut IO) -> Result<()> {
    let (n, x): (usize, usize) = (io.read(), io.read());
    let mut comb = vec![vec![1; n + 1]; n + 1];
    let mut comb2 = vec![vec![1; n + 1]; n + 1];
    let mut fact = vec![1; n + 1];

    for i in 1..=n {
        fact[i] = (fact[i - 1] * (i as u64)) % MOD;

        for j in 1..=i {
            let rem = (fact[j] * fact[i - j]) % MOD;
            let rinv = modinv(rem);

            comb[i][j] = (fact[i] * rinv) % MOD;

            comb2[i][j] = fastpow(i as u64 - 1, j as u64) * comb[i][j] % MOD;
        }
    }

    let mut dp = vec![vec![0; x + 1]; n + 1];
    dp[0] = vec![1; x + 1];

    for k in 2..=n {
        let mut sum = 0u64;
        for y in 1..=min(k - 1, x) {
            dp[k][y] = (fastpow(y as u64, k as u64) + MOD - sum) % MOD;
            sum = (sum + dp[k][y]) % MOD
        }

        for y in k..=x {
            let mut val = dp[k][y - (k - 1)];

            for i in 1..k {
                let a = dp[k - i][y - (k - 1)] * comb2[k][i] % MOD;
                val = (val + a) % MOD;
            }
            dp[k][y] = val;
        }
    }

    let mut cnt = 0;
    for y in 1..=x {
        cnt = (cnt + dp[n][y]) % MOD;
    }

    writeln!(io.out, "{}", cnt % MOD)
}

