static M: i64 = 1000_000_007;

fn exponentiate( base: i64, mut exponent: i64 ) -> i64 {
    let mut ans = 1;
    let mut accum = base;
    while exponent != 0 {
        if exponent & 1 != 0 {
            ans = (ans * accum) % M;
        }
        accum = (accum * accum) % M;
        exponent = exponent >> 1;
    }
    ans
}

