fn can_remove(index: usize, phrase: &mut Vec<char>) -> bool {
    let phrase_length = phrase.len();
    let (current, previous, next) = (
        phrase[index] as i32,
        if index == 0 {
            phrase[index] as i32
        } else {
            phrase[index - 1] as i32
        },
        if index == (phrase_length - 1) {
            phrase[index] as i32
        } else {
            phrase[index + 1] as i32
        },
    );
    (current as i32 - next as i32) == 1 || (current as i32 - previous as i32) == 1
}

