    let mut bigger = 'a' as i32 - 1;
    let mut candidate: usize = 101;
    for (i, charac) in phrase.clone().iter().enumerate() {
        if *charac as i32 > bigger && can_remove(i, phrase) {
            candidate = i;
            bigger = *charac as i32;
        }
    }
    if candidate == 101 {
        false
    } else {
        phrase.remove(candidate);
        true
    }
}
