pub fn solve(s: String, ch: char) -> String {
    if &s == "" {
        return "".to_string();
    }
    let mut result = 0;
    let segments = s.split(ch).map(|s| s.to_string()).collect::<Vec<String>>();
    let mut new_string = String::new();
    for segment in segments.iter().cloned() {
        new_string += &solve(segment, (ch as u8 + 1) as char);
        new_string += &ch.to_string();
    }
    new_string.pop();

    let pattern1 = ch.to_string() + &((ch as u8 + 1) as char).to_string();
    let pattern2 = ((ch as u8 + 1) as char).to_string() + &ch.to_string();
    while {
        let len = new_string.len();
        new_string = new_string.replace(&pattern1, &ch.to_string());
        new_string = new_string.replace(&pattern2, &ch.to_string());
        len != new_string.len()
    } {}
    //println!("{} - {}", s, new_string);

    new_string
}

