fn calculate_divs(mut x: u32) -> Vec<u32> {
  let mut divs: Vec<u32> = Vec::new();
    for p in 2..100_000 {
    if x % p == 0 {
      divs.push(p);
      while x % p == 0 {
        x /= p;
      }
    }
  }
  if x > 1 {
    divs.push(x);
  }
  return divs;
}

const MOD: u64 = 1_000_000_007;

fn bin_pow(mut a: u64, mut n: u64) -> u64 {
  let mut x: u64 = 1;
  while n > 0 {
    if (n & 1) == 1 {
      x = x * a % MOD;
    }
    a = a * a % MOD;
    n >>= 1;
  }
  return x;
}

