const MOD: u64 = 1000000007;

fn mod_pow(mut a: u64, mut n: u64) -> u64 {
    let mut result = 1;
    while n != 0 {
        if n % 2 == 1 {
            result = result * a % MOD;
        }
        a = a * a % MOD;
        n /= 2;
    }
    return result;
}

fn calc(p: u64, mut n: u64) -> u64 {
    let mut cnt = 0;
    while n != 0 {
        n /= p;
        cnt += n;
    }
    return mod_pow(p, cnt);
}

fn solve(writer: &mut std::io::BufWriter<std::io::Stdout>) {
    let (mut x, n) = parse_line!(u64, u64);
    let mut result = 1;
    for i in 2..=x {
        if i * i > x {
            break;
        }
        if x % i == 0 {
            x /= i;
            while x % i == 0 {
                x /= i;
            }
            result = result * calc(i, n) % MOD;
        }
    }
    if x != 1 {
        result = result * calc(x, n) % MOD;
    }
    writeln!(writer, "{}", result).unwrap();
}

