type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

struct Scanner<'a, R> {
    reader: R,
    buf_str: Vec<u8>,
    buf_iter: SplitAsciiWhitespace<'a>,
}

impl<R: BufRead> Scanner<'_, R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_ascii_whitespace(),
        }
    }

    fn try_token<T>(&mut self) -> Result<T>
        where T: FromStr,
              <T as FromStr>::Err: 'static + std::error::Error
    {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return Ok(token.parse()?);
            }
            self.buf_str.clear();
            let bytes_read = self.reader
                .read_until(b'\n', &mut self.buf_str)?;
            if bytes_read == 0 {
                return Err(Box::new(io::Error::from(io::ErrorKind::UnexpectedEof)));
            }
            self.buf_iter = unsafe {
                let slice = str::from_utf8_unchecked(&self.buf_str);
                ::std::mem::transmute(slice.split_ascii_whitespace())
            }
        }
    }

    fn token<T>(&mut self) -> T
        where T: FromStr,
              <T as FromStr>::Err: 'static + std::error::Error
    {
        self.try_token().unwrap()
    }

    fn line_str(&mut self) -> &str {
        self.buf_str.clear();
        let bytes_read = self.reader
            .read_until(b'\n', &mut self.buf_str)
            .expect("Failed read");
        if bytes_read == 0 { panic!("unexpected EOF"); }
        unsafe { str::from_utf8_unchecked(self.buf_str.as_slice()) }
            .trim()
    }

    fn line_token<T: FromStr>(&mut self) -> T {
        self.line_str()
            .parse().ok().expect("Failed parse")
    }
}

const MOD: u64 = 1e9 as u64 + 7;

fn solve<R: BufRead, W: Write>(mut scan: Scanner<R>, mut output: W) {
    let x: u32 = scan.token();
    let n: u64 = scan.token();
    let mut answer: u64 = 1;
    prime_divs_distinct(x, |prime| {
        let prime = prime as u64;
        let mut k = 0;
        let mut factor = prime;
        while factor <= n {
            k += n / factor;
            factor = factor.saturating_mul(prime);
        }
        answer = (answer * mod_pow(prime, k)) % MOD;
    });
    writeln!(output, "{}", answer);
}

fn prime_divs_distinct<F>(mut n: u32, mut prime: F)
    where F: FnMut(u32)
{
    if n & 1 == 0 {
        prime(2);
        n >>= 1;
    }
    while n & 1 == 0 { n >>= 1; }
    let mut f = 3;
    let mut prev_f = 0;
    while f * f <= n {
        if n % f == 0 {
            if f != prev_f {
                prime(f);
                prev_f = f;
            }
            n /= f;
        } else {
            f += 2;
        }
    }
    if n != 1 && n != prev_f { prime(n); }
}

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1;
    base %= MOD;
    while exp > 0 {
        if exp & 1 == 1 {
            result = (result * base) % MOD;
        }
        exp >>= 1;
        base = (base * base) % MOD;
    }
    result
}


