const M: u64 = 1e9 as u64 + 7;

fn solve<R: BufRead, W: Write>(mut scan: Scanner<R>, mut output: W) {
    let n: u64 = scan.token();
    let k: u64 = scan.token();
    let k_1 = k - 1;
    let kp3 = mpow(k_1, n);
    let mut sum = mpow((mpow(k, n) + (M - kp3)) % M, n);
    let mut bcf = 1;
    let mut kp2 = 1;
    for i in 1..=n {
        bcf = (n - i + 1) * mpow(i, M - 2) % M * bcf % M;
        let kp1 = mpow(k, n - i);
        kp2 = kp2 * k_1 % M;
        sum = (sum + mpow(M - 1, i & 1) * bcf % M * mpow((kp1 * kp2 % M + (M - kp3)) % M, n) % M) % M;
    }
    writeln!(output, "{}", sum).unwrap();
}

pub fn mpow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1;
    while exp > 0 {
        if exp & 1 == 1 {
            result = (result * base) % M;
        }
        exp >>= 1;
        base = (base * base) % M;
    }
    result
}

