const MOD: u64 = 1_000_000_007;

fn bin_pow(mut a: u64, mut n: u64) -> u64 {
  let mut x: u64 = 1;
  while n > 0 {
    if (n & 1) == 1 {
      x = x * a % MOD;
    }
    a = a * a % MOD;
    n >>= 1;
  }
  return x;
}

fn rev(a: u64) -> u64 {
  return bin_pow(a, MOD - 2);
}


fn main() {
  let mut scan = Scanner::new();
  let n: usize = scan.next();
  let x: usize = scan.next();

  let mut f: Vec<u64> = vec![0; 1000];
  f[0] = 1;
  for i in 1..1000 {
    f[i] = f[i - 1] * (i as u64) % MOD;
  }

  let mut rf: Vec<u64> = vec![0; 1000];
  for i in 0..1000 {
    rf[i] = rev(f[i]);
  }

  let mut px: Vec<u64> = vec![0; 1000];
  px[0] = 1;
  for i in 1..1000 {
    px[i] = px[i - 1] * ((x-1) as u64) % MOD;
  }

  let c = |n, k|{ f[n] * rf[n-k] % MOD * rf[k] % MOD };

  let mut dp: Vec<Vec<u64>> = vec![vec![0; n + 1]; n + 1];
  dp[0][0] = 1;
  for ones_now in 1..(n+1) {
    for ones_before in 0..(ones_now+1) {
      let mut ways: u64 = 0;
      for place_non_one in 0..std::cmp::min(ones_before + 1, ones_now) {
        ways += px[place_non_one] * rf[place_non_one] % MOD * rf[ones_before - place_non_one] % MOD;
      }
      ways %= MOD;
      ways = ways * f[ones_before] % MOD;
      ways = ways * c(n-ones_before, ones_now-ones_before) % MOD;
      ways = ways * px[n-ones_now] % MOD;
      for i in 1..(n+1) {
        dp[i][ones_now] = (dp[i][ones_now] + dp[i-1][ones_before] * ways) % MOD;
      }
    }
  }

  println!("{}", dp[n][n]);
}

