const m:i64 = 1000000007;

fn main() {
	let mut inp = Iinput::default();
	let out = &mut BufWriter::new(stdout());
	let n:usize = inp.scan::<usize>();
	let k:i64 = inp.scan::<i64>();
	let mut nCr = vec![vec![0 as i64; n + 1]; n + 1];
	nCr[0][0] = 1;
	for i in 1..n+1 {
		for j in 0..i+1 {
			if j > 0 {
				nCr[i][j] += nCr[i - 1][j - 1];
			}
			if j < i {
				nCr[i][j] += nCr[i - 1][j];
			}
			nCr[i][j] %= m;
		}
	}
	let mut dp = vec![0; n + 1];
	dp[0] = 1;
	let mut pow2 = vec![1 as i64; n + 1];
	for i in 1..n+1 {
		pow2[i] = pow2[i - 1] * (k - 1) % m;
	}
	for _row in 0..n {
		let mut tp = vec![0; n + 1];
		let mut powa = 1 as i64;
		for i in 0..n+1 {
			for j in i..n+1 {
				let mut val = pow2[n - j] * powa % m;
				if i == j {
					val += m - pow2[n];
				}
				val = val * nCr[n - i][n - j] % m;
				tp[j] = (tp[j] + val * dp[i]) % m;
			}
			powa = powa * k % m;
		}
		dp = tp;
	}
	writeln!(out, "{}", dp[n]);
}

