        .map(|x| x.as_bytes().to_vec())
        .collect::<Vec<_>>();
    let p1 = b'X';
    let p2 = b'0';
    let p1_count = count(&board, p1);
    let p2_count = count(&board, p2);
    let p1_win = win(&board, p1);
    let p2_win = win(&board, p2);
    if p1_count < p2_count || p1_count > p2_count + 1 || p1_win && p2_win {
