fn count(board: &Vec<Vec<u8>>, c: u8) -> usize {
    board
        .iter()
        .map(|xs| xs.iter().filter(|&&x| x == c).count())
        .sum()
}

fn win(board: &Vec<Vec<u8>>, c: u8) -> bool {
    (0..3).any(|i| (0..3).all(|j| board[i][j] == c))
        || (0..3).any(|j| (0..3).all(|i| board[i][j] == c))
        || (0..3).all(|i| board[i][i] == c)
        || (0..3).all(|i| board[i][2 - i] == c)
}

