struct Scanner<R> {
    reader: R,
    buf_str: Vec<u8>,
    buf_iter: std::str::SplitAsciiWhitespace<'static>,
}

impl<R: std::io::BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_ascii_whitespace(),
        }
    }
    fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = std::str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_ascii_whitespace())
            }
        }
    }
}

enum Answer {
    Illegal,
    First,
    Second,
    FirstWon,
    SecondWon,
    Draw,
}

fn solve(b: [[u8; 3]; 3]) -> Answer {
    let mut cnt1 = 0;
    let mut cnt2 = 0;
    for i in 0..3 {
        for j in 0..3 {
            if b[i][j] == 'X' as u8 {
                cnt1 += 1;
            } else if b[i][j] == '0' as u8 {
                cnt2 += 1;
            }
        }
    }

    if !(cnt1 == cnt2 || cnt1 == cnt2 + 1) {
        return Answer::Illegal;
    }

    let win_check = |p: u8| {
        for i in 0..3 {
            if b[i][0] == p && b[i][1] == p && b[i][2] == p {
                return true;
            }
            if b[0][i] == p && b[1][i] == p && b[2][i] == p {
                return true;
            }
        }
        return b[1][1] == p && ((b[0][0] == p && b[2][2] == p) || (b[0][2] == p && b[2][0] == p));
    };
    let first_won = win_check('X' as u8);
    let second_won = win_check('0' as u8);
    if first_won && second_won {
        return Answer::Illegal;
    }
    if first_won {
        if cnt1 == cnt2 {
            return Answer::Illegal;
        }
        return Answer::FirstWon;
    }
    if second_won {
        if cnt1 == cnt2 + 1 {
            return Answer::Illegal;
        }
        return Answer::SecondWon;
    }

    let mut is_finished = true;
    for i in 0..3 {
        for j in 0..3 {
            if b[i][j] == '.' as u8 {
                is_finished = false;
            }
        }
    }

    if is_finished {
        return Answer::Draw;
    }

    if cnt1 == cnt2 {
        Answer::First
    } else {
        Answer::Second
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let (stdin, stdout) = (std::io::stdin(), std::io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = std::io::BufWriter::new(stdout.lock());

    let mut a: Vec<String> = vec![];
    a.push(scan.next());
    a.push(scan.next());
    a.push(scan.next());

    let mut b: [[u8; 3]; 3] = [[0; 3]; 3];
    for i in 0..3 {
        b[i] = a[i].as_bytes().try_into().unwrap();
    }

    writeln!(
        out,
        "{}",
        match solve(b) {
            Answer::Illegal => "illegal",
            Answer::First => "first",
            Answer::Second => "second",
            Answer::FirstWon => "the first player won",
            Answer::SecondWon => "the second player won",
            Answer::Draw => "draw",
        }
    )?;

    Ok(())
}

use std::io;
use std::io::Stdin;

const DIMENSION : usize = 3;
const NUM_SQUARES : usize = DIMENSION * DIMENSION;
const BLANK : u64 = 0;
const X : u64 = 1;
const O : u64 = 10;

fn read_line(stdin : &Stdin, line : &mut String) {
    match stdin.read_line(line) {
        Ok(_) => return,
        Err(msg) => panic!("Could not read line! Message: {}.", msg),
    }
}

fn read_board(stdin : &Stdin, board : &mut [[u64; DIMENSION]; DIMENSION]) {
    for i in 0 .. DIMENSION {
        let mut row = String::new();
        read_line(stdin, &mut row);
        let mut j = 0;
        for c in row.trim().chars() {
            if c == '.' {
                board[i][j] = BLANK;
            } else if c == 'X' {
                board[i][j] = X;
            } else if c == '0' {
                board[i][j] = O;
            } else {
                panic!("Unknown square on board: {}", c);
            }
            j = j + 1;
        }
    }
}

fn has_player_won(board: &[[u64; DIMENSION]; DIMENSION], player : u64) -> bool {
    let three_p = 3 * player;
    let row_0 = (board[0][0] + board[0][1] + board[0][2]) == three_p;
    let row_1 = (board[1][0] + board[1][1] + board[1][2]) == three_p;
    let row_2 = (board[2][0] + board[2][1] + board[2][2]) == three_p;
    let col_0 = (board[0][0] + board[1][0] + board[2][0]) == three_p;
    let col_1 = (board[0][1] + board[1][1] + board[2][1]) == three_p;
    let col_2 = (board[0][2] + board[1][2] + board[2][2]) == three_p;
    let dia_1 = (board[0][0] + board[1][1] + board[2][2]) == three_p;
    let dia_2 = (board[0][2] + board[1][1] + board[2][0]) == three_p;
    row_0 || row_1 || row_2 || col_0 || col_1 || col_2 || dia_1 || dia_2
}

fn has_first_player_won(board : &[[u64; DIMENSION]; DIMENSION]) -> bool {
    has_player_won(board, X)
}

fn has_second_player_won(board : &[[u64; DIMENSION]; DIMENSION]) -> bool {
    has_player_won(board, O)
}

fn print_board_state(board : &[[u64; DIMENSION]; DIMENSION]) {
    let mut num_x : i64 = 0;
    let mut num_o : i64 = 0;
    for i in 0 .. DIMENSION {
        for j in 0 .. DIMENSION {
            if board[i][j] == X {
                num_x = num_x + 1;
            } else if board[i][j] == O {
                num_o = num_o + 1;
            } else {
                // Do nothing ...
            }
        }
    }
    let sum = (num_x + num_o) as usize;
    let diff = num_x - num_o;
    let first_player_won = has_first_player_won(&board);
    let second_player_won = has_second_player_won(&board);
    if diff == 0 {
        if first_player_won {
            println!("illegal");
        } else if second_player_won {
            println!("the second player won");
        } else {
            println!("first");
        }
    } else if diff == 1 {
        if second_player_won {
            println!("illegal");
        } else if first_player_won {
            println!("the first player won");
        } else {
            if sum == NUM_SQUARES {
                println!("draw");
            } else {
                println!("second");
            }
        }
    } else {
        println!("illegal");
    }
}

fn main() {
    let stdin = io::stdin();
    let mut board = [[BLANK; DIMENSION]; DIMENSION];
    read_board(&stdin, &mut board);
    print_board_state(&board);
    // println!("{:?}", board);
}

use std::io;
use std::io::prelude::*;

const PRIMES: [u128; 8] = [2, 3, 5, 7, 11, 13, 17, 19];
const WEIGHTS: [u128; 9] = [
    2 * 7 * 17,
    2 * 11,
    2 * 13 * 19,
    7 * 3,
    11 * 3 * 19 * 17,
    3 * 13,
    5 * 7 * 19,
    5 * 11,
    5 * 13 * 17,
];

fn count_powers_of(x: u128, y: u128) -> u128 {
    let mut x = x;
    let mut n = 0;
    while x != 0 && x % y == 0 {
        n += 1;
        x /= y;
    }
    n
}

fn ix(c: char) -> usize {
    match c {
        'X' => 1,
        _ => 0,
    }
}

fn main() {
    let stdin = io::stdin();
    let lines = stdin.lock().lines();
    let board = lines.map(|r| r.unwrap()).take(3).collect::<String>();
    let mut count = vec![0, 0];
    let mut prod = vec![1u128, 1];
    let mut wins = vec![0, 0];
    for (i, c) in board.chars().enumerate().filter(|p| p.1 != '.') {
        count[ix(c)] += 1;
        prod[ix(c)] *= WEIGHTS[i];
    }
    for i in 0..2 {
        for p in PRIMES.iter() {
            if count_powers_of(prod[i], *p) == 3 {
                wins[i] += 1;
            }
        }
    }
    if count[0] != count[1] && count[0] != count[1] - 1
        || wins[0] > 2
        || wins[1] > 2
        || wins[0] * wins[1] != 0
        || wins[0] > 0 && count[0] != count[1]
        || wins[1] > 0 && count[0] != count[1] - 1
    {
        println!("illegal");
    } else if count[0] == 4 && count[1] == 5 && wins[0] + wins[1] == 0 {
        println!("draw");
    } else if wins[0] > 0 {
        println!("the second player won");
    } else if wins[1] > 0 {
        println!("the first player won");
    } else if count[0] == count[1] {
        println!("first");
    } else {
        println!("second");
    }
}

