fn test_case<W: Write>(sc: &mut input::In, out: &mut std::io::BufWriter<W>) {
    let n: usize = sc.read();
    let m: usize = sc.read();
    let modd: usize = 998244353;
    let mut prime: Vec<bool> = vec![true; n + 1];
    for i in 2..(n + 1) {
        if prime[i] {
            for j in i..(n / i + 1) {
                prime[j * i] = false;
            }
        }
    }
    let mut ans: usize = 0;

    let mut mul = m % modd;
    let mut cnt = m % modd;
    let mut lcm: usize = 1;
    for i in 2..(n + 1) {
        let mut t = 0;
        cnt = cnt * (m % modd) % modd;
        if lcm <= m {
            if prime[i] {
                lcm *= i;
            }
            t = m / lcm;
        }
        mul = mul * (t % modd) % modd;
        ans = (ans + modd + cnt - mul) % modd;
    }

    writeln!(out, "{}", ans);
}

