type Mint = ModInt998244353;

fn main() {
    let mut sc = Scanner::new();
    let n: u64 = sc.next_num();
    let m: u64 = sc.next_num();

    let mut is_prime = vec![true; n as usize + 1];
    is_prime[1] = false;
    for i in 2..n + 1 {
        if !is_prime[i as usize] {
            continue;
        }
        let mut k = 2;
        while i * k <= n {
            is_prime[(i * k) as usize] = false;
            k += 1;
        }
    }

    let mut ans = Mint::from(0);
    let mut pow_m = Mint::from(1);
    let mut tmp = Mint::from(1);
    let mut l = 1;
    for i in 1..=n {
        if l <= m && is_prime[i as usize] {
            l *= i;
        }
        pow_m *= m;
        tmp *= m / l;
        ans += pow_m - tmp;
    }
    println!("{}", ans);
}

