pub fn sieve(n: usize) -> Vec<bool> {
    let mut p = vec![true; n + 1];
    p[0] = false;
    p[1] = false;
    for i in 2..=n {
        if p[i] && i * i <= n {
            for j in (i * i..=n).step_by(i) {
                p[j] = false;
            }
        }
    }
    p
}

