pub struct Z(i64);

impl Z {
    const MOD: i64 = 998_244_353;

    pub fn new(mut x: i64) -> Z {
        x %= Z::MOD;
        if x < 0 {
            x += Z::MOD;
        }
        Z(x)
    }

    pub fn pow(self, mut exp: u32) -> Z {
        let mut ans = Z::new(1);
        let mut base = self;
        while exp > 1 {
            if exp % 2 == 1 {
                ans = ans * base;
            }
            base = base * base;
            exp >>= 1;
        }
        ans * base
    }

    pub fn inv(self) -> Z {
        assert_ne!(self.0, 0);
        self.pow((Z::MOD - 2) as u32)
    }
}

