            }
        }
    }
    p
}

pub fn modpow(mut base: i64, mut exp: i64) -> i64 {
    let mut ans = 1;
    base %= MOD;
    while exp > 0 {
        if exp % 2 == 1 {
            ans = ans * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    ans
}

