pub mod plat {
    pub mod classic {
        pub mod solution {
            use crate::{input, output};

            use super::io::Io;

            pub const IS_MULTITEST: bool = false;

            pub fn solve(io: &mut Io) {
                input! { io =>
                    n: usize,
                    m: u64
                }
                let mut is_prime = vec![true; n+1];
                for v in 2..=n {
                    if !is_prime[v] {
                        continue;
                    }
                    for d in (v..=n).step_by(v).skip(1) {
                        is_prime[d] = false;
                    }
                }
                let md = 998244353u64;
                let mut tot = m % md;
                let mut pos = m % md;
                let mut ans = 0;
                let mut mul = 1u64;
                for k in 2..=n {
                    tot = (tot * (m % md)) % md;
                    if is_prime[k] && mul <= m {
                        mul *= k as u64;
                    }
                    pos = (m / mul % md * pos) % md;
                    ans = (ans + md + tot - pos) % md;
                }
                output! { io => ans; }
            }
        }

        pub mod io {
            use std::{fmt::Debug, io::BufRead, str::FromStr};

            use crate::utils::io::{InputSource, OutputTarget};

            #[macro_export]
            macro_rules! read_value {
                ($io:ident, [$type:tt; $len:expr]) => {
                    (0..$len).map(|_| $crate::read_value!($io, $type)).collect::<Vec<_>>()
                };
                ($io:ident, ($($type:tt),+)) => {
                    ($( $crate::read_value!($io, $type), )*)
                };
                ($io:ident, usize1) => {
                    $crate::read_value!($io, usize) - 1
                };
                ($io:ident, $type:ty) => {
                    $io.reader.read::<$type>()
                }
            }

            /// # Examples
            /// ```
            /// input! { io =>
            ///     (n, m): usize,
            ///     a: [[i32; m]; n]
            /// }
            /// input! { io =>
            ///     (n, m): usize,
            ///     edges: [(usize1, usize1); m]
            /// }
            /// ```
            #[macro_export]
            macro_rules! input {
                ($io:ident => ) => {};
                ($io:ident => $var:ident: $type:tt) => {
                    let $var = $crate::read_value!($io, $type);
                };
                ($io:ident => ($($var:ident),+): $type:tt) => {
                    $( $crate::input!{ $io => $var: $type } )*
                };
                ($io:ident => $($vars:tt: $type:tt),+) => {
                    $( $crate::input!{ $io => $vars: $type } )*
                }
            }

            /// # Examples
            /// ```
            /// let (n, m) = (1, 2);
            /// let a = vec![1, 2, 3];
            /// let ans = false;
            /// output! { io =>
            ///     n, m;
            ///     sl(a);
            ///     yn(ans);
            /// }
            /// ```
            #[macro_export]
            macro_rules! output {
                ($io:ident => ) => {};
                ($io:ident => ;) => {
                    $io.printer.print(&'\n');
                };
                ($io:ident => ,) => {
                    $io.printer.print(&' ');
                };
                ($io:ident => $val:expr) => {
                    $io.printer.print(&$val);
                };
                ($io:ident => sl $val:tt $($tail:tt)*) => {
                    $io.printer.print_vec(&$val, ' ');
                    $crate::output!{ $io => $($tail)* }
                };
                ($io:ident => nl $val:tt $($tail:tt)*) => {
                    $io.printer.print_vec(&$val, '\n');
                    $crate::output!{ $io => $($tail)* }
                };
                ($io:ident => yn $val:tt $($tail:tt)*) => {
                    #[allow(unused_parens)]
                    $io.printer.print(&(if $val { "Yes" } else { "No" }));
                    $crate::output!{ $io => $($tail)* }
                };
                ($io:ident => $head:tt $($tail:tt)*) => {
                    $crate::output!{ $io => $head }
                    $crate::output!{ $io => $($tail)* }
                }
            }

            #[derive(Default)]
            pub struct Io {
                pub reader: InputReader,
                pub printer: OutputPrinter,
            }

            pub struct InputReader {
                source: InputSource,
                splitter: WhitespaceSplitter,
            }

            pub struct OutputPrinter {
                target: OutputTarget,
            }

            pub trait Parsable {
                fn parse(s: &str) -> Self;
            }

            impl<T> Parsable for T
            where
                T: FromStr,
                <T as FromStr>::Err: Debug,
            {
                fn parse(s: &str) -> Self {
                    T::from_str(s).unwrap()
                }
            }

            impl Default for InputReader {
                fn default() -> Self {
                    Self {
                        source: InputSource::from_env(),
                        splitter: WhitespaceSplitter::default(),
                    }
                }
            }

            impl InputReader {
                pub fn read<T: Parsable>(&mut self) -> T {
                    self.splitter.parse_next(self.source.reader())
                }
            }

            impl Default for OutputPrinter {
                fn default() -> Self {
                    Self {
                        target: OutputTarget::from_env(),
                    }
                }
            }

            impl OutputPrinter {
                pub fn print<T: ToString>(&mut self, v: &T) {
                    self.target
                        .writer()
                        .write(v.to_string().as_bytes())
                        .unwrap();
                }

                pub fn print_vec<T: ToString>(&mut self, a: &Vec<T>, sep: char) {
                    let mut is_first = true;
                    for item in a {
                        if !is_first {
                            self.print(&sep)
                        }
                        is_first = false;
                        self.print(item)
                    }
                }
            }

            #[derive(Default)]
            pub struct WhitespaceSplitter {
                buf: Vec<u8>,
            }

            impl WhitespaceSplitter {
                pub fn parse_next<T: Parsable>(&mut self, buf_read: &mut dyn BufRead) -> T {
                    self.buf.clear();
                    while let Some(byte) = consume_next_byte(buf_read) {
                        match byte {
                            b'\r' => {}
                            b' ' | b'\n' => {
                                if !self.buf.is_empty() {
                                    break;
                                }
                            }
                            symbol => {
                                self.buf.push(symbol);
                            }
                        }
                    }
                    if self.buf.is_empty() {
                        panic!("Read nothing")
                    }
                    let s = std::str::from_utf8(&self.buf).unwrap();
                    T::parse(s)
                }
            }

            fn consume_next_byte(buf_read: &mut dyn BufRead) -> Option<u8> {
                if let Some(&byte) = buf_read.fill_buf().unwrap().get(0) {
                    buf_read.consume(1);
                    Some(byte)
                } else {
                    None
                }
            }
        }


        pub fn run() {
            let mut io = io::Io::default();
            let test_cnt = if solution::IS_MULTITEST {
                io.reader.read::<usize>()
            } else { 1 };
            for _ in 0..test_cnt {
                solution::solve(&mut io);
            }
        }
    }

