const P: i64 = 998244353;

fn primes(n: usize) -> Vec<bool> {
    let mut ps = vec![true; n + 1];
    for i in 2..n {
        if ps[i] {
            for j in (i * i..=n).step_by(i) {
                ps[j] = false;
            }
        }
    }
    ps
}

fn primes2(ps: Vec<bool>) -> Vec<usize> {
    ps.iter()
        .enumerate()
        .filter_map(|(i, &is_prime)| if is_prime && i >= 2 { Some(i) } else { None })
        .collect()
}

fn solve(n: usize, m: i64) -> i64 {
    let mut x = m % P;
    let mut y = m % P;
    let mut ans = 0;
    let mut p = 1 as i64;
    let ps = primes(n);
    for i in 2..=n {
        if ps[i] && p <= m {
            p = p * (i as i64);
        }
        x = (x * ((m / p) % P)) % P;
        y = (y * (m % P)) % P;
        ans = (ans + (y - x + P) % P) % P;
    }
    ans
}

fn main() {
    read_line!(n: usize, m: i64);
    println!("{}", solve(n, m));
}

