struct Digits {
    number: u64,
    divisor: u64,
}

impl Digits {
    fn new(number: u64) -> Self {
        let mut divisor = 1;
        while number >= divisor * 10 {
            divisor *= 10;
        }

        Digits {
            number,
            divisor,
        }
    }

    fn reset(&mut self, number: u64){
        let mut divisor = 1;
        while number >= divisor * 10 {
            divisor *= 10;
        }
        self.divisor = divisor;
        self.number = number;

    }
}

impl Iterator for Digits {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        if self.divisor == 0 {
            None
        } else {
            let v = Some(self.number / self.divisor);
            self.number %= self.divisor;
            self.divisor /= 10;
            v
        }

    }
}

struct InfinityCounter{
    num: Digits,
    current: u64,
}
impl InfinityCounter{
    pub fn new() -> Self{
        Self{
            current: 0,
            num: Digits::new(1),
        }
    }
}


impl Iterator for InfinityCounter{
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        let next = self.num.next();
        if next.is_none() {
            self.current += 1;
            self.num.reset(self.current);
            return self.num.next();
        }
        next
    }
}

