const BALLS_SIZE: usize = 3;
const CRYST_SIZE: usize = 2;

enum ColorsB{
    Yell,
    Green,
    Blue
}

type CrystalsArray =  [i64; CRYST_SIZE];
type BallsArray = [i64; BALLS_SIZE];

fn count_crystals(balls :BallsArray) -> CrystalsArray{
    fn count_yellow(num: i64 ) -> CrystalsArray {
        [2*num, 0]
    }
    fn count_green(num: i64 ) -> CrystalsArray {
        [num, num]
    }
    fn count_blue(num: i64 ) -> CrystalsArray {
        [0,3*num]
    }
    println!("");
    let mut res: CrystalsArray = [0; CRYST_SIZE];
    for (ind,i) in count_yellow(balls[ColorsB::Yell as usize]).iter().enumerate(){
        res[ind] += *i;
    }
    for (ind,i) in count_green(balls[ColorsB::Green as usize]).iter().enumerate(){
        res[ind] += *i;
    }

    for (ind,i) in count_blue(balls[ColorsB::Blue as usize]).iter().enumerate(){
        res[ind] += *i;
    }
    return res ;
}

