    let mut input: String = String::new();
    io::stdin().read_line(&mut input).expect("some error");
    let mut cryst_inp: CrystalsArray = [0; CRYST_SIZE];
    let mut balls_inp: BallsArray = [0; BALLS_SIZE];
    for (ind,i) in input.trim().split(char::is_whitespace).enumerate(){
        cryst_inp[ind] = i.trim().parse().expect("failed to parse");
    }
    input.clear();
    io::stdin().read_line(&mut input).expect("some error");
    for (ind,i) in input.trim().split(char::is_whitespace).enumerate(){
        balls_inp[ind] = i.trim().parse().expect("failed to parse");
    }
    let have_to = count_crystals(balls_inp);
    let mut sum = 0;
    for (ind,i) in  cryst_inp.iter().enumerate(){
        let diff =  have_to[ind] - i;
        if diff > 0 {
            sum += diff;
        }
    }
    print!("{}", sum);
}

