fn calc(x: u64, y: u64) -> bool {
    let mut set = Set::new();
    let mut s = vec![];
    let mut x = x;
    while x > 0 {
        s.push(x % 2);
        x /= 2;
    }
    set.insert(s.clone());
    let fix = |s: &mut Vec<u64>| {
        while *s.last().unwrap() == 0 {
            s.pop();
        }
    };
    let mut dfs = vec![s];
    while let Some(s) = dfs.pop() {
        for &d in [0, 1].iter() {
            let mut s = s.clone();
            s.insert(0, d);
            s.reverse();
            fix(&mut s);
            if s.len() <= 60 && set.insert(s.clone()) {
                dfs.push(s);
            }
        }
    }
    let mut s = vec![];
    let mut y = y;
    while y > 0 {
        s.push(y % 2);
        y /= 2;
    }
    set.contains(&s)
}

fn run() {
    input!(x: u64, y: u64);
    if calc(x, y) {
        println!("YES");
    } else {
        println!("NO");
    }
}

