}

fn to10(d: &Vec<i64>) -> i64 {
    if d.len() > 60 {
        return 0;
    }
    let (mut exp, mut res) = (1, 0);
    for i in (0..d.len()).rev() {
        if d[i] == 1 {
            res += exp;
        }
        exp *= 2;
    }
    res
}

