    while x & ((1 << m) - 1) < x {
        m += 1
    }
    while y > 0 {
        if y & ((1 << m) - 1) == x {
            y >>= m;
            return y & (y + 1) == 0;
        } else if y & 1 == 0 {
            return false;
        } else {
            y >>= 1;
        }
    }
    false
}

