fn main() {
    let mut sc = Scanner::stdin();
    let mut wr = Writer::stdout();

    let (x, y) = scan!(sc, u64, u64);
    let target = format!("{:b}", y);

    let mut visited = HashSet::new();
    let mut current = Vec::new();
    current.push(format!("{:b}", x));

    for _ in 0..140 {
        let mut next_cur = Vec::new();
        for s in current {
            if s == target {
                out!(wr, "YES");
                return;
            }
            for d in ['0', '1'] {
                let mut next = s.clone();
                next.push(d);
                next = next.chars().rev().skip_while(|c| *c == '0').collect();
                if !visited.contains(&next) {
                    visited.insert(next.clone());
                    next_cur.push(next);
                }
            }
        }
        current = next_cur;
        if current.is_empty() {
            break;
        }
    }

    out!(wr, "NO");
}

