impl Scanner {
    fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            stdin().read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}

pub fn flip(mut num: u64) -> u64 {
    let mut result: u64 = 0;
    while num > 0 {
        result = (result << 1) | (num & 1);
        num >>= 1;
    }
    result
}

pub fn add_one(num: u64) -> u64 {
    flip((num << 1) | 1)
}

pub fn main() {
    let mut scanner = Scanner::default();
    let a: u64 = scanner.next();
    let b: u64 = scanner.next();
    let mut visited: HashSet<u64> = HashSet::new();
    let mut queue: VecDeque<u64> = VecDeque::new();
    queue.push_back(a);
    visited.insert(a);
    let mut current: u64 = a;
    while !queue.is_empty() {
        current = queue.pop_front().unwrap();
        if current == b {
            break;
        }
        if current < b {
            let added: u64 = add_one(current);
            if !visited.contains(&added) {
                visited.insert(added);
                queue.push_back(added);
            }
        }
        let flipped: u64 = flip(current);
        if !visited.contains(&flipped) {
            visited.insert(flipped);
            queue.push_back(flipped);
        }
    }
    println!("{}", if current == b { "YES" } else { "NO" });
}

