fn read_line(stdin : &Stdin, line : &mut String) {
    match stdin.read_line(line) {
        Ok(_) => return,
        Err(msg) => panic!("Could not read line! Message: {}.", msg),
    }
}

fn parse_t<T : FromStr>(s : &str) -> T {
    match s.trim().parse() {
        Ok(y) => y,
        Err(_) => panic!("Could not read from string!"),
    }
}

fn read_t<T : FromStr>(stdin : &Stdin) -> T {
    let mut line = String::new();
    read_line(stdin, &mut line);
    parse_t(&line)
}

const NUM_LETTERS : usize = 26;

fn is_pangram(s : &String) -> bool {
    let t = s.trim().to_lowercase();
    let mut distinct_chars = BTreeSet::new();
    for c in t.chars() {
        distinct_chars.insert(c);
    }
    distinct_chars.len() == NUM_LETTERS
}

fn main() {
    let stdin = io::stdin();
    let _ : u64 = read_t(&stdin);
    let mut s = String::new();
    read_line(&stdin, &mut s);
    if is_pangram(&s) {
        println!("YES");
    } else {
        println!("NO");
    }
}

