  let x: Vec<i32> = s.trim()
    .split_whitespace()
    .map(|x| x.parse().unwrap())
    .collect();

  let n = x[0];
  let m = x[1];
  let a = x[2];
  let b = x[3];

  if m * a <= b {
    println!("{}", a*n);
  } else {
    if m > n { 
      println!("{}", min(b, a*n));
    } else {
      if a*(n%m) < b {
        println!("{}", b*(n/m)+a*(n%m));
      } else {
        println!("{}", b*(n/m+1));
      }
    }
  }
}

