use std::io;
use std::str;

pub struct Scanner<R> {
    reader: R,
    buffer: Vec<String>,
}

impl<R: io::BufRead> Scanner<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![],
        }
    }

    pub fn token<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}

fn linear_sieve(n: u64) -> (Vec<u64>, Vec<u64>) {
    let n = n as usize;
    let mut mpf = vec![0u64; n + 1];
    let mut primes = Vec::new();
    for i in 2..=n {
        if mpf[i] == 0 {
            mpf[i] = i as u64;
            primes.push(i as u64);
        }
        // for (int j = 0; j < primes.size() && i * primes[j] <= n && primes[j] <= mpf[i]) {
        //   mpf[i * primes[j]] = primes[j]
        // }
        for &p in primes.iter() {
            let num = i * p as usize;
            if num > n || p > mpf[i] {
                break;
            }
            mpf[num] = p;
        }
    }
    (primes, mpf)
}

fn get_mpf(n: u64, primes: &[u64], mpf: &[u64]) -> u64 {
    if (n as usize) < mpf.len() {
        return mpf[n as usize];
    }
    for &p in primes {
        if n % p == 0 {
            return p;
        }
    }
    n
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
    let (primes, mpf) = linear_sieve(1000000);
    let mut n: u64 = scan.token();
    let mut ans = n;
    while n > 1 {
        let factor = n / get_mpf(n, &primes, &mpf);
        ans += factor;
        n = factor;
    }
    writeln!(out, "{}", ans).ok();
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());
    solve(&mut scan, &mut out);
}

