struct Scanner<'a, T: std::io::Read> {
    reader: &'a mut T,
    buffer: [u8; 4096],
    position: usize,
    size: usize
}

impl<'a, T: std::io::Read> Scanner<'a, T> {
    const SPACES: [i32; 4] = [
        ' ' as i32,
        '\n' as i32,
        '\t' as i32,
        '\r' as i32];
    const ZERO: i32 = '0' as i32;
    const NINE: i32 = '9' as i32;
    const NEG: i32 = '-' as i32;

    fn new(reader: &'a mut T) -> Scanner<'a, T> {
        Scanner {
            reader,
            buffer: [0; 4096],
            position: 0,
            size: 0
        }
    }

    fn read_block(&mut self) {
        self.size = self.reader.read(&mut self.buffer).unwrap();
        self.position = 0;
    }

    fn read_char(&mut self) -> i32 {
        if self.position >= self.size {
            self.read_block();
            if self.position >= self.size {
                return -1;
            }
        }

        let ch = self.buffer[self.position];
        self.position += 1;

        ch as i32
    }

    fn read_int(&mut self) -> Option<i32> {
        let mut ch = self.read_char();
        while ch != -1 && Scanner::<T>::SPACES.contains(&ch) {
            ch = self.read_char();
        }

        if ch == -1 {
            return None;
        }

        let mut negative = false;
        if ch == Scanner::<T>::NEG {
            negative = true;
            ch = self.read_char();
        }

        let mut result = 0;
        while ch != -1 && ch >= Scanner::<T>::ZERO && ch <= Scanner::<T>::NINE {
            result = result * 10 + ch - Scanner::<T>::ZERO;
            ch = self.read_char();
        }

        Some(if negative {
            -result
        } else {
            result
        })
    }

    fn read_str(&mut self) -> String {
        let mut ch = self.read_char();
        while ch != -1 && Scanner::<T>::SPACES.contains(&ch) {
            ch = self.read_char();
        }

        let mut s = String::new();
        while !Scanner::<T>::SPACES.contains(&ch) {
            s.push(std::char::from_u32(ch as u32).unwrap());
            ch = self.read_char();
        }

        return s;
    }
}

const MOD: i64 = 998244353i64;

fn main() {
    let mut stdin = std::io::stdin();
    let mut reader = Scanner::new(&mut stdin);

    let w = reader.read_int().unwrap();
    let h = reader.read_int().unwrap();

    // dp[i][j] = dp[i][j - 1] * 2 = dp[i - 1][j] * 2
    let mut dp = vec![vec![0i64; (w + 1) as usize]; (h + 1) as usize];
    dp[1][1] = 4;

    for j in 2..=w as usize {
        dp[1][j] = dp[1][j - 1] * 2 % MOD;
    }
    for i in 2..=h as usize {
        dp[i][1] = dp[i - 1][1] * 2 % MOD;
    }

    for i in 2..=h as usize {
        for j in 2..=w as usize {
            dp[i][j] = dp[i][j - 1] * 2 % MOD;
        }
    }

    println!("{}", dp[h as usize][w as usize]);
}

