fn calcular_linea(line: String, tipo: i32) -> i32{
    let mut total = 0;
    for c in line.chars(){
        if tipo == 0 {
            match c{
                'Q' => total += 9,
                'R' => total += 5,
                'B' => total += 3,
                'N' => total += 3,
                'P' => total += 1,
                _ => (),
            };
        }
        else {
            match c{
                'q' => total += 9,
                'r' => total += 5,
                'b' => total += 3,
                'n' => total += 3,
                'p' => total += 1,
                _ => (),
            };
        }
    }
    total
}

