fn board_calc(mut sc: i32, piece: char) -> i32 {
	match piece {
	    'Q' => sc += 9,
	    'q' => sc -= 9,
	    'R' => sc += 5,
	    'r' => sc -= 5,
	    'B' | 'N' => sc += 3,
	    'b' | 'n' => sc -= 3,
	    'P' => sc += 1,
	    'p' => sc -= 1,
	    _ => sc += 0
	};
	sc
}

