struct BIT {
    n: usize,
    bit: Vec<i64>,
}

impl BIT {
    fn new(n:usize) -> BIT {
        BIT {
            n,
            bit: vec![0;n+1],
        }
    }

    fn add(&mut self, a:usize, w:i64) {
        let mut x = a;
        while x <= self.n {
            self.bit[x] += w;
            x += (x as i64 & -(x as i64)) as usize;
        }
    }

    fn sum(&self, a:usize) -> i64 {
        let mut ret = 0;
        let mut x = a as i64;
        while x > 0 {
            ret += self.bit[x as usize];
            x -= x & -x;
        }
        ret
    }
}

fn prime_factor(n: i64) -> BTreeMap<i64,i64> {
    let mut n = n;
    let mut map = BTreeMap::new();
    let mut i = 2;
    while i*i <= n {
        while n%i == 0 {
            let count = map.entry(i).or_insert(0);
            *count += 1;
            n /= i;
        }
        i += 1;
    }
    if n!=1 { map.insert(n,1); }
    map
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }

    input! {
        n: i64,
    }

    let mut n = n;
    let fac = prime_factor(n);
    let d = *fac.iter().next().unwrap().0;
    //debug!(d);
    let mut ans = 0;
    if d != 2 {
        n -= d;
        ans += 1;
    }
    //debug!(d,n);
    puts!("{}\n", ans+n/2);
}

/*

n から最小の素数の約数を引いていく、何回操作ができるか。

34, 32, 30, 28, .., 2, 0
31, 0
6, 4, 2, 0
10, 8, 6, 4,
9, 6, 4, 2, 0
25, 20, 18, 16, 14, 12, 10
3*3 -> 3*2 -> 2*2 -> 2*1 -> 2*0
5*5 -> 10*2 (5*4) -> 9*2 -> 8*2 -> .. -> 1*2 -> 0*2
3*3*3 (3*9) -> 3*8 (2*12) -> 2*11 -> .. -> 2*0

素因数分解する。最小の約数が２じゃないなら、それで引く。
次の数字は必ず最小の素数の約数が２になるので答えに２で割った数を足す。

*/

fn main() {
    let mut input = String::new();
    use std::io::{self, prelude::*};
    io::stdin().read_to_string(&mut input).unwrap();

    let mut it = input.split_whitespace();
    let r0 = it.next().unwrap();
    let n = r0.len();
    let r1 = it.next().unwrap();

    #[derive(Clone, Copy, Debug)]
    enum Cell {
        Empty,
        Pawn,
    }

    let mut grid: Vec<_> = r0.chars().chain(r1.chars()).map(|c| {
        match c {
            '0' => Cell::Empty,
            'X' => Cell::Pawn,
            _ => panic!("Oops!"),
        }
    }).collect();

    let f = |c| {
        match c {
            Cell::Empty => 1,
            Cell::Pawn => 0,
        }
    };

    let cnt = |c, grid: &[Cell]| {
        f(grid[c]) + f(grid[n + c])
    };

    let mut ans = 0;
    for c in 0..n {
        if cnt(c, &grid) == 2 {
            if c > 0 && cnt(c - 1, &grid) == 1 {
                grid[c] = Cell::Pawn;
                grid[n + c] = Cell::Pawn;
                ans += 1;
            } else if c + 1 < n {
                if let Cell::Empty = grid[c + 1] {
                    grid[c + 1] = Cell::Pawn;
                    grid[c] = Cell::Pawn;
                    grid[n + c] = Cell::Pawn;
                    ans += 1;
                } else if let Cell::Empty = grid[n + c + 1] {
                    grid[n + c + 1] = Cell::Pawn;
                    grid[c] = Cell::Pawn;
                    grid[n + c] = Cell::Pawn;
                    ans += 1;
                }
            }
        }
    }

    println!("{}", ans);
}

