    let mut v: Vec<u32> = Vec::with_capacity(a.len());
    for (p, q) in a.chars().zip(b.chars()) {
        let mut slots = if p == '0' { 1 } else { 0 } + if q == '0' { 1 } else { 0 };
        v.push(slots);
    }
    let mut bishwocks = 0;
    for i in 0..v.len() {
        if v[i] == 2 {
            if i != 0 && v[i - 1] == 1 {
                v[i] = 0;
                bishwocks += 1;
            } else if i + 1 != v.len() {
                if v[i + 1] != 0 {
                    v[i] = 0;
                    v[i + 1] -= 1;
                    bishwocks += 1;
                }
            }
        }
    }
    println!("{}", bishwocks);
