use combinatorics::{next_permutation, Factorials};
use number_theory::{egcd, gcd, mod_exp, mod_mulinv, PrimeSieve};
use prefix_sum::{PrefixOp, PrefixSum};
use scanner::{
    macros::{LenArray, UsizeM1},
    Scanner,
};
use util::{fix, Argmax, Assign, Choose, IntoVec, Sorted};
use writer::{Format, Writer};

fn main() {
    let mut sc = Scanner::stdin();
    let mut wr = Writer::stdout();

    const MOD: i64 = 1_000_000_007;
    const N: i64 = 100_000;
    let n = scan!(sc, i64);
    let primes = PrimeSieve::new(N);

    let totient = |n: i64| {
        let mut t = n;
        let mut pf = primes.factorize(n);
        pf.sort();
        pf.dedup();
        for f in pf {
            t -= t / f
        }
        t
    };
    let totient_pre = (0..=N)
        .map(|i| if i <= 1 { 0 } else { totient(i) })
        .into_vec();
    p!(&totient_pre[..10]);

    let mut total = 0;
    for c in 1..=n - 2 {
        let mut gs = vec![];
        for g in (1..).take_while(|g| g * g <= n - c) {
            if (n - c) % g == 0 {
                gs.push(g);
                if g * g != n - c {
                    gs.push((n - c) / g);
                }
            }
        }
        p!(c, gs);

        for g in gs {
            let cnt = totient_pre[((n - c) / g) as usize];
            p!(g, cnt, (n - c) / g);
            total = (total + cnt * c * g / gcd(c, g)) % MOD;
        }
    }

    out!(wr, total);
}

use std::{
    io::{prelude::*, stdin, stdout, BufWriter},
    mem::swap,
};

const MOD: i64 = 1000000007;

fn main() {
    let std_in = stdin();
    let mut input = Scanner::new(std_in.lock());

    let std_out = stdout();
    let mut output = BufWriter::new(std_out.lock());

    let n: usize = input.token();

    let mut phi: Vec<usize> = (0..=n).collect();
    for i in 2..=n {
        if phi[i] == i {
            for j in (i..=n).step_by(i) {
                phi[j] -= phi[j] / i;
            }
        }
    }

    let mut result = 0;
    for c in 1..n {
        let sum = n - c;
        if sum < 2 {
            continue;
        }

        add_to_result(c as i64, 1, phi[sum] as i64, &mut result);
        for x in 2..=sum {
            if x * x > sum {
                break;
            }
            if sum % x != 0 {
                continue;
            }

            let y = sum / x;
            if phi[y] != 0 {
                add_to_result(c as i64, x as i64, phi[y] as i64, &mut result);
            }
            if x != y && phi[x] != 0 {
                add_to_result(c as i64, y as i64, phi[x] as i64, &mut result);
            }
        }
    }
    writeln!(output, "{}", result).unwrap();
}

fn add_m(x: i64, y: i64) -> i64 {
    let mut tmp = x + y;
    if tmp < 0 {
        tmp += MOD;
    }
    if tmp >= MOD {
        tmp -= MOD;
    }
    tmp
}

fn mul_m(x: i64, y: i64) -> i64 {
    (x * y) % MOD
}

fn gcd(mut a: i64, mut b: i64) -> i64 {
    while b != 0 {
        a %= b;
        swap(&mut a, &mut b);
    }
    a
}

fn add_to_result(c: i64, g: i64, cnt: i64, result: &mut i64) {
    *result = add_m(*result, mul_m(cnt, c * g / gcd(c, g)));
}

pub struct Scanner<B> {
    reader: B,
    buf_str: Vec<u8>,
    buf_iter: std::str::SplitWhitespace<'static>,
}
impl<B: BufRead> Scanner<B> {
    pub fn new(reader: B) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_whitespace(),
        }
    }
    pub fn token<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = std::str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_whitespace())
            }
        }
    }
}

