fn solve<R: BufRead, W: Write>(sc: &mut Scanner<R>, wr: &mut W) {
    const MOD: i64 = 1_000_000_007;
    let n: usize = sc.tok();
    let lowest = sieve(n);
    let mut phi = vec![1; n + 1];
    for k0 in 2..=n {
        let p = lowest[k0];
        let mut pow = 1;
        let mut k = k0;
        while k % p == 0 {
            k /= p;
            pow *= p;
        }
        phi[k0] = phi[k] * ((p - 1) * (pow / p)) as i64;
    }
    let mut res = 0;
    for g in 1..=n as i64 - 1 {
        let mut s = 2 * g;
        while s < n as i64 {
            res += phi[(s / g) as usize] * lcm(g, n as i64 - s) % MOD;
            if res >= MOD {
                res -= MOD;
            }
            s += g;
        }
    }
    writeln!(wr, "{}", res);
}

pub fn gcd(mut a: i64, mut b: i64) -> i64 {
    a = a.abs();
    b = b.abs();
    while b > 0 {
        a %= b;
        (a, b) = (b, a);
    }
    a
}

pub fn lcm(a: i64, b: i64) -> i64 {
    if (a, b) == (0, 0) {
        0
    } else {
        a / gcd(a, b) * b
    }
}
fn sieve(max: usize) -> Vec<usize> {
    let mut primes = vec![];
    let mut lowest = vec![0; max + 1];
    for n in 2..=max {
        if lowest[n] == 0 {
            lowest[n] = n;
            primes.push(n);
        }
        for &p in &primes {
            if p > lowest[n] || p * n > max {
                break;
            }
            lowest[p * n] = p;
        }
    }
    lowest
}

use std::marker::PhantomData;
macro_rules! recursive_function {
    ($name: ident, $trait: ident, ($($type: ident $arg: ident,)*)) => {
        pub trait $trait<$($type, )*Output> {
            fn call(&mut self, $($arg: $type,)*) -> Output;
        }

        pub struct $name<F, $($type, )*Output>
        where
            F: FnMut(&mut dyn $trait<$($type, )*Output>, $($type, )*) -> Output,
        {
            f: F,
            $($arg: PhantomData<$type>,
            )*
            phantom_output: PhantomData<Output>,
        }

        impl<F, $($type, )*Output> $name<F, $($type, )*Output>
        where
            F: FnMut(&mut dyn $trait<$($type, )*Output>, $($type, )*) -> Output,
        {
            pub fn new(f: F) -> Self {
                Self {
                    f,
                    $($arg: Default::default(),
                    )*
                    phantom_output: Default::default(),
                }
            }
        }

        impl<F, $($type, )*Output> $trait<$($type, )*Output> for $name<F, $($type, )*Output>
        where
            F: FnMut(&mut dyn $trait<$($type, )*Output>, $($type, )*) -> Output,
        {
            fn call(&mut self, $($arg: $type,)*) -> Output {
                let const_ptr = &self.f as *const F;
                let mut_ptr = const_ptr as *mut F;
                unsafe { (&mut *mut_ptr)(self, $($arg, )*) }
            }
        }
    }
}

