fn gcd(mut a: i64, mut b: i64) -> i64 {
    while b > 0 {
        a %= b;
        let tmp = a;
        a = b;
        b = tmp;
    }
    a
}

fn solution() {
    let mut scanner = Scanner::new();
    let n: i64 = scanner.next();
    let k: i64 = scanner.next();
    let a: i64 = scanner.next();
    let b: i64 = scanner.next();

    let mut x = std::i64::MAX;
    let mut y = 0;
    for i in 0..n {
        if a + i * k >= n * k {
            break;
        }
        for j in [b - a, a + b, a + i * k - b, a + i * k + b, i * k - a + b, i * k - a - b].iter() {
            let mut l = *j;
            if l < 0 {
                l = -l;
            }
            if l == 0 {
                l = n * k;
            }
            let m = n * k / gcd(l, n * k);
            x = std::cmp::min(x, m);
            y = std::cmp::max(y, m);
        }
    }
    println!("{} {}", x, y);
}

