fn forward_dist(mut c1: u8, c2: u8) -> u64 {
  let mut dist = 0;
  while c1 != c2 {
    c1 = (c1 + 1) % 26;
    dist += 1;
  }
  dist
}

fn backward_dist(mut c1: u8, c2: u8) -> u64 {
  let mut dist = 0;
  while c1 != c2 {
    if c1 == 0 { c1 = 25; }
    else { c1 -= 1; }
    dist += 1;
  }
  dist
}

