fn hash(a: &[usize], cnt: &[usize]) -> usize {
    let mut hash = 0;
    for i in 0..10 {
        hash = (cnt[i] + 1) * hash + a[i];
    }
    hash
}

fn decode(mut hash: usize, cnt: &[usize]) -> Vec<usize> {
    let mut d = vec![];
    for i in (0..10).rev() {
        d.push(hash % (cnt[i] + 1));
        hash /= cnt[i] + 1;
    }
    d.reverse();
    d
}

