    let mut dp = vec![0u64; hash_sup * m];
    let mut used = vec![false; hash_sup * m];
    dp[(hash_sup - 1) * m + 0] = 1;
    used[(hash_sup - 1) * m + 0] = true;
    let mut q = std::collections::VecDeque::new();
    q.push_back((hash_sup - 1) * m + 0);
    while let Some(v) = q.pop_front() {
        let rem = v % m;
        let h = v / m;
        let a = decode(h, &cnt);
        for d in 0..10 {
            if a[d] > 0 && !(d == 0 && a == cnt) {
                let r = (10 * rem + d) % m;
                let u = (h - step[d]) * m + r;
                dp[u] += dp[v];
                if !used[u] {
                    used[u] = true;
                    q.push_back(u);
                }
            }
        }
    }
    let ans = dp[0 * m + 0];
    println!("{}", ans);
}

fn main() {
    run();
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let mut n: u64 = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let p = 10;
    let mut cnt = vec![0; p];
    while n > 0 {
        let k = (n % p as u64) as usize;
        cnt[k] += 1;
        n /= p as u64;
    }
    let mut step = vec![1; p + 1];
    for i in (0..p).rev() {
        step[i] = step[i + 1] * (cnt[i] + 1);
    }
    let len = step[0];
    let mut dp = vec![vec![0u64; len]; m];
    dp[0][len - 1] = 1;
    let mut q = std::collections::VecDeque::new();
    q.push_back((0, len - 1));
    while let Some((rem, v)) = q.pop_front() {
        for d in 0..p {
            let a = v % step[d] / step[d + 1];
            if a > 0 && !(d == 0 && v == len - 1) {
                let u = v - step[d + 1];
                let r = (10 * rem + d) % m;
                if dp[r][u] == 0 {
                    q.push_back((r, u));
                }
                dp[r][u] += dp[rem][v];
            }
        }
    }
    let ans = dp[0][0];
    println!("{}", ans);
}

fn main() {
    run();
}

