fn hash(a: &[u64], cnt: &[u64]) -> u64 {
    let mut hash = 0;
    for i in 0..10 {
        hash = (cnt[i] + 1) * hash + a[i];
    }
    hash
}

fn decode(mut hash: u64, cnt: &[u64]) -> Vec<u64> {
    let mut d = vec![];
    for i in (0..10).rev() {
        d.push(hash % (cnt[i] + 1));
        hash /= cnt[i] + 1;
    }
    d.reverse();
    d
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
