    let m: usize = it.next().unwrap().parse().unwrap();
    let mut cnt = vec![0; 10];
    let mut len = 0;
    while n > 0 {
        let k = (n % 10) as usize;
        cnt[k] += 1;
        len += 1;
        n /= 10;
    }
    let mut now = std::collections::BTreeMap::new();
    now.insert((hash(&cnt, &cnt), 0), 1u64);
    for p in 0..len {
        let mut next = std::collections::BTreeMap::new();
        for (k, v) in now.iter() {
            let (h, rem) = *k;
            let a = decode(h, &cnt);
            for d in 0..10 {
                if a[d] > 0 && !(p == 0 && d == 0) {
                    let mut b = a.clone();
                    b[d] -= 1;
                    let r = (10 * rem + d) % m;
                    *next.entry((hash(&b, &cnt), r)).or_insert(0u64) += *v;
                }
            }
        }
        now = next;
    }
    let mut ans = 0;
    for (k, v) in now.iter() {
        if k.1 == 0 {
            ans += *v;
        }
    }
