fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 {
        a
    } else {
        gcd(b, a%b)
    }
}

fn main() {
    input! {
        n: i64
    };

    let mut ans = n;
    for i in 1..n+1 {
        if i * i > n {
            break;
        }
        if n % i == 0 {
            if i >= 2 {
                ans = gcd(ans, i);
            }
            if n/i >= 2 {
                ans = gcd(ans, n/i);
            }
        }
    }
    println!("{}", ans);
}

