pub fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}
pub fn bezout(a: i64, b: i64) -> (i64, i64, u64) {
    let (x, y, g) = bezout_sub((a * a.signum()) as u64, (b * b.signum()) as u64);
    (x * a.signum(), y * b.signum(), g)
}
fn bezout_sub(a: u64, b: u64) -> (i64, i64, u64) {
    if b == 0 {
        (1, 0, a)
    } else {
        let m = (a / b) as i64;
        let (x, y, g) = bezout_sub(b, a % b);
        (y, x - m * y, g)
    }
}

fn divs(n: u64) -> Vec<u64> {
    let mut res = Vec::new();
    for d in 2..((n as f64).sqrt() as u64)+1 {
        if n % d == 0 {
            res.push(d);
            if n != d*d {
                res.push(n / d);
            }
        }
    }
    res
}

fn main() {
    read!(n = u64);
    let ans = divs(n).into_iter().fold(n, |acc, d| gcd(acc, d));
    println!("{}", ans);
}

