macro_rules! readln {
        () => {{ let mut line = String::new(); stdin().read_line(&mut line).unwrap(); line }};
        ($type:ty) => {{ readln!().split_whitespace().next().unwrap().parse::<$type>().unwrap() }};
        (|$type_vec:ty|) => {{ readln!().split_whitespace().map(|it| it.parse().unwrap()).collect::<Vec<$type_vec>>() }};
        ($($type:ty),*) => {{ let line = readln!(); let mut iter = line.split_whitespace(); ($(iter.next().unwrap().parse::<$type>().unwrap(),)*) }};
        ($($type:ty),*, |$type_vec:ty|) => {{ let line = readln!(); let mut iter = line.split_whitespace();
            ($(iter.next().unwrap().parse::<$type>().unwrap(),)*iter.map(|it| it.parse().unwrap()).collect::<Vec<$type_vec>>(),)}};
}

fn re2(mut n: u64) -> BTreeSet<u64> {
    let mut res = BTreeSet::new();
    let mut mb = BTreeSet::new();
    let copy = n;
    let mut i = 2;
    while n != 1 && i * i <= copy && res.len() != 2 {
        if n % i == 0 {
            n /= i;
            res.insert(i);
            mb.insert(copy / i);
        } else {
            i += 1;
        }
    }
    mb.insert(n);
    res.remove(&1);
    if res.len() == 2 {
        return res;
    }
    mb.iter().for_each(|it| {
        let mut flag = true;
        for j in res.iter() {
            if *it % *j == 0 {
                flag = false;
            }
        }
        if flag {
            res.insert(*it);
        }
    });
    res.remove(&1);
    if res.is_empty() {
        res.insert(copy);
        return res;
    }

    res
}

fn main() {
    let mut n = readln!(u64);

    let res = re2(n);

    if res.is_empty() {
        println!("{}", n);
    } else if res.len() == 1 {
        println!("{}", res.iter().next().unwrap());
    } else {
        println!("1")
    }
}

