use std::vec;
fn ksm(mut a:isize, mut b:isize, c:isize) -> isize {
    a = a%c;
    let mut ret = 1;
    while b >= 1{
        if b % 2 == 1 {
            ret = (ret*a % c) as isize;
        }
        a = a*a % c;
        b /= 2;
    }
    return ret;
}
fn inv(mut a:isize, c:isize) -> isize {
    if a == 0{
        return 1;
    }
    return ksm(a, c-2, c);
}
