pub fn main() {
    crate::prepare!();
    sc!(n, k);
    let mut dp = vec![M::zero(); n + 1];
    dp[1] = M::one();
    let f = MemorizedFactorial::new(n);
    for i in 1..=k {
        let mut ndp = vec![M::zero(); n + 1];
        for j in 1..=n {
            if dp[j].is_zero() {
                continue;
            }
            for x in 0..=n - j {
                let d = dp[j] * f.combination(n - j, x);
                let nj = j + x;
                let e = (nj * nj.saturating_sub(1) - j * j.saturating_sub(1)) / 2;
                ndp[nj] += d * M::from(k - i + 1).pow(e - x);
            }
        }
        dp = ndp;
    }
    pp!(dp[n]);
}
