fn read_line() -> String {
    let mut input_line = String::new();
    io::stdin().read_line(&mut input_line).unwrap();
    return String::from(input_line.trim());
}

fn read_line_pair() -> (i32, i32) {
    let vec = read_line_vec();
    return (vec[0], vec[1]);
}

fn read_line_vec() -> Vec<i32> {
    return read_line().split(' ')
        .map(|s| s.parse().unwrap())
        .collect();
}



fn main() {
    let (n, m) = read_line_pair();
    let mut f = read_line_vec();
    f.sort();

    let mut best_diff = i32::max_value();
    // println!("best_diff: {}", best_diff);

    for i in 0..(m + 1) - n {
        let from_value = f[i as usize];
        let to_value = f[(i + n - 1) as usize];
        let diff = to_value - from_value;
        if diff < best_diff {
            best_diff = diff;
        }
    }

    println!("{:?}", best_diff);


}

