use std::io;

macro_rules! rt {
  ( $( $type:ty ),+ ) => ({
    let mut s = String::new();
    io::stdin().read_line(&mut s).unwrap();
    let mut iter = s.split_whitespace();
    (
      $(
      iter.next().unwrap().parse::<$type>().unwrap(),
      )+
    )
  })
}

macro_rules! rv {
  ( $type:ty ) => ({
    let mut s = String::new();
    io::stdin().read_line(&mut s).unwrap();
    let v: Vec<$type> = s.split_whitespace().map(|x|
    x.parse::<$type>().unwrap()).collect();
    v
  })
}

fn main() {
  let (n, m) = rt!(usize, usize);
  let mut v = rv!(usize);

  v.sort();

  let mut d = v[n-1] - v[0];
  for i in 1..m-n+1 {
    let diff = v[i+n-1] - v[i];
    if diff < d {
      d = diff;
    }
  }

  println!("{}", d);
}

use std::io;
use std::io::Stdin;
use std::str::FromStr;

fn read_line(stdin : &Stdin, line : &mut String) {
    match stdin.read_line(line) {
        Ok(_) => return,
        Err(msg) => panic!("Could not read line! Message: {}.", msg),
    }
}

fn parse_t<T : FromStr>(s : &str) -> T {
    match s.trim().parse() {
        Ok(y) => y,
        Err(_) => panic!("Could not read from string!"),
    }
}

fn read_ts<T : FromStr>(stdin : &Stdin, ts : &mut Vec<T>) {
    let mut line = String::new();
    read_line(stdin, &mut line);
    let word_iter = line.split_whitespace();
    for word in word_iter {
        let x = parse_t(word);
        ts.push(x);
    }
}

fn min_difference(n : u64, fs : &mut Vec<u64>) -> u64 {
    let mut min_diff = u64::max_value();
    let n_u = n as usize;
    let f_l_u = fs.len() as usize;
    fs.sort();
    for i in (n_u - 1) .. f_l_u {
        let diff = fs[i] - fs[(i + 1) - n_u];
        if diff < min_diff {
            min_diff = diff;
        }
    }
    min_diff
}

fn main() {
    let stdin = io::stdin();
    let mut n_m = vec![];
    let mut fs = vec![];
    read_ts(&stdin, &mut n_m);
    read_ts(&stdin, &mut fs);
    let d = min_difference(n_m[0], &mut fs);
    println!("{}", d);
}

