fn manhattan(p:(i64,i64), q:(i64,i64)) -> i64 {
    (p.0 - q.0).abs() + (p.1 - q.1).abs()
}

fn center(rect: &Vec<(i64, i64)>) -> (i64, i64) {
    let mut x = 0;
    let mut y = 0;
    for p in rect.iter() {
        x += p.0;
        y += p.1;
    }
    let m = rect.len() as i64;
    (x/m, y/m)
}

fn radius(rect: &Vec<(i64, i64)>) -> i64 {
    let mut mnx = rect[0].0;
    let mut mxx = rect[0].0;
    for p in rect.iter() {
        mnx = min(mnx, p.0);
        mxx = max(mxx, p.0);
    }
    (mxx - mnx) / 2
}

fn minx(rect: &Vec<(i64, i64)>) -> i64 {
    let mut ac = rect[0].0;
    for p in rect.iter() { ac = min(ac, p.0); }
    ac
}
fn maxx(rect: &Vec<(i64, i64)>) -> i64 {
    let mut ac = rect[0].0;
    for p in rect.iter() { ac = max(ac, p.0); }
    ac
}
fn miny(rect: &Vec<(i64, i64)>) -> i64 {
    let mut ac = rect[0].1;
    for p in rect.iter() { ac = min(ac, p.1); }
    ac
}
fn maxy(rect: &Vec<(i64, i64)>) -> i64 {
    let mut ac = rect[0].1;
    for p in rect.iter() { ac = max(ac, p.1); }
    ac
}

