use std::io;

fn sum_digits(n : u16) -> u16 {
    let mut num = n;
    let mut sum = 0;
    while num != 0 {
        sum += num % 10;
        num /= 10;
    }
    sum
}

fn to_div_four(n : u16) -> u16 {
    let m = n % 4;
    if m == 0 {
        0
    } else {
        4 - m
    }
}

