fn largest_prime_factor(mut n: u32) -> u32 {
    let mut k = 2;
    let mut last_factor = 1;
    while k*k <= n {
        while n % k == 0 {
            n = n / k;
            last_factor = k;
        }
        k += 1;
    }
    if n > 1 { n } else { last_factor }
}

fn candidate(n: u32) -> u32 {
    let p = largest_prime_factor(n);
    if p == n {
        n
    } else {
        n - p + 1
    }
}

