use std::cmp::*;

fn run() {
    input! {
        seed: (i64, i64),
        a: (i64, i64),
        b: (i64, i64),
        s: (i64, i64),
        t: i64,
    }
    let mut p = vec![];
    let mut state = seed;
    while state.0 <= s.0 + t && state.1 <= s.1 + t {
        p.push(state);
        state = (a.0 * state.0 + b.0, a.1 * state.1 + b.1);
    }
    let n = p.len();
    let dis = |a: (i64, i64), b: (i64, i64)| -> i64 {
        (a.0 - b.0).abs() + (a.1 - b.1).abs()
    };
    let mut ans = 0;
    for i in 0..n {
        let mut cnt = 0;
        let mut now = s;
        let mut next = i;
        let mut rem = t;
        while next < n && dis(now, p[next]) <= rem {
            rem -= dis(now, p[next]);
            now = p[next];
            next += 1;
            cnt += 1;
        }
        ans = max(ans, cnt);
    }
    for i in (0..n).rev() {
        let mut cnt = 0;
        let mut now = s;
        let mut next = i;
        let mut rem = t;
        while next < n && dis(now, p[next]) <= rem {
            rem -= dis(now, p[next]);
            now = p[next];
            next -= 1;
            cnt += 1;
        }
        ans = max(ans, cnt);
    }
    println!("{}", ans);
}

fn main() {
    run();
}

