    let y0: i64 = scan();
    let ax: i64 = scan();
    let ay: i64 = scan();
    let bx: i64 = scan();
    let by: i64 = scan();
    let xs: i64 = scan();
    let ys: i64 = scan();
    let t: i64 = scan();

    let limit = 2_000_000_000_000_000_0;
    assert!(limit * 100 > 0);
    let mut cur_x = x0;
    let mut cur_y = y0;
    let mut vertexes = Vec::new();
    loop {
        vertexes.push((cur_x, cur_y));
        cur_x = cur_x * ax + bx;
        cur_y = cur_y * ay + by;
        if cur_x > limit || cur_y > limit {
            break;
        }
    }

    let n = vertexes.len();
    let mut ans = 0;
    for _ in 0..2 {
        for c in 0..n {
            let mut cost_a = 0;
            let mut get_a = 0;
            for a in (0..c + 1).rev() {
                let from = if a == c { (xs, ys) } else { vertexes[a + 1] };
                let to = vertexes[a];
                cost_a += cost(from, to);
                if cost_a > t {
                    break;
                }
                get_a += 1;

                ans.set_max(get_a);

                let mut cost_b = 0;
                let mut get_b = 0;
                for b in c + 1..n {
                    let from = if b == c + 1 {
                        vertexes[a]
                    } else {
                        vertexes[b - 1]
                    };
                    let to = vertexes[b];
                    cost_b += cost(from, to);
                    if cost_b + cost_a > t {
                        break;
                    }
                    get_b += 1;
                    ans.set_max(get_a + get_b);
                }
            }
        }
        vertexes.reverse();
    }

    println!("{}", ans);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}

