fn cost_to_one(n : u64, k : u64, a : u64, b : u64) -> u64 {
    let mut c = 0;
    let mut x = n;
    if k == 1 {
        c = (x - 1) * a; 
    } else {
        loop {
            if x < 1 {
                panic!("x is less than 1!");
            } else if x == 1 {
                break;
            } else if x < k {
                c = c + (a * (x - 1));
                x = 1;
            } else {
                let q = x / k;
                let r = x % k;
                let cost_div = b;
                let cost_sub = a * ((q * k) - q);
                if r == 0 {
                    if cost_div <= cost_sub {
                        c = c + cost_div;
                    } else {
                        c = c + cost_sub;
                    }
                    x = q;
                } else {
                    c = c + (r * a);
                    x =  x - r;
                }
            }
        }
    }
    c
}

