fn solve<Inner: BufRead, Output: Write>(inf: &mut Input<Inner>, ouf: &mut Output) {
	let (mut n, k, a, b) = read!(inf,i64,i64,i64,i64);
	if k == 1 {
		writeln!(ouf, "{}", (n - 1) * a);
		return;
	}
	let mut ans = 0i64;
	while n > 1 {
		if n < k {
			ans += (n - 1) * a;
			break;
		}
		ans += (n % k) * a;
		n -= n % k;

		ans += min(b, (n - n / k) * a);
		n /= k;
	}
	writeln!(ouf, "{}", ans);
}

