const N: usize = 19;

fn main() {
    let mut input = String::new();
    use std::io::{self, prelude::*};
    io::stdin().read_to_string(&mut input).unwrap();

    let n: u64 = input.trim().parse().unwrap();

    let fact: Vec<u64> = std::iter::once(1).chain((1..N).scan(1, |state, x| {
        *state *= x as u64;
        Some(*state)
    })).collect();

    let mut dl = Vec::with_capacity(N);

    let mut t = n;
    while t > 0 {
        let r = t % 10;
        dl.push(r);
        t /= 10;
    }

    let mut ms = [0; 10];
    for d in dl {
        ms[d as usize] += 1;
    }

    let binc = |k: usize, n: usize| -> u64 {
        fact[n] / fact[k] / fact[n - k]
    };

    let cnt = |ms: &[usize; 10], c: usize, zc: usize| -> u64 {
        if c == 0 {
            0
        } else {
            let mut ret_val = fact[c];
            for &c in &ms[1..] {
                ret_val /= fact[c];
            }
            ret_val *= binc(ms[0], c + zc - 1);
            ret_val
        }
    };

    let mut curc = 0;
    let mut curzc = 0;

    let first = {
        let mut t = [0; 10];
        if ms[0] > 0 {
            t[0] = 1;
            curzc += 1;
        }
        for (&c, t) in ms.iter().zip(t.iter_mut()).skip(1) {
            if c > 0 {
                *t = 1;
                curc += 1;
            }
        }
        t
    };

    let mut ans = 0;
    let mut cur = first;
    'outer: loop {
        let c = cnt(&cur, curc, curzc);
        ans += c;
        for di in 0..10 {
            if cur[di] == ms[di] {
                if di == 9 {
                    break 'outer;
                }
                if di == 0 {
                    curzc -= cur[di] - first[di];
                } else {
                    curc -= cur[di] - first[di];
                }
                cur[di] = first[di];
            } else {
                cur[di] += 1;
                if di == 0 {
                    curzc += 1;
                } else {
                    curc += 1;
                }
                break;
            }
        }
    }

    println!("{}", ans);
}

