#[derive(Copy, Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct Clock {
    time: i32,
}

impl Clock {
    pub fn new (hh: i32, mm: i32) -> Self {
        Self {
            time: Clock::hhmm_to_time(hh, mm)
        }
    }
    pub fn hh(&self) -> i32 {
        self.time / 60
    }
    pub fn mm(&self) -> i32 {
        self.time % 60
    }
    fn hhmm_to_time(hh: i32, mm: i32) -> i32 {
        hh * 60 + mm
    }
    fn time_to_hhmm(t: i32) -> (i32, i32) {
        (t / 60, t % 60)
    }
}

impl Sub<i32> for Clock {
    type Output = Clock;
    fn sub(mut self, m: i32) -> Clock {
        let day = 24 * 60;
        let m = m % day;
        self.time = (self.time + day - m) % day;
        self
    }
}

fn find_lucky(c: &Clock) -> bool {
    if c.hh() / 10 == 7 || c.hh() % 10 == 7 || c.mm() / 10 == 7 || c.mm() % 10 == 7 {
        true
    } else {
        false
    }
}

