    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            id: 0,
            buf: Vec::new(),
        }
    }
    fn next_line(&mut self) -> Option<String> {
        let mut res = String::new();
        match self.stdin.read_line(&mut res) {
            Ok(0) => return None,
            Ok(_) => Some(res),
            Err(why) => panic!("error in read_line: {}", why.description()),
        }
    }
    fn next<T: FromStr>(&mut self) -> Option<T> {
        while self.buf.len() == 0 {
            self.buf = match self.next_line() {
                Some(r) => {
                    self.id = 0;
                    r.trim().as_bytes().to_owned()
                }
                None => return None,
            };
        }
        let l = self.id;
        assert!(self.buf[l] != b' ');
        let n = self.buf.len();
        let mut r = l;
        while r < n && self.buf[r] != b' ' {
            r += 1;
        }
        let res = match str::from_utf8(&self.buf[l..r]).ok().unwrap().parse::<T>() {
            Ok(s) => Some(s),
            Err(_) => panic!("parse error"),
        };
        while r < n && self.buf[r] == b' ' {
            r += 1;
        }
        if r == n {
            self.buf.clear();
        } else {
            self.id = r;
        }
        res
    }
    fn ne<T: FromStr>(&mut self) -> T {
        self.next::<T>().unwrap()
    }
}

use std::io::stdin;
use std::cmp::min;

fn main() {
    let mut input_line = String::new();
    stdin().read_line(&mut input_line);

    let input_iter = input_line.
        split_whitespace().
        map(|x| x.parse::<u64>().unwrap());

    let input: Vec<_> = input_iter.collect();

    let owned = input[0];
    if owned % 4 == 0 {
        // Already meet criteria
        println!("0");
        return;
    }

    let purchase = (4 - owned % 4) as usize;

    let mut dp = vec![u64::max_value(); 12];
    dp[0] = 0;

    for i in 0..12 {
        for j in 1..4 {
            if i >= j {
                dp[i] = min(dp[i - j] + input[j], dp[i]);
            }
        }
    }

    println!("{}", min(min(dp[purchase], dp[purchase + 4]), dp[purchase + 8]));
}

use std::io::stdin;
use std::cmp::min;

fn main() {
    let mut input_line = String::new();
    stdin().read_line(&mut input_line);

    let mut input_iter = input_line.
        split_whitespace().
        map(|x| x.parse::<u64>().unwrap());

    let owned = input_iter.next().unwrap();
    let price1 = input_iter.next().unwrap();
    let price2 = input_iter.next().unwrap();
    let price3 = input_iter.next().unwrap();

    if owned % 4 == 0 {
        // Already meet criteria
        println!("0");
        return;
    }

    let purchase = 4 - owned % 4;
    let result = match purchase {
        1 => min(price1, min(price3 * 3, price2 + price3)),
        2 => min(price2, min(price1 * 2, price3 * 2)),
        3 => min(price3, min(price1 * 3, price2 + price1)),
        _ => u64::max_value()
    };

    println!("{}", result);
}

