mod my_ios {
	use std::io::{BufRead, ErrorKind, Result};
	use std::str::{FromStr, from_utf8};
	use std::fmt::Debug;

	pub fn read_token<R:BufRead>(r:&mut R, buf:&mut Vec<u8>) -> Result<usize> {
		let mut read = 0;
		loop {
			let (done, used) = {
				let avail = match r.fill_buf() {
					Ok(n) => n,
					Err(ref e) if e.kind() == ErrorKind::Interrupted => continue,
					Err(e) => return Err(e)
				};
				match avail.iter().position(|&x| x == b'\n' || x== b' ') {
					Some(i) => {
						buf.extend_from_slice(&avail[..i]);
						(true, i + 1)
					}
					None => {
						buf.extend_from_slice(avail);
						(false, avail.len())
					}
				}
			};
			r.consume(used);
			read += used;
			if done || used == 0 {
				return Ok(read);
			}
		}
	}

	pub struct InputReader<R:BufRead> {
		reader:R,
		buf:Vec<u8>,
	}

	impl<R:BufRead> InputReader<R> {
		pub fn new(reader: R) -> InputReader<R> {
			InputReader {
				reader:reader,
				buf:Vec::<u8>::new(),
			}
		}
		pub fn read_token(&mut self) {
			read_token(&mut self.reader, &mut self.buf);
		}
		pub fn read<T>(&mut self) -> T where T:FromStr, T::Err:Debug {
			self.buf.clear();
			self.read_token();
			from_utf8(&self.buf).unwrap().trim().parse().unwrap()
		}
	}
}

