fn rev(n:u64) -> u64 {
    let mut rev:u64 = 0;
    let mut n = n;
    while n>0 {
        rev*=10;
        rev+=n%10;
        n/=10;
    }
    return rev;
}

fn num_digits(n:u64) -> u32 {
    let mut d:u32 = 0;
    let mut n = n;
    while n>0 {
        n/=10;
        d+=1;
    }
    return d;
}

fn zcy(n:u64) -> u64{
    n*(10u64.pow(num_digits(n)))+rev(n)
}

