use std::io;
use std::io::BufRead;

type Grid = Vec<Vec<usize>>;

fn valid_index(index: isize) -> bool {
    index >= 0 && index <= 2
}

fn get_position(grid: &Grid, x: isize, y: isize) -> usize {
    if !valid_index(x) || !valid_index(y) {
        0
    } else {
        *grid.get(y as usize).and_then(|n| n.get(x as usize).or(Some(&0))).unwrap_or(&0)
    }
}

fn main() {
    let numbers: Grid = io::stdin()
        .lock()
        .lines()
        .take(3)
        .map(|line| line.expect("failed to read line")
                .trim()
                .split(" ")
                .map(|number| number.parse::<usize>().expect("failed to parse number"))
                .collect()
            )
        .collect();

    for y in 0 as isize..3 {
        for x in 0 as isize..3 {
            let mut n = get_position(&numbers, x, y);
            n += get_position(&numbers, x, y - 1);
            n += get_position(&numbers, x, y + 1);
            n += get_position(&numbers, x - 1, y);
            n += get_position(&numbers, x + 1, y);
            print!("{}", match n % 2 {
                0 => 1,
                1 => 0,
                _ => unreachable!()
            });
        }
        println!("");
    }
}

