use std::io;
use std::io::{Error, ErrorKind};
use std::str::FromStr;

struct IO {
    buffer: Vec<String>
}

impl IO {
    fn new() -> IO {
        IO { buffer: Vec::new() }
    }
    /*
    pub fn reset(&mut self) {
        self.buffer = Vec::new();
    }
    */

    fn try_parse<T>(s: String) -> Result<T, T::Err> 
        where T: FromStr {
        let res = (&s).parse::<T>()?;
        Ok(res)
    }

    fn receive<T>(&mut self) -> Result<T, Error> 
        where T: FromStr {
        let ref mut stdio = &mut io::stdin();
        if let Some(s) = self.buffer.pop() {
            return match IO::try_parse::<T>(s) {
                Ok(value) => Ok(value),
                _ => Err(Error::new(ErrorKind::Other, "cannot parse to desired type"))
            }
        }

        let mut input = String::new();
        if let Err(error) = stdio.read_line(&mut input) {
            return Err(error)
        }

        input = input.trim().to_string();

        self.buffer.extend::<Vec<String> >(input.split(' ').map(|s| s.to_string()).collect());

        return self.receive::<T>()
    }
}

