struct FactModCache<const MODVAL: i64> {
    fact: Vec<i64>,
    inv: Vec<i64>,
    n: i64,
}

impl<const MODVAL: i64> FactModCache<MODVAL> {
    fn new(n: usize) -> FactModCache<MODVAL> {
        let mut fmc = FactModCache {
            ..Default::default()
        };
        fmc.fact.resize(n, 0);
        fmc.inv.resize(n, 0);
        fmc.fact[0] = 1;
        fmc.inv[0] = 1;
        fmc.n = n as i64; //set this after so the calculation doesn't return cached value
        for i in 1..n {
            fmc.fact[i] = fmc.mult_mod(fmc.fact[i - 1], i as i64);
            fmc.inv[i] = fmc.inv_mod(fmc.fact[i]);
        }
        fmc
    }

    fn factorial_mod(&self, n: i64) -> i64 {
        if n < self.n {
            return self.fact[n as usize];
        }
        let mut t = self.fact[self.n as usize - 1];
        for x in self.n..=n {
            t = (t * x) % MODVAL;
        }
        t
    }

    fn permutations_mod(&self, n: i64, r: i64) -> i64 {
        let a = self.factorial_mod(n);
        let b = self.inv_fact_mod(n - r);
        return self.mult_mod(a, b);
    }

    fn inv_fact_mod(&self, n: i64) -> i64 {
        if n < self.n {
            return self.inv[n as usize];
        }
        self.pow_mod(self.factorial_mod(n), MODVAL - 2)
    }

    fn inv_mod(&self, n: i64) -> i64 {
        self.pow_mod(n, MODVAL - 2)
    }

    fn combinations_mod(&self, n: i64, r: i64) -> i64 {
        let a = self.factorial_mod(n);
        let b = self.inv_fact_mod(r);
        let c = self.inv_fact_mod(n - r);
        return self.mult_mod(self.mult_mod(a, b), c);
    }

    fn pow_mod(&self, mut base: i64, mut pow: i64) -> i64 {
        if pow == 0 {
            return 1;
        }
        let mut result = 1;
        while pow > 0 {
            if pow & 1 == 1 {
                result = (result * base) % MODVAL;
            }
            pow /= 2;
            base = (base * base) % MODVAL;
        }
        result
    }

    fn mult_mod(&self, a: i64, b: i64) -> i64 {
        let a = a as i128;
        let b = b as i128;
        ((a * b) % MODVAL as i128) as i64
    }

    fn add_mod(&self, a: i64, b: i64) -> i64 {
        ((a % MODVAL) + (b % MODVAL)) % MODVAL
    }
}

