fn solve_wrapper<B,W,F>(scan: &mut Scanner<B>, out: &mut W, mut solve: F)
    where B: BufRead, W: Write, F:FnMut(&mut Scanner<B>, &mut W)
    {
    let t = 1;
    //let t = scan.token::<usize>();
    for _ in 0..t {
        solve(scan,out);
