}

const MOD:usize = 1e9 as usize + 7;

fn solve(scan: &mut Scanner<impl BufRead>, out: &mut impl Write) {
    let n = scan.token::<usize>();
    let k = scan.token::<usize>();
    let cmb = Combi::<MOD>::new(n);
    cmb.kcombi(n,k);
    let mut ans = 0;
    for i in 0..(k.min(n)+1) {
        ans+=cmb.kcombi(n,i);
        ans%=MOD;
    }
    writeln!(out, "{}", ans).ok();
}

pub mod solution {

use std::cmp::min;
use crate::io::input::Input;
use crate::io::output::output;
use crate::{out, out_line};

fn solve(input: &mut Input, _test_case: usize) {
    let (n, k) = input.read();
    let mut ans = 0;
    let mut fact = vec![0; n + 1];
    let mut inv = vec![0; n + 1];
    let mut invfact = vec![0; n + 1];
    inv[1] = 1;
    for i in 2..=n {
        inv[i] = mul(inv[(MOD % i as i32) as usize], MOD - MOD / i as i32);
    }
    fact[0] = 1;
    invfact[0] = 1;
    for i in 1..=n {
        fact[i] = mul(fact[i - 1], i as i32);
        invfact[i] = mul(invfact[i - 1], inv[i]);
    }
    for i in 0..=min(k, n) {
        add(&mut ans, c(n, i, &fact, &invfact));
    }
    out_line!(ans);
}

fn c(n: usize, k: usize, fact: &Vec<i32>, invfact: &Vec<i32>) -> i32 {
    mul(fact[n], mul(invfact[k], invfact[n - k]))
}

fn add(a: &mut i32, b: i32) {
    *a += b;
    if *a >= MOD {
        *a -= MOD;
    }
}

const MOD: i32 = 1000000007;

fn mul(a: i32, b: i32) -> i32 {
    (a as i64 * b as i64 % MOD as i64) as i32
}


pub(crate) fn run(mut input: Input) -> bool {
    solve(&mut input, 1);
    output().flush();
    input.skip_whitespace();
    !input.peek().is_some()
}


