#[allow(dead_code)]
fn bi_coefficient_mod(n: u64, k: u64, fact: &FactorialsMod, modval: u64) -> u64 {
    if n == k {
        return 1;
    }
    let mut res = fact.get(n as usize).unwrap();
    res *= mod_inverse(fact.get(k as usize).unwrap(), modval);
    res %= modval;
    res *= mod_inverse(fact.get((n - k) as usize).unwrap(), modval);
    res %= modval;
    res
}

#[allow(dead_code)]
fn pow_mod(a: u64, b: u64, modval: u64) -> u64 {
    let mut a = a % modval;
    if a == 0 {
        return 0;
    }
    let mut b = b;
    let mut res = 1u64;
    while b > 0 {
        if b & 1 != 0 {
            res *= a;
            res %= modval;
            b -= 1;
        }
        a *= a;
        a %= modval;
        b >>= 1;
    }
    res
}

#[allow(dead_code)]
fn mod_inverse(a: u64, modval: u64) -> u64 {
    pow_mod(a, modval - 2, modval)
}

