use std::io::Read;
use std::collections::HashMap;

fn main() {
    let mut stdin = String::new();
    io::stdin().read_to_string(&mut stdin).unwrap();
    let mut stdin = stdin.split_whitespace();
    let mut get = || stdin.next().unwrap();
    macro_rules! get {
        ($t:ty) => (get().parse::<$t>().unwrap());
    }

    let n = get!(usize);
    let need = get!(u64);

    let mut costs = vec![0; n];

    for i in 0..n {
        costs[i] = get!(u64);
    }

    fn search(costs: &Vec<u64>, need: u64, memo: &mut HashMap<u64,u64>) -> u64 {
        if let Some(p) = memo.get(&need) {
            return *p;
        }
        let mut best_payment = 0;
        for i in 0..costs.len() {
            let liters = 1 << i;
            if liters < need {
                let bottles = need / liters;
                let remains = need-bottles*liters;
                let payment = bottles*costs[i]; 
                let payment = if remains > 0 {
                    payment+search(costs, remains, memo)
                } else {
                    payment
                };
                if payment < best_payment || best_payment == 0 {
                    best_payment = payment;
                }
            } else {
                let payment = costs[i];
                if payment < best_payment || best_payment == 0 {
                    best_payment = payment;
                }
            }
        }
        memo.insert(need, best_payment);
        best_payment
    }
    let best_payment = search(&costs, need, &mut HashMap::new());
    println!("{}", best_payment);
}

