fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }
    input!(n: i64, m: i64, l: i64, r: i64);
    let a = (n * m + 1) / 2;
    let b = n * m - a;
    let d = r / 2 - (l - 1) / 2;
