fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: u32 = it.next().unwrap().parse().unwrap();
    let k: usize = it.next().unwrap().parse().unwrap();
    let mut is_prime = vec![true; k + 1];
    for i in 2.. {
        if i * i > k {
            break;
        }
        if is_prime[i] {
            let mut j = i * i;
            while let Some(p) = is_prime.get_mut(j) {
                *p = false;
                j += i;
            }
        }
    }
    let mut mobius = vec![ModInt::one(); k + 1];
    for (i, p) in is_prime.into_iter().enumerate().skip(2) {
        if !p {
            continue;
        }
        let mut j = i;
        while let Some(x) = mobius.get_mut(j) {
            *x = -*x;
            j += i;
        }
        let k = i.saturating_mul(i);
        let mut j = k;
        while let Some(x) = mobius.get_mut(j) {
            *x = ModInt::zero();
            j += k;
        }
    }
    let pow: Vec<ModInt> = (0..=k).map(|k| ModInt::from(k).pow(n)).collect();
    let mut imos = vec![ModInt::zero(); 2 * k + 1];
    for (i, v) in mobius.into_iter().enumerate().skip(2) {
        if v.0 == 0 {
            continue;
        }
        for (x, &pow) in pow.iter().enumerate().skip(1) {
            if x * i > k {
                break;
            }
            let v = v * pow;
            let l = x * i;
            let r = (x + 1) * i;
            imos[l] += v;
            imos[r] -= v;
        }
    }
    let mut ans = ModInt::zero();
    for i in 1..=k {
        imos[i] = imos[i] + imos[i - 1];
        let way = ModInt::from(i).pow(n) + imos[i];
        ans += ModInt::new(way.0 ^ i as u32);
    }
    println!("{}", ans);
}

fn main() {
    run();
}

