fn prime_factorization(n: i64) -> Vec<(i64,usize)> {
    let mut res = vec![];
    let mut x = n;
    let mut i = 2;
    while i * i <= x {
        let mut count = 0;
        while x % i == 0 {
            count += 1;
            x /= i;
        }
        if count != 0 {
            res.push((i, count));
        }
        i += 1;
    }
    if x != 1 {
        res.push((x,1));
    }
    res
}

fn dfs(ps: &Vec<(i64,usize)>, table: &Vec<Vec<Mod>>, i: usize, x: i64, prob: Mod) -> Mod {
    if i == ps.len() {
        return prob * Mod::new(x as u64);
    }
    let mut res = Mod::new(0);
    for k in 0..ps[i].1+1 {
        res += dfs(ps, table, i+1, x * ps[i].0.pow(k as u32), prob * table[i][k]);
    }
    res
}

fn main() {
    input! {
        n: i64,
        m: u64,
    }
    let ps = prime_factorization(n);

    let mut inv_table = vec![Mod::new(1), Mod::new(1)];
    for i in 2..1000 {
        inv_table.push(Mod::new(1) / Mod::new(i));
    }

    let mut table = vec![];
    for &(p,count) in &ps {
        let mut dp = vec![Mod::new(0); count+1];
        dp[count] = Mod::new(1);
        for _ in 0..m {
            let mut dp2 = vec![Mod::new(0); count+1];
            for j in 0..count+1 {
                for k in 0..j+1 {
                    // dp2[k] += dp[j] / Mod((j+1) as u64);
                    dp2[k] += dp[j] * inv_table[j+1];
                }
            }
            dp = dp2;
        }
        table.push(dp);
    }

    let res = dfs(&ps, &table, 0, 1, Mod::new(1));
    println!("{}", res.0);
}

use std::ops::*;

const MOD : u64 = 1_000_000_007;
#[derive(Clone,Copy,PartialEq,Debug)]
pub struct Mod (pub u64);

impl Mod {
    pub fn new(x: u64) -> Mod {
        Mod(x % MOD)
    }
    pub fn pow(self, n: u64) -> Mod {
        if n == 0 {
            return Mod(1);
        }
        let t = self.pow(n/2);
        if n % 2 == 0 {
            t * t
        }
        else {
            t * t * self
        }
    }
}

impl Add for Mod {
    type Output = Self;
    fn add(self, rhs: Self) -> Self::Output {
        Mod((self.0 + rhs.0) % MOD)
    }
}

impl AddAssign for Mod {
    fn add_assign(&mut self, rhs: Self) {
        *self = *self + rhs;
    }
}

impl Sub for Mod {
    type Output = Self;
    fn sub(self, rhs: Self) -> Self::Output {
        Mod((self.0 + MOD - rhs.0 % MOD) % MOD)
    }
}

impl SubAssign for Mod {
    fn sub_assign(&mut self, rhs: Self) {
        *self = *self - rhs;
    }
}

impl Neg for Mod {
    type Output = Mod;
    fn neg(self) -> Mod {
        Mod(MOD - self.0)
    }
}

impl Mul for Mod {
    type Output = Self;
    fn mul(self, rhs: Self) -> Self::Output {
        Mod((self.0 % MOD) * (rhs.0 % MOD) % MOD)
    }
}

impl MulAssign for Mod {
    fn mul_assign(&mut self, rhs: Self) {
        *self = *self * rhs;
    }
}

impl Div for Mod {
    type Output = Self;
    fn div(self, rhs: Self) -> Self::Output {
        if rhs.0 == 0 {
            loop {}
        }
        assert!(rhs.0 != 0);
        self * rhs.pow(MOD-2)
    }
}

