pub fn factor(input: u64) -> Vec<u64> {
    let mut vector = vec![];

    let mut i = 1;
    while i * i <= input {
        if input % i == 0 {
            vector.push(i);
            if i != input / i {
                vector.push(input / i);
            }
        }
        i += 1;
    }

    vector
}

