const MOD: usize = 1000000007;


fn count_good_sequences(n: usize, k: usize) -> usize {
    let mut d: Vec<Vec<usize>> = vec![vec![0; n + 1]; k + 1];
    d[1] = vec![1; n + 1];
    d[1][0] = 0;

    for length in 2..=k {
        for x in 1..=n {
            for t in (x..=n).step_by(x) {
                d[length][t] += d[length - 1][x];
                d[length][t] %= MOD;
            }
        }
    }
    // dbg!(&d);
    let mut sum: usize = 0;
    for x in d.last().unwrap() {
        sum += x;
        sum %= MOD;
    }
    sum
