fn foo(a: u64, b:u64) -> (u64, u64) {
  if a == 0 || b == 0 {
    (a, b)
  } else if a >= 2*b {
    foo(a % (2*b), b)
  } else if b >= 2*a {
    foo(a, b % (2*a))
  } else {
    (a, b)
  }
}

