fn process(a : u64, b : u64) -> (u64, u64) {
    let mut m_a = a;
    let mut m_b = b;
    loop {
        if (m_a == 0) || (m_b == 0) {
            break;
        } else {
            let two_m_a = 2 * m_a;
            let two_m_b = 2 * m_b;
            if m_a >= two_m_b {
                m_a = m_a % two_m_b;
            } else if m_b >= two_m_a {
                m_b = m_b % two_m_a;
            } else {
                break;
            }
        }
    }
    (m_a, m_b)
}

