fn zeros_fac(n : u32) -> u32 {
    let mut i = 5;
    let mut count = 0;
    while i <= n {
        count += n / i;
        i *= 5;
    }
    count
}

fn bsearch(mut pi : u32, mut pf : u32, n : u32) -> Option<u32> {
    while pf >= pi {
        let pm = (pf + pi) / 2;
        let zeros_pm = zeros_fac(5 * pm);
        if zeros_pm < n {
            pi = pm + 1;
        } else if zeros_pm == n {
            return Some(5 * pm);
        } else {
            pf = pm - 1;
        }
    }
    return None;
}

