fn c(n: i64, k: i64) -> i64 {
    if k > n {
        return 0;
    }
    let mut result = 1;
    if k > n - k {
        for i in k + 1..n + 1 {
            result *= i;
        }
        for i in 1..n - k + 1 {
            result /= i;
        }
    }
    if k <= n - k {
        for i in n - k + 1..n + 1 {
            result *= i;
        }
        for i in 1..k + 1 {
            result /= i;
        }
    }
    return result;
}

