fn read_u32() -> u32 {
    let mut line = String::new();
    std::io::stdin().read_line(&mut line).unwrap();
    line.trim().parse().unwrap()
}

fn convert_a(a: &mut u32, d: &mut u32, cost: u32) -> u32 {

    let a_amount = *a.min(d);
    *a -= a_amount;
    *d -= a_amount;

    a_amount * cost
}

fn convert_b(b: &mut u32, c: &mut u32, d: &mut u32, cost: u32) -> u32 {

    let b_amount = *b.min(c).min(d);
    *b -= b_amount;
    *c -= b_amount;
    *d -= b_amount;

    b_amount * cost
}

