    let mut d = read_u32();

    let cost_a = read_u32();
    let cost_b = read_u32();

    let mut rev = 0;

    if cost_a > cost_b {

        rev += convert_a(&mut a, &mut d, cost_a);
        rev += convert_b(&mut b, &mut c, &mut d, cost_b);

    } else {

        rev += convert_b(&mut b, &mut c, &mut d, cost_b);
        rev += convert_a(&mut a, &mut d, cost_a);

    }

    println!("{}", rev);
