use std::cmp::Reverse;

fn main() {
    let mut aa: Vec<char> = util::line().chars().collect();
    let bb: Vec<char> = util::line().chars().collect();

    let mut amap = HashMap::new();
    let mut bmap = HashMap::new();

    for &a in &aa {
        *amap.entry(a).or_insert(0) += 1;
    }

    for &b in &bb {
        *bmap.entry(b).or_insert(0) += 1;
    }

    if amap == bmap {
        println!(
            "{}",
            bb.iter()
                .map(|x| x.to_string())
                .collect::<Vec<_>>()
                .join("")
        );
        return;
    }

    if aa.len() < bb.len() {
        aa.sort_by_key(|&x| Reverse(x));
        println!(
            "{}",
            aa.iter()
                .map(|x| x.to_string())
                .collect::<Vec<_>>()
                .join("")
        );
        return;
    }

    let ans = (0..aa.len())
        .filter_map(|i| {
            let mut res = Vec::new();
            let mut amap = amap.clone();

            for &b in &bb[..i] {
                let c = amap.entry(b).or_insert(0);
                if *c > 0 {
                    *c -= 1;
                    res.push(b);
                } else {
                    return None;
                }
            }

            if let Some((&x, _)) = amap.iter().filter(|&(&k, &v)| v > 0 && k < bb[i]).max() {
                res.push(x);
                *amap.entry(x).or_insert(0) -= 1;
            } else {
                return None;
            }

            let mut rest = Vec::new();
            for (&k, &v) in amap.iter() {
                for _ in 0..v {
                    rest.push(k);
                }
            }

            rest.sort_by_key(|&x| Reverse(x));

            res.append(&mut rest);

            Some(res)
        })
        .max()
        .unwrap();

    println!(
        "{}",
        ans.iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join("")
    );
}

