fn prime_factorization(mut n: u64) -> Vec<(u64, u64)> {
    let mut i = 2;
    let mut ans = vec![];
    while i*i <= n {
        let mut cnt = 0;
        while n%i == 0 {
            n /= i;
            cnt += 1;
        }
        if cnt > 0 {
            ans.push((i, cnt));
        }
        i += 1;
    }
    if n > 1 {
        ans.push((n, 1));
    }
    ans
}

fn fact_num(n: u64, v: u64) -> u64 {
    if n < v {
        return 0;
    }
    let div = n/v;
    div + fact_num(div, v)
}


fn main() {
    input!{
      n: u64,
      b: u64,
    }
    let facts = prime_factorization(b);
    let mut ans: i64 = -1;
    for i in 0..facts.len() {
        let (v, pow) = facts[i];
        let fnum = fact_num(n, v);
        if ans == -1 {
            ans = (fnum/pow) as i64;
        } else {
            ans = min(ans, (fnum/pow) as i64);
        }
    }
    println!("{}", ans);
}

