fn factor(mut n: i64) -> Vec<(i64, i64)> {
    let mut fs: Vec<(i64, i64)> = Vec::new();
    for i in 2..((n as f64).sqrt().ceil() as i64 + 1) {
        let mut cnt = 0i64;
        while n % i == 0 {
            n /= i;
            cnt += 1;
        }
        if cnt > 0 {
            fs.push((i as i64, cnt));
        }
    }
    if n > 1 {
        fs.push((n, 1));
    }
    fs
}

fn count(n: i64, p: i64) -> i64 {
    let mut c = 0i64;
    let mut b = p;
    while n >= b {
        c += n / b;        
        //println!("n = {}, b = {}, n/b = {}", n, b, n/b);

        if n/b >= p {
            b *= p;
        } else {
            break;
        }
    }
    c
}

