const MAX_DIFF: i32 = 90;

fn digit_sum(n: i32) -> i32 {
    let mut result = 0;
    let mut t = n;
    while t > 0 {
        result = result + (t % 10);
        t = t / 10;
    }
    result
}

fn solve(n: i32) -> Vec<i32> {
    let mut result: Vec<i32> = Vec::new();
    for x in 1..MAX_DIFF {
        let t = n - x;
        if digit_sum(t) == x {
            result.push(t);
        }
    }
    result
}

