fn nums(digs: &Vec<Vec<i32>>) -> Vec<i32> {
    if digs.is_empty() { vec![0] } else {
        digs.iter()
            .enumerate()
            .flat_map(|(i, v)| {
                let mut v1 = digs.clone();
                v1.remove(i);
