fn extended_euclid(a: i64, b: i64) -> (i64, i64, i64) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (d0, x0, y0) = extended_euclid(b, a % b);
        (d0, y0, x0 - a / b * y0)
    }
}

fn main() {
    let n: usize = get_line().trim().parse().unwrap();

    let cubes: Vec<_> = BufReader::new(io::stdin()).lines()
        .map(|s| {
            let s = s.unwrap();
            let mut cube = [false; 10];
            for s in s.split_whitespace() {
                let d = s.bytes().last().unwrap();
                let d = (d - b'0') as usize;
                cube[d] = true;
            }
            cube
        }).collect();

    let perms = match n {
