        ],
        2 => vec![
            vec![0, 1],
            vec![1, 0],
        ],
        1 => vec![vec![0]],
        _ => panic!(""),
    };


    let fact = |n| {
        let mut ret_val = 1;
        for i in 0..n {
            ret_val *= i + 1;
        }
        ret_val
    };

    let check = |x| {
        let x = format!("{}", x);
        for perm in perms.iter().take(fact(n)) {
            let p = x.bytes().map(|b| (b - b'0') as usize)
                .zip(perm.iter()).all(|(d, &i)| cubes[i][d]);
            if p {
                return true;
            }
        }
        false
    };

    for i in 1.. {
        if !check(i) {
            println!("{}", i - 1);
            return;
        }
    }
