fn nums<'a>(digs: Vec<Vec<i32>>) -> Box<Iterator<Item=i32> + 'a> {
    if digs.is_empty() { Box::new(once(0)) } else {
        let d1 = digs.clone();
        Box::new(d1.into_iter()
            .enumerate()
            .flat_map(move |(i, v)| {
                let mut v1 = digs.clone();
                v1.remove(i);
                nums(v1)
                    .into_iter()
                    .flat_map(move |n|
                        v.clone()
                            .into_iter()
                            .map(move |d| n * 10 + d)
                            .chain(once(n)))
            }))
    }
}


