fn check(dice: &[[i32; 6]], digits: &[i32]) -> bool {
    if dice.len() < digits.len() {
        println!("a");
        false
    } else if digits.len() == 0 {
        true
    } else {
        let mut leftover_dice: Vec<[i32; 6]> = dice[1..].iter().cloned().collect();
        let mut has_solution = false;
        for (i, &die) in dice.iter().enumerate() {
            if die.iter().any(|&a| a == digits[0]) && check(&leftover_dice, &digits[1..]) {
                has_solution = true;
                break;
            }
            if i < leftover_dice.len() {
                leftover_dice[i] = die;
            }
        }
        has_solution
    }
}

fn main() {
    let n = scan_line!(i32);
    let mut dice = Vec::new();
    for _ in 0..n {
        let (a, b, c, d, e, f) = scan_line!(i32, i32, i32, i32, i32, i32);
        dice.push([a, b, c, d, e, f]);
    }
    let mut max_valid = 0;
    for i in 1.. {
        let mut digits = Vec::new();
        let mut j = i;
        while j > 0 {
            digits.push(j % 10);
            j /= 10;
        }
        let is_valid = check(&dice, &digits);
        if is_valid {
            max_valid = i;
        } else {
            break;
        }
    }
    println!("{}", max_valid);
}

