fn truc(i: usize, b: usize, v: &mut Vec<usize>) -> usize {
    v.push(i);
    if i == b {
        i
    } else if i % 10 == 1 && i > 1 {
        truc((i - 1) / 10, b, v)
    } else if i % 2 == 0 {
        truc(i / 2, b, v)
    } else {
        i
    }
}

