fn generate(value: i64, limit: i64, list: Vec<i64>, res: &mut Vec<i64>) {
    if value == limit {
        *res = list.clone();
    }

    let next_value = value * 2;
    if next_value <= limit {
        let mut v = list.clone();
        v.push(next_value);
        generate(next_value, limit, v, res);
    }
    let next_value = value * 10 + 1;
    if next_value <= limit {
        let mut v = list.clone();
        v.push(next_value);
        generate(next_value, limit, v, res);
    }
}

