fn partition(array: &mut [i32], mut left_index: usize, mut right_index: usize) -> usize {
    let pivot_element = array[(left_index + right_index) >> 1];
    loop {
        while array[left_index] < pivot_element {
            left_index += 1;
        }
        while array[right_index] > pivot_element {
            right_index -= 1;
        }
        if left_index >= right_index {
            break;
        }
        array.swap(left_index, right_index);
        left_index += 1;
        right_index -= 1;
    }
    return right_index;
}


fn qsort(array: &mut [i32], left: usize, right: usize) {
    if left < right {
        let p = partition(array, left, right);
        qsort(array, left, p);
        qsort(array, p + 1, right);
    }
}


