use std::{io, process};

fn main() {
	let n: u8 = {
		let mut line = String::new();
		io::stdin().read_line(&mut line).unwrap();
		line.trim().parse().unwrap()
	};

	let mut a: Vec<u8> = {
		let mut line = String::new();
		io::stdin().read_line(&mut line).unwrap();
		line.trim().split(' ').map(|a| a.parse().unwrap()).collect()
	};

	a.sort();

	// remove duplicates
	let mut i = a.len() - 1;
	loop {
		for j in (0..a.len()).rev() {
			if i == j {
				continue;
			}
			if a[i] == a[j] {
				if i > j {
					a.remove(i);
					a.remove(j);
				} else {
					a.remove(j);
					a.remove(i);
				}
				i -= 1;
				break;
			}
		}

		if i == 0 {
			break;
		}
		i -= 1;
	}

	assert!(a.len() % 2 == 0);

	let mut pb0 = 0u32;
	for s in a
		.iter()
		.enumerate()
		.filter(|s| s.0 % 2 == 0)
		.map(|s| *s.1)
		.zip(a.iter().enumerate().filter(|s| s.0 % 2 == 1).map(|s| *s.1))
	{
		pb0 += s.1 as u32 - s.0 as u32;
	}

	if a.len() < 3 {
		println!("{}", pb0);
		process::exit(0);
	}

	let mut pb1 = 0u32;
	let mut b: Vec<u8> = a
		.iter()
		.enumerate()
		.filter(|s| s.0 % 2 == 0)
		.map(|s| *s.1)
		.collect();
	b.remove(0);
	let lasti = b.len() - 1;
	b.remove(lasti);
	for s in a
		.iter()
		.enumerate()
		.filter(|s| s.0 % 2 == 1)
		.map(|s| *s.1)
		.zip(b)
	{
		pb1 += s.1 as u32 - s.0 as u32;
	}
	pb1 += a[a.len() - 1] as u32 - a[0] as u32;

	println!("{}", pb0.min(pb1));
}

