type Mint = ModInt1000000007;

fn main() {
    inputv! {
        n:usize,x:usize,pos:usize
    }
    let mut f = vec![Mint::new(1)];
    for i in 1..1000 {
        let l = *f.last().unwrap();
        f.push(l * Mint::new(i));
    }
    let mut r_count = 0;
    let mut l_count = 0;
    let mut left = 0;
    let mut right = n;
    while left < right {
        let mid = (left + right) / 2;
        if mid > pos {
            r_count += 1;
            right = mid;
        } else {
            l_count += 1;
            left = mid + 1;
        }
    }
    if left > 0 && left - 1 == pos {
        l_count -= 1;
    } else {
        println!("0");
        return;
    }
    //dbg!(l_count, r_count);
    if n - x < r_count || x - 1 < l_count {
        println!("0");
        return;
    }
    let mut ans = f[n - x] / f[n - x - r_count] * f[x - 1] / f[x - 1 - l_count]
        * f[n - l_count - r_count - 1];
    println!("{}", ans);
}

