fn is_prime(n: u64) -> bool {
    factorize(n).len() == 1
}

fn dp(graph: &Vec<Vec<usize>>, weights: &Vec<u64>, node: usize) -> (u64, u64, usize) {
    if graph[node].is_empty() {
        return (weights[node], 0, 1);
    }
    let weight = weights[node];
    let ans_vec = graph[node]
        .iter()
        .map(|neighbour| dp(graph, weights, *neighbour))
        .collect::<Vec<_>>();
    let max_ans = ans_vec
        .iter()
        .map(|(a, _residue, _leaves)| *a)
        .max()
        .unwrap();
    let sum_residue = ans_vec
        .iter()
        .map(|(a, res, leaves)| res + (max_ans - a) * (*leaves) as u64)
        .sum::<u64>();
    let total_leaves = ans_vec.into_iter().map(|(_a, _r, l)| l).sum::<usize>();
    if sum_residue >= weight {
        (max_ans, sum_residue - weight, total_leaves)
    } else {
        let residue = weight - sum_residue;
        (
            max_ans + ((residue + total_leaves as u64 - 1) / total_leaves as u64),
            residue % total_leaves as u64,
            total_leaves,
        )
    }
}

