const MOD: i64 = 1_000_000_007;

fn solve(writer: &mut io::BufWriter<io::StdoutLock>) {
    let (n, x, pos) = read!(i64, i64, i64);

    let mut ans = 1;
    let mut small = x - 1;
    let mut large = n - x;

    let mut left = 0;
    let mut right = n;
    while left < right {
        let middle = (left + right) / 2;
        if middle <= pos {
            left = middle + 1;
        } else {
            right = middle;
        }

        if middle < pos {
            ans = ans * small % MOD;
            small = small.saturating_sub(1);
        }
        if pos < middle {
            ans = ans * large % MOD;
            large = large.saturating_sub(1);
        }
    }

    let k = small + large;
    ans = ans * (1..=k).fold(1, |acc, x| acc * x % MOD) % MOD;
    writeln!(writer, "{}", ans).ok();
}

fn main() {
    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    solve(&mut writer);
}

