const MOD:u64 = 1000000007;

static INIT: Once = Once::new();
static mut FACTS:Vec<u64> = Vec::new();

fn fact(n:u64) -> u64 {
	unsafe {
		INIT.call_once(|| {
			FACTS.push(1);
			for i in 1..=1000 {
				FACTS.push((FACTS[i-1]*i as u64)%MOD);
			}
		});
		FACTS[n as usize]
	}
}



fn mod_pow(mut base: u64, mut exp: u64, modulus: u64) -> u64 {
    if modulus == 1 { return 0 }
    let mut result = 1;
    base = base % modulus;
    while exp > 0 {
        if exp % 2 == 1 {
            result = result * base % modulus;
        }
        exp = exp >> 1;
        base = base * base % modulus
    }
    result
}

fn inverse(base: u64) -> u64 {
	mod_pow(base, MOD-2, MOD)
}

fn perms(n:u64, x:u64) -> u64 {
	(fact(n) * inverse(fact(n-x)))%MOD
}

fn solve(scan:&mut Scanner) {
	let n:u64 = scan.next();
	let x:u64 = scan.next();
	let p:u64 = scan.next();
	let mut ltx = Vec::new();
	let mut gtx = Vec::new();
	let mut l = 0;
	let mut r = n;
	let mut m;
	while l < r {
		m = (l + r)/2;
		if m < p {
			ltx.push(m);
			l = m+1;
		} else if m > p {
			gtx.push(m);
			r = m
		} else {
			l = m+1;
		}
	}
	if x <= ltx.len() as u64 || n - x < gtx.len() as u64 {
		println!("0");
		return;
	}
	let free = n - ltx.len() as u64 - gtx.len() as u64 - 1;
	println!("{}",
		((perms(free, free) * 
		perms(x-1, ltx.len() as u64))%MOD * 
		perms(n-x, gtx.len() as u64))%MOD);
}

