fn md(a: i64) -> i64 {
    a % 1000000007
}

fn mul(a: i64, b: i64) -> i64 {
    md(md(a) * md(b))
}

fn solve(writer: &mut io::BufWriter<io::Stdout>) {
    let (n, x, pos) = read_multi!(i64, i64, i64);

    let checks: Vec<bool> = {
        let mut path: Vec<(i64, bool)> = vec![];
        let mut left: i64 = 0;
        let mut right: i64 = n;
        while left < right {
            let middle = (left + right) / 2;
            let check = middle <= pos;
            if middle != pos {
                path.push((middle, check));
            }
            if check {
                left = middle + 1;
            } else {
                right = middle;
            }
        }
        path.into_iter()
            .collect::<HashSet<(i64, bool)>>()
            .into_iter()
            .map(|(_, y)| y)
            .collect()
    };

    let mut n_tf: Vec<i64> = vec![0, 0];
    for &check in checks.iter() {
        n_tf[check as usize] += 1;
    }

    let h_tf = vec![n - x, x - 1];

    let mut r: i64 = 1;
    for i in 0..n_tf[1] {
        r = mul(r, h_tf[1] - i);
    }
    for i in 0..n_tf[0] {
        r = mul(r, h_tf[0] - i);
    }

    for i in 1..h_tf[1] - n_tf[1] + h_tf[0] - n_tf[0] + 1 {
        r = mul(r, i);
    }

    writeln!(writer, "{}", r).unwrap();
}

fn main() {
    let mut writer = io::BufWriter::new(io::stdout());
    solve(&mut writer);
}

use std::io;
use std::str;
use std::io::Write;

pub struct Scanner<R> {
    reader: R,
    buf_str: Vec<u8>,
    buf_iter: str::SplitAsciiWhitespace<'static>,
}

impl<R: io::BufRead> Scanner<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buf_str: vec![],
            buf_iter: "".split_ascii_whitespace(),
        }
    }

    pub fn token<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_ascii_whitespace())
            }
        }
    }
}


fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());
    let (n, x, pos) = (scan.token::<usize>(), scan.token::<usize>(), scan.token::<usize>());
    const MOD: i64 = 1e9 as i64 + 7;

    let mut permutation_ordering = vec![0; n];
    let mut factorial = vec![0i64; n + 1];
    factorial[0] = 1;
    for i in 1..=n {
        factorial[i] = (factorial[i - 1] * i as i64) % MOD;
    }
    let mut left = 0;
    let mut right = n;
    while left < right {
        let mid = (left + right) >> 1;
        // println!("{}, {}, {}", left, right, mid);
        if mid < pos {
            permutation_ordering[mid] = -1;
            left = mid + 1;
        } else if mid == pos {
            left = mid + 1;
        } else {
            permutation_ordering[mid] = 1;
            right = mid;
        }
    }
    let lesser_elements_count = permutation_ordering.iter().filter(|x| **x == -1).count();
    let greater_elements_count = permutation_ordering.iter().filter(|x| **x == 1).count();
    // println!("{:?}, {}, {}", elements, lesser_elements_count, greater_elements_count);

    let mut ans = 0i64;
    if n - x >= greater_elements_count && x - 1 >= lesser_elements_count {
        ans = 1;
        for i in 0..greater_elements_count {
            ans *= (n - x - i) as i64;
            ans %= MOD;
        }
        for i in 0..lesser_elements_count {
            ans *= (x - 1 - i) as i64;
            ans %= MOD;
        }
        ans *= factorial[n - 1 - greater_elements_count - lesser_elements_count];
        ans %= MOD;
    }
    writeln!(out, "{}", ans);
}

