fn shiftmod(i: usize, dir: i32) -> usize {
    let res = i as i32 + 2 * dir;
    (if res < 0 { 8 + res } else if res > 8 { res - 8 } else { res }) as usize
}


struct State(Vec<i32>);

impl State {
    fn shift(&mut self, perm: &[usize; 8], dir: i32) {
        for i in 0..6 {
            self.0.swap(perm[i] - 1, perm[shiftmod(i, dir)] - 1)
        }
    }

    fn is_correct(&self) -> bool {
        (0..6).all(|i|
            ((i * 4)..(i * 4 + 3))
                .all(|k| self.0[k] == self.0[k + 1]))
    }

    fn try_move(&mut self, perm: &[usize; 8], dir: i32) -> bool {
        self.shift(perm, dir);
        let res = self.is_correct();
        self.shift(perm, -dir);
        res
    }

    fn single_move(&mut self) -> bool {
        PERMS.iter().any(|perm| {
            self.try_move(perm, 1) || self.try_move(perm, -1)
        })
    }
}

fn main() {
    let mut sin = ReadIn::new();
    let mut colors = State(sin.intvec());
    println!("{}", if colors.single_move() { "YES" } else { "NO" });
}


