fn rotate(v: &mut Vec<u8>, i: usize, j: usize, k: usize, l: usize) {
    let t = v[i];
    v[i] = v[j];
    v[j] = v[k];
    v[k] = v[l];
    v[l] = t;
}

fn rotate_rev(v: &mut Vec<u8>, i: usize, j: usize, k: usize, l: usize) {
    let t = v[l];
    v[l] = v[k];
    v[k] = v[j];
    v[j] = v[i];
    v[i] = t;
}

fn check(v: &Vec<u8>) -> bool {
    for face in 0..6 {
        for sq in 1..4 {
            if v[4 * face + sq] != v[4 * face] {
                return false;
            }
        }
    }
    true
}

