fn extended_euclid(a: i32, b: i32) -> (i32, i32, i32) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (d, x, y) = extended_euclid(b, modulo(a, b));
        (d, y, x - a / b * y)
    }
}

fn modulo(a: i32, b: i32) -> i32 {
    let ret_val = a % b;
    if ret_val < 0 {
        ret_val + b
    } else {
        ret_val
    }
}

