    let ans = if e % g != 0 {
        -1
    } else {
        let x1 = x * e / g;
        let x2 = modulo(x1, c / g);

        let y1 = y * e / g;
        let y2 = modulo(-y1, a / g);

        max(b + x2 * a, d + y2 * c)
    };

    println!("{}", ans);
}

fn gcd(mut x: usize, mut y: usize) -> usize {
    while y != 0 {
        let z = x%y;
        x = y;
        y = z;
    }
    x
}

fn lcm(x: usize, y: usize) -> usize {
    x * y / gcd(x, y)
}

