fn bs<F>(f: F, mut mi: i64, mut ma: i64) -> i64
where
    F: Fn(i64) -> bool,
{
    let mut mm = 0;
    while mi < ma {
        mm = (mi + ma) / 2;
        if f(mm) {
            mi = mm + 1;
        } else {
            ma = mm;
        }
    }
    if f(mm) {
        mm + 1
    } else {
        mm
    }
}

