fn solve(x: u32) -> (u32, char) {
    fn to_category(x: u32) -> char {
        match x % 4 {
            1 => 'A',
            3 => 'B',
            2 => 'C',
            0 => 'D',
            _ => unreachable!(),
        }
    }
    [0, 1, 2]
        .iter()
        .map(|&a| (a, to_category(x + a)))
        .min_by_key(|&(_a, c)| c)
        .unwrap()
}

