    const MODULUS: u64 = 1_000_000_007;

    for _ in 0..read!() {
        let n = read!(u64);
        let k = read!(u64);

        let upper = modexp(2, n - 1, MODULUS) - 1;

        let mut result = 1;

        for bit in 0..k {
            if n % 2 == 1 {
                result *= upper + 2;
                result %= MODULUS;
            } else {
                result *= upper;
                result %= MODULUS;
                result += modexp(2, n * bit, MODULUS);
                result %= MODULUS;
            }
        }

        outln!("{}", result % MODULUS);
    }
}

fn modexp(mut base: u64, mut exp: u64, modulus: u64) -> u64 {
    let mut result = 1;

    while exp > 0 {
        if exp & 1 != 0 {
            result *= base;
            result %= modulus;
        }

        exp >>= 1;
        base *= base;
        base %= modulus;
    }

    result
}

