        let mut min = &slice[0];
        let mut max_pos: usize = 0;
        let mut min_pos: usize = 0;
        for index in 1..slice.len() {
            if slice[index] < *min {
                min = &slice[index];
                min_pos = index;
            }
            if slice[index] > *max {
                max = &slice[index];
                max_pos = index;
            }
        }
        (*max, *min, max_pos, min_pos)
    }
