pub struct Scanner<B> {
    reader: B,
    buf_str: Vec<u8>,
    buf_iter: std::str::SplitWhitespace<'static>,
}

impl<B: BufRead> Scanner<B> {
    pub fn new(reader: B) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_whitespace(),
        }
    }
    pub fn token<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = std::str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_whitespace())
            }
        }
    }
}

use std::{io, io::prelude::*, str};

struct Scanner<R> {
    reader: R,
    buffer: Vec<String>,
}
impl<R: io::BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![],
        }
    }

    fn t<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}

use std::ops;

#[derive(Copy, Clone)]
struct ModGroup {
    val: usize,
}
impl ModGroup {
    const MOD: usize = 1000000007;
    const MOD64: i64 = Self::MOD as i64;

    fn new(v: usize) -> Self {
        Self { val: v }
    }

    fn from_usize(v: usize) -> Self {
        Self { val: v % Self::MOD }
    }

    fn from_i64(v: i64) -> Self {
        Self {
            val: (v % Self::MOD64) as usize,
        }
    }

    fn pow(self, mut p: usize) -> Self {
        let mut base = self;
        let mut res = Self::new(1);
        while p > 0 {
            if p % 2 > 0 {
                res = res * base;
            }
            base = base * base;
            p /= 2;
        }

        res
    }

    fn inv(self) -> Self {
        self.pow(Self::MOD - 2)
    }
}

impl ops::Add<usize> for ModGroup {
    type Output = Self;

    fn add(self, other: usize) -> Self {
        Self::from_usize(self.val + other)
    }
}
impl ops::Add<ModGroup> for ModGroup {
    type Output = Self;

    fn add(self, other: Self) -> Self {
        self + other.val
    }
}
impl ops::Sub<usize> for ModGroup {
    type Output = Self;

    fn sub(self, other: usize) -> Self {
        Self::new(if self.val > other {
            self.val - other
        } else {
            self.val + Self::MOD - other
        })
    }
}
impl ops::Sub<ModGroup> for ModGroup {
    type Output = Self;

    fn sub(self, other: Self) -> Self {
        self - other.val
    }
}
impl ops::Mul<usize> for ModGroup {
    type Output = Self;

    fn mul(self, other: usize) -> Self {
        Self::from_i64(self.val as i64 * other as i64)
    }
}
impl ops::Mul<ModGroup> for ModGroup {
    type Output = Self;

    fn mul(self, other: Self) -> Self {
        self * other.val
    }
}
impl ops::Div<usize> for ModGroup {
    type Output = Self;

    fn div(self, other: usize) -> Self {
        self * Self::new(other).inv()
    }
}
impl ops::Div<ModGroup> for ModGroup {
    type Output = Self;

    fn div(self, other: Self) -> Self {
        self * other.inv()
    }
}

fn main() -> io::Result<()> {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout);

    const N: usize = 200002;

    let pow2_mod = {
        let mut p = vec![ModGroup::new(1); N];
        for i in 1..N {
            p[i] = p[i - 1] * 2;
        }
        p
    };
    let fact_mod = {
        let mut f = vec![ModGroup::new(1); N];
        for i in 1..N {
            f[i] = f[i - 1] * i;
        }
        f
    };

    let bin_coef = |n: usize, k: usize| fact_mod[n] / (fact_mod[k] * fact_mod[n - k]);

    let tn: usize = scan.t();
    for _ in 0..tn {
        let (n, k): (usize, usize) = (scan.t(), scan.t());

        let pow2n_mod = {
            let mut p = vec![ModGroup::new(1); k];
            for i in 1..k {
                p[i] = pow2_mod[i].pow(n);
            }
            p
        };

        let gt_cnt = if n % 2 > 0 {
            ModGroup::new(0)
        } else {
            ModGroup::new(1)
        };
        let eq_cnt = {
            let mut res = ModGroup::new(1);
            if n % 2 > 0 {
                res = res + 1;
            }

            let mut m = 2;
            while m < n {
                res = res + bin_coef(n, m);
                m += 2;
            }

            res
        };
        let mut sum_eq_cnt = ModGroup::new(1);
        let mut res = ModGroup::new(0);
        for i in 0..k {
            res = res + gt_cnt * sum_eq_cnt * pow2n_mod[k - i - 1];
            sum_eq_cnt = sum_eq_cnt * eq_cnt;
        }

        res = res + sum_eq_cnt;
        writeln!(out, "{}", res.val)?;
    }

    io::Result::Ok(())
}

