use modint::ModInt1000000007 as mint;
use modint::*;

pub struct Combination {
    fact: Vec<mint>,
    ifact: Vec<mint>,
}
impl Combination {
    pub fn new(n: i32) -> Self {
        let mut fact = vec![mint::new(0); (n + 1) as usize];
        let mut ifact = vec![mint::new(0); (n + 1) as usize];
        fact[0] = mint::new(1);
        for i in 1..n + 1 {
            fact[i as usize] = fact[(i - 1) as usize] * mint::new(i as i64)
        }
        ifact[n as usize] = fact[n as usize].inv();
        for i in (1..n + 1).rev() {
            ifact[(i - 1) as usize] = ifact[i as usize] * mint::new(i as i64)
        }
        let a = Combination {
            fact: fact,
            ifact: ifact,
        };
        return a;
    }
    #[macro_use]
    pub fn gen(&mut self, n: i32, k: i32) -> mint {
        if (k < 0 || k > n) {
            return mint::new(0 as i64);
        };
        return self.fact[n as usize] * self.ifact[k as usize] * self.ifact[(n - k) as usize];
    }
    pub fn P(&mut self, n: i32, k: i32) -> mint {
        self.fact[n as usize] * self.ifact[(n - k) as usize]
    }
}

fn main() {
    let T = get!(usize);
    let mut cmb = Combination::new(2 * 100000 + 10);

    for testcase in 0..T {
        mydbg!(testcase);
        let mut ans: mint = mint::new(0);
        let (N, K) = get!(usize, usize);

        let mut E = mint::new(1);
        for i in 1.. {
            let k = i * 2;
            if k >= N {
                break;
            }
            E += cmb.gen(N as i32, k as i32);
        }

        mydbg!(E);

        let mut dp = vec![vec![mint::new(0); 3]; K + 1];
        dp[0][0] = mint::new(1);
        for i in 0..K {
            for j in 0..2 {
                if dp[i][j] == mint::new(0) {
                    continue;
                }
                if j == 0 {
                    //1
                    if N % 2 == 0 {
                        dp[i + 1][j + 1] = dp[i + 1][j + 1] + dp[i][j];
                    } else {
                        dp[i + 1][j] = dp[i + 1][j] + dp[i][j];
                    }
                    //0
                    dp[i + 1][j] = dp[i + 1][j] + dp[i][j] * E;
                } else {
                    dp[i + 1][j] = dp[i + 1][j] + dp[i][j] * mint::new(2).pow(N as u64);
                }
            }
        }

        echo!(dp[K][0] + dp[K][1]);
    }
}

// ---------- begin input macro ----------
// reference: https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};
    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };
    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
