    line: Vec<u8>,
    ptr: usize

}

impl<R: std::io::BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        return Self {reader, line: vec![], ptr: 0};
    }

    fn scan<T: std::str::FromStr>(&mut self) -> T {
        loop {
            while self.ptr < self.line.len() && self.line[self.ptr].is_ascii_whitespace() {
                self.ptr += 1;
            }
            if self.ptr != self.line.len() {
                let start = self.ptr;
                while self.ptr < self.line.len() && !self.line[self.ptr].is_ascii_whitespace() {
                    self.ptr += 1;
                }
                return std::str::from_utf8(&self.line[start..self.ptr]).unwrap().parse().ok().
                    expect("parse error");
            }
            self.line.clear();
            self.reader.read_until(b'\n', &mut self.line).expect("read error");
            self.ptr = 0;
        }
    }

}

fn solve_even(n: usize, m: usize, mut k: usize) -> Option<Vec<Vec<u8>>> {
    if k % 2 == 1 {
        return None;
    }
    let mut field = vec![vec![0u8; m]; n];
    for i in (0..n).step_by(2) {
        for j in (0..m).step_by(2) {
            if k != 0 {
                field[i][j] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i][j + 1] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i + 1][j] = ((i + 1) % 3 * 3 + j % 3) as u8 + b'a';
                field[i + 1][j + 1] = ((i + 1) % 3 * 3 + j % 3) as u8 + b'a';
                k -= 2;
            } else {
                field[i][j] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i + 1][j] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i][j + 1] = (i % 3 * 3 + (j + 1) % 3) as u8 + b'a';
                field[i + 1][j + 1] = (i % 3 * 3 + (j + 1) % 3) as u8 + b'a';
            }
        }
    }
    return Some(field);
}

fn solve_odd(n: usize, m: usize, mut k: usize) -> Option<Vec<Vec<u8>>> {
    if k < m / 2 || (k - m / 2) % 2 == 1 {
        return None;
    }
    let mut field = vec![vec![0u8; m]; n];
    for i in (0..m).step_by(2) {
        field[0][i] = (i % 3) as u8 + b'a';
        field[0][i + 1] = (i % 3) as u8 + b'a';
        k -= 1;
    }
    for i in (1..n).step_by(2) {
        for j in (0..m).step_by(2) {
            if k != 0 {
                field[i][j] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i][j + 1] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i + 1][j] = ((i + 1) % 3 * 3 + j % 3) as u8 + b'a';
                field[i + 1][j + 1] = ((i + 1) % 3 * 3 + j % 3) as u8 + b'a';
                k -= 2;
            } else {
                field[i][j] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i + 1][j] = (i % 3 * 3 + j % 3) as u8 + b'a';
                field[i][j + 1] = (i % 3 * 3 + (j + 1) % 3) as u8 + b'a';
                field[i + 1][j + 1] = (i % 3 * 3 + (j + 1) % 3) as u8 + b'a';
            }
        }
    }
    return Some(field);
}

fn transpose(old: Vec<Vec<u8>>) -> Vec<Vec<u8>> {
    let mut field = vec![vec![0u8; old.len()]; old[0].len()];
    for i in 0..old.len() {
        for j in 0..old[i].len() {
            field[j][i] = old[i][j];
        }
    }
    return field;
}

fn solve<R: std::io::BufRead, W: std::io::Write>(scanner: &mut Scanner<R>, writer: &mut W) {
    let n: usize = scanner.scan();
    let m: usize = scanner.scan();
    let k: usize = scanner.scan();
    if n % 2 == 0 && m % 2 == 0 {
        if let Some(field) = solve_even(n, m, k) {
            writeln!(writer, "YES").unwrap();
        } else {
            writeln!(writer, "NO").unwrap();
        }
        return;
    }
    let field = if n % 2 == 1 {
        solve_odd(n, m, k)
    } else {
        let cur = solve_odd(m, n, n * m / 2 - k);
        if let Some(cur) = cur {
            Some(transpose(cur))
        } else {
            None
        }
    };
    if let Some(field) = field {
        writeln!(writer, "YES").unwrap();
    } else {
        writeln!(writer, "NO").unwrap();
    }
}

fn main() {
    let (stdin, stdout) = (std::io::stdin(), std::io::stdout());
    let mut writer = std::io::BufWriter::new(stdout.lock());
    let mut scanner = Scanner::new(stdin.lock());
    let tests: usize = scanner.scan();
    for _ in 0..tests {
        solve(&mut scanner, &mut writer);
    }
}

