fn main() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let n: i32 = input.trim().parse().unwrap();
    let mut segs: Vec<(i32, i32, i32)> = vec![];

    for i in 0..(n+1) {
        for j in (i+1)..(n+1) {
            segs.push((j-i,i,j));
        }
    }
    segs.sort();
    let mut result: i32 = 0;
    let mut flags: Vec<bool> = vec![false; segs.len()];
    for i in (0..segs.len()).rev() {
        if flags[i] { continue; }
        let (size, mut a, mut b) = segs[i];
        flags[i] = true;
        let mut cur: i32 = size;
        while cur < n {
            let mut did_something = false;
            for j in (0..segs.len()).rev() {
                if flags[j] { continue; }
                let (s, c, d) = segs[j];
                if a == d || b == c {
                    if cur + s <= n {
                        a = cmp::min(a, c);
                        b = cmp::max(b, d);
                        cur += s;
                        flags[j] = true;
                        did_something = true;
                    }
                }
            }
            if !did_something { break; }
        }
        result += 1;
    }
    println!("{}", result);
}

