                    next[1][j] += dp[1][j] * ModInt((cnt[1][j] - i) as u32);
                    next[1][j] += dp[1][j + 1] * ModInt((cnt[1][j] - cnt[1][j + 1]) as u32);
                }
            }
            dp = next;
        }
        ans += dp[0][0];
    }
    println!("{}", ans.0);
}

