macro_rules! read_line {
    ([$t: ty]) => {{
        read_line().split_whitespace().map(|token| {
            <$t as std::str::FromStr>::from_str(token).expect(
                &format!(concat!("Could not parse {} into ", stringify!($t)), token))
        })
    }};
    ($($t: ty),*) => {{
        let line = read_line();
        let mut iter = line.split_whitespace();
        ($({
            let token = iter.next().expect("Not enough tokens");
            <$t as std::str::FromStr>::from_str(token).expect(
                &format!(concat!("Could not parse {} into ", stringify!($t)), token))
        }),*)
    }};
}

fn main() {
    read_line!(usize);
    enum State {
        Up,
        Hold,
        Down,
    }
    let mut state = State::Up;
    let mut prev = 0;
    let mut ans = true;
    for x in read_line!([u16]) {
        match state {
            State::Hold => {
                if x > prev {
                    ans = false;
                    break;
                }
            }
            State::Down => {
                if x >= prev {
                    ans = false;
                    break;
                }
            }
            State::Up => {}
        }
        state = if x < prev {
            State::Down
        } else if x > prev {
            State::Up
        } else {
            State::Hold
        };
        prev = x;
    }
    println!("{}", if ans { "YES" } else { "NO" });
}

