use std::collections::VecDeque;

fn main() {
    let m: i32 = get_input().split_ascii_whitespace().last().unwrap().parse().unwrap();
    let children: Vec<i32> = get_input().split_ascii_whitespace().map(|v| v.parse().unwrap()).collect();

    let candies: Vec<Candy> = children.iter().enumerate().map(|(index, value)| {
        let candy = Candy::new(*value, index + 1);
        candy
    }).collect();

    let mut stack = VecDeque::new();

    for candy in candies {
        stack.push_back(candy);
    };

    while stack.len() > 1 {
        let next = stack.pop_front().unwrap();
        let temp = next.value - m;

        if temp > 0 {
            stack.push_back(Candy::new(temp, next.index));
        }
    }


    println!("{}", stack.pop_front().unwrap().index);
}


