    let mut scan = Scan::new();
    // e.g: 3 -> 3 + (2*(2-1)+1) + 1
    // e.g: 4 -> 4 + 3 + 2 + 1 =
    let n: isize = scan.next();
    if n == 1 {
        println!("1");
        return;
    }
    let mut result: isize = n + 1; 
    let mut i = n-1;
    while i >= 2 {
        result += i*(n-i) + 1;
        i -= 1;
    }
    println!("{}", result);
}

