          if a == b || a == c || a == d || b == c || b == d || c == d { continue; }
          let cond =
            a + b == r1 &&
            c + d == r2 &&
            a + c == c1 &&
            b + d == c2 &&
            a + d == d1 &&
            b + c == d2;
          if cond {
            println!("{} {}", a, b);
            println!("{} {}", c, d);
            return;
          }
        }
      }
    }
  }
  println!("-1");
}

fn solution(r1:u32, r2:u32, c1:u32, c2:u32, d1:u32, d2: u32) -> [u32;4] {
  let mut r = [0,0,0,0];

  'outer: 
  for a in 1..=9 {
    for b in 1..=9 {
      if b==a {continue}; 
      for c in 1..=9 {
        if c==b || c==a {continue};
        for d in 1..=9 {
          if d==a || d==b || d==c {continue}; 
          if a+b==r1 && c+d==r2 && a+c==c1 && b+d==c2 && a+d==d1 && b+c==d2 {
            r = [a,b,c,d];
            break 'outer;
          }
        } 
      }
    }
  }
  r
}

