fn dfs<'a>(g: &'a Vec<Vec<usize>>, u: &'a mut Vec<bool>, v: usize) {
	if u[v] {
		return;
	}
	u[v] = true;
	for &x in &g[v] {
		dfs(g, u, x);
	}
}

