fn solve<Inner: BufRead, Output: Write>(inf: &mut Input<Inner>, ouf: &mut Output) {
	let s = inf.read_word().as_bytes().to_vec();
	let mut pos = 0;
	while pos < s.len() && s[pos] == b'0' {
		pos += 1;
	}
	let mut ans = 0;
	for i in pos + 1..s.len() {
		if s[i] == b'0' {
			ans += 1;
		}
	}
	if ans >= 6 {
		writeln!(ouf, "yes");
	} else {
		writeln!(ouf, "no");
	}
}

