fn solve(input: &mut std::str::SplitWhitespace) {
    macro_rules! read {
        () => ();
        ([$tt:tt]) => (read!([$tt; read!(usize)]));
        ([$tt:tt; $n:expr]) => ((0..$n).map(|_| read!($tt)).collect::<Vec<_>>());
        (($($tt:tt),+)) => (($(read!($tt)),*));
        (Usize1) => (read!(usize) - 1);
        (Chars) => (read!(String).chars().collect::<Vec<char>>());
        (Byte) => (read!(char) as u8);
        (Bytes) => (read!(String).into_bytes());
        ($ty:ty) => (input.next().unwrap().trim().parse::<$ty>().unwrap());
    }
    macro_rules! input {
        ($($id:ident : $ty:tt),*) => {
            $(
                let $id = read!($ty);
            )*
        }
    }

    input! {
        n: usize,
        a_r: usize, a_s: usize, a_p: usize,
        b_r: usize, b_s: usize, b_p: usize
    }

    let mi = a_r.saturating_sub(b_r + b_p)
        + a_s.saturating_sub(b_s + b_r)
        + a_p.saturating_sub(b_p + b_s);
    let ma = min(a_r, b_s) + min(a_s, b_p) + min(a_p, b_r);

    vis!(mi, ma);
}

