pub struct Perm {
    used: Vec<bool>,
    perm: Vec<usize>,
    ret: Vec<Vec<usize>>,
}
impl Perm {
    pub fn new(len: usize) -> Self {
        let mut f = Perm {
            used: vec![false; len],
            perm: vec![0; len],
            ret: vec![],
        };
        f.calc(0, len);
        return f;
    }
    pub fn calc(&mut self, pos: usize, n: usize) {
        if pos == n {
            self.ret.push(self.perm.clone());
            return;
        }
        for i in 0..n {
            if self.used[i] == false {
                self.perm[pos] = i;
                self.used[i] = true;
                self.calc(pos + 1, n);
                self.used[i] = false;
            }
        }
    }
}

