use std::cmp;
use std::collections::VecDeque;

fn rec(
    deq: &mut VecDeque<(usize, usize)>,
    a: &mut Vec<i32>, b: &mut Vec<i32>,
) -> i32 {
    if deq.is_empty() { return a.iter().sum(); }
    let mut res = std::i32::MAX;
    let n = deq.len();
    for _ in 0..n {
        let (i, j) = deq.pop_front().unwrap();
        let tmp = cmp::min(a[i], b[j]);
        a[i] -= tmp;
        b[j] -= tmp;
        res = cmp::min(res, rec(deq, a, b));
        deq.push_back((i, j));
        a[i] += tmp;
        b[j] += tmp;
    }
    res
}

fn solve() -> String {
    let _n = read_line_to_tuple!(i32);
    let mut a = read_line_to_collection!(Vec<i32>);
    let mut b = read_line_to_collection!(Vec<i32>);

    let mut deq = VecDeque::new();
    deq.push_back((0, 0));
    deq.push_back((1, 1));
    deq.push_back((2, 2));
    deq.push_back((0, 2));
    deq.push_back((1, 0));
    deq.push_back((2, 1));
    let min = rec(&mut deq, &mut a, &mut b);

    let mut max = 0;
    for i in 0..3 {
        let tmp = cmp::min(a[i], b[(i + 1) % 3]);
        max += tmp;
    }

    format!("{} {}", min, max)
}

