#[doc = " [l, r)"]
pub fn binary_search_by<F>(mut l: i64, mut r: i64, f: &F) -> i64
where
    F: Fn(i64) -> bool,
{
    assert!(l <= r);
    while r != l {
        let m = l + (r - l) / 2;
        if f(m) {
            r = m;
        } else {
            l = m + 1;
        }
    }
    r
}

