fn scan_helper(lock : &mut StdinLock) -> String {
    let mut buffer = String::new();
    lock.read_line(&mut buffer).ok();
    buffer
}

macro_rules! scan {
    ($lock:ident, $t:ty) => ({
        scan_helper(&mut $lock).split_whitespace()
            .next().unwrap()
            .parse::<$t>().unwrap()
    });
    ($lock:ident, $($t:ty),+) => ({
        let buffer = scan_helper(&mut $lock);
        let mut iter = buffer.split_whitespace();
        ($(
            {
                iter.next().unwrap()
                    .parse::<$t>().unwrap()
            },
        )+)
    })
}

macro_rules! scan_iter {
    ($lock:ident, $t:ty) => ({
        scan_helper(&mut $lock).split_whitespace()
            .map(|x| x.parse::<$t>().unwrap())
            .collect()
    })
}

trait Ext {
    fn idx(&self) -> usize;
    fn num(&self) -> i64;
}

macro_rules! ext {
    ($t:ty) => (
        impl Ext for $t {
            #[inline]
            fn idx(&self) -> usize {
                *self as usize
            }

            #[inline]
            fn num(&self) -> i64 {
                *self as i64
            }
        }
    )
}
ext!(i64);
ext!(usize);

macro_rules! derive_regular {
    ($t:ty) => (
        impl Ord for $t {
            fn cmp(&self, other : &$t) -> Ordering {
                self.partial_cmp(other).unwrap()
            }
        }
        impl PartialEq for $t {
            fn eq(&self, other : &$t) -> bool {
                self.cmp(other) == Ordering::Equal
            }
        }
        impl Eq for $t {}
    )
}

fn solve(v : &Vec<i64>, n : i64, d : bool, memo : &mut HashMap<(i64, bool), (i64, i64)>) -> (i64, i64) {
    if n == v.len().num() {
        if d {
            return (0, 0);
        } else {
            return (0, 0);
        }
    }
    if let Some(&x) = memo.get(&(n, d)) {
        return x;
    }

    let mut take = solve(v, n+1, !d, memo);
    if d {
        take.1 += v[n.idx()];
    } else {
        take.0 += v[n.idx()];
    }
    let mut defer = solve(v, n+1, d, memo);
    if d {
        defer.0 += v[n.idx()];
    } else {
        defer.1 += v[n.idx()];
    }

    let result = if d {
        if take.1 >= defer.1 {
            take
        } else {
            defer
        }
    } else {
        if take.0 >= defer.0 {
            take
        } else {
            defer
        }
    };
    memo.insert((n, d), result);

    result
}

fn main() {
    let stdin = stdin();
    let mut s = stdin.lock();
    let n = scan!(s, i64);
    let data : Vec<_> = scan_iter!(s, i64);

    let mut memo = HashMap::new();

    let result = solve(&data, 0, true, &mut memo);
    println!("{} {}", result.0, result.1);
}

