use std::io;

fn main() {
    let (mut x, k) = read_2::<u64>(&io::stdin());
    let modulo = 1000000007;
    if x == 0 {
        println!("{}", x);
        return;
    }
    x = x % modulo;
    let a = (mod_exp(2, k + 1, modulo) * x) % modulo;
    let b = mod_exp(2, k, modulo);
    if a >= b {
        println!("{}", (a - b + 1) % modulo);
    } else {
        println!("{}", ((modulo + a) - b + 1) % modulo);
    }
}

fn mod_exp(mut a: u64, mut k: u64, n: u64) -> u64 {
    let mut multiplier = 1;
    a = a % n;
    while k != 0 {
        if k % 2 == 1 {
            multiplier = (multiplier * a) % n;
        }
        a = (a * a) % n;
        k = k / 2;
    }
    multiplier
}

fn read_2<T>(stdin: &io::Stdin) -> (T, T)
where
    T: std::str::FromStr,
    <T as std::str::FromStr>::Err: std::fmt::Debug,
{
    let mut s = String::new();
    stdin.read_line(&mut s).unwrap();
    let mut iter = s.trim().split_whitespace().map(|x| x.parse().unwrap());
    (iter.next().unwrap(), iter.next().unwrap())
}

