//generate factorial modulo m
fn fac_gen(n: i64, m: i64) -> Vec<i64> {
    let it = (1..=n).scan(1, |s, x: i64| {*s = *s * x % m; Some(*s)} );
    (1..=1).chain(it).collect()
}

