    let factorials = fac_gen(n, m);

    // dbg!(&factorials);

    let ans = (1..=n)
        .map(|length| (n-length+1) * factorials[length as usize] % m * factorials[(n-length + 1) as usize] % m )
        // .inspect(|x| {dbg!(x);} )
        .fold(0i64, |acc, x| (x + acc) % m);

    println!("{}",ans);
}

