use input::*;
use std::cmp;
use std::collections::HashMap;

fn main() {
    let t: usize;
    input!(t);
    for _ in 0..t {
        let (n, k, d): (usize, usize, usize);
        input!(n, k, d);
        let v = input_vector::<usize>();
        let mut map = HashMap::new();
        let mut ans;
        for i in 0..d {
            *map.entry(v[i]).or_insert(0) += 1;
        }
        ans = map.len();
        for i in 0..n - d {
            *map.entry(v[i + d]).or_insert(0) += 1;
            let buf = map[&v[i]] - 1;
            map.insert(v[i], buf);
            if map[&v[i]] == 0 {
                map.remove(&v[i]);
            }
            //println!("{:?}->{}",&map,map.len());
            ans = cmp::min(ans, map.len());
        }
        p(ans);
    }
}

