use std::str::FromStr;
use std::io;
use std::fs::File;
use std::io::BufReader;
use std::io::BufRead;
use std::collections::HashMap;
use std::cmp;

struct Reader {
    index: usize,
    items: Vec::<String>,
    reader: Box<io::BufRead>
}

impl Reader {
    fn read<T: FromStr>(&mut self) -> T {
        if self.index >= self.items.len() {
            let mut buffer = String::new();
            self.reader.read_line(&mut buffer).expect("Error reading new line");
            self.items = buffer.split_ascii_whitespace().map(|x| x.to_string()).collect();
            self.index = 0;
        }

        let result = self.items[self.index].parse::<T>();
        self.index += 1;
        return match result {
            Ok(value) => value,
            Err(_) => {
                panic!("Error reading next value");
            }
        }
    }

    fn read_vec<T: FromStr>(&mut self) -> Vec::<T> {
        let mut buffer = String::new();
        self.reader.read_line(&mut buffer).expect("Error reading new line");
        buffer.split_ascii_whitespace().map(|x| match x.parse::<T>() {
            Ok(v) => v,
            Err(_) => {
                panic!("Error reading next value")
            }
        }).collect()
    }

    fn new(from_file: bool) -> Reader {
