fn enumerate(a: &[u32], m: u32) -> Vec<u32> {
    let mut ans = vec![0];
    for &a in a.iter() {
        let mut next = ans.clone();
        for v in ans {
            next.push((v + a) % m);
        }
        ans = next;
    }
    ans.sort();
    ans.dedup();
    ans
}

fn run() {
    input! {
        n: usize,
        m: u32,
        a: [u32; n],
    }
    let mid = n / 2;
    let (l, r) = a.split_at(mid);
    let l = enumerate(l, m);
    let r = enumerate(r, m);
    let mut ans = (*l.last().unwrap() + *r.last().unwrap()) % m;
    let mut j = 0;
    for l in l.iter().rev() {
        while j + 1 < r.len() && *l + r[j + 1] < m {
            j += 1;
        }
        ans = std::cmp::max(ans, (*l + r[j]) % m);
    }
    println!("{}", ans);
}

