fn combs(s: &[u64]) -> Vec<u64> {
    let mut res = HashSet::new();
    res.insert(0);

    for &x in s {
        let copy = res.clone();
        for &y in &copy {
            res.insert(x + y);
        }
    }

    let mut v = res.iter().cloned().collect::<Vec<_>>();
    v.sort();
    v
}

fn bsearch(t: u64, s: &[u64]) -> u64 {
    match s.binary_search(&t) {
        Ok(i) => s[i],
        Err(i) => {
            let mut i = i;
            if i >= s.len() {
                return s.last().cloned().unwrap();
            }
            while i > 0 && s[i] > t {
                i -= 1;
            }
            s[i]
        }
    }
}

