use std::slice::Iter;
use std::iter::Peekable;

fn check_step(iter : &mut Peekable<Iter<u64>>, check_sum : u64) -> Option<bool> {
    if iter.len() == 0 { return None }
    let mut sum = 0;
    while let Some(x) = iter.next() {
        sum += x;
        if sum == check_sum {
            while iter.peek().map(|x| **x == 0).unwrap_or(false) {
                iter.next();
            }
            return Some(true)
        }
    }
    Some(false)
}

fn check(iter : Iter<u64>, check_sum : u64) -> bool {
    if iter.len() == 0 { return false }
    let mut iter = iter.peekable();
    while let Some(flag) = check_step(&mut iter, check_sum) {
        if !flag { 
            return false 
        }
    }
    true
}

