/*
«Игра 23» — вот во что сейчас играет Поликарп. ;
Изначально у него есть целое число n и его цель преобразовать его в целое число m. 
За один ход он может умножить n на 2 или умножить n на 3. Он может совершать любое количество ходов.

Выведите количество ходов, сколько необходимо Поликарпу, чтобы получить из числа n число m. 
Выведите -1, если это невозможно сделать.
*/

use std::io::{BufRead, Write, BufReader, BufWriter};
const MULTIPLE_TESTS: bool = false;

fn task(n: u32, m: u32) -> i32 {
    let mut mult: u32 = m / n;
    if mult * n != m { return -1; }

    let mut steps = 0;
    while mult % 2 == 0 {
        steps += 1;
        mult /= 2;
    }
    while mult % 3 == 0 {
        steps += 1;
        mult /= 3;
    }
    if mult == 1 { steps } else { -1 }
}

fn main() -> std::io::Result<()> {
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    let reader = BufReader::new(stdin.lock());
    let mut writer = BufWriter::new(stdout.lock());

    let mut lines = reader.lines();
    let n_tests: i32 = if MULTIPLE_TESTS {
        lines.next().unwrap().map(|s| s.parse::<i32>())?.unwrap()
    } else { 1 };

    for i in 0..n_tests {
        // read arguments
        let line = lines.next().unwrap()?;
        let args = line.split_whitespace().map(|s| s.parse::<u32>().unwrap()).collect::<Vec<_>>();
        // run test
        let result = task(args[0], args[1]);
        writeln!(writer, "{}", result)?;
    }

    Ok(())
}

