fn get_min_transform_move_num(n: usize, m: usize) -> Option<usize> {
    if (m % n) != 0 {
        return None;
    }
    let mut value: usize = m / n;
    let mut step_num: usize = 0;
    while value > 1 {
        if (value % 3) == 0 {
            value /= 3;
            step_num += 1;
        } else if (value % 2) == 0 {
            value /= 2;
            step_num += 1;
        } else {
            return None;
        }
    }
    return Some(step_num);
}

