fn solve(a: String, b: String) {
    let mut counters = vec![Vec::<i64>::new(); b.len() + 2];
    let mut start = 1;
    for i in 0..a.len() {
        for j in 0..start {
            if a.as_bytes()[i] == b.as_bytes()[j] {
                counters[j + 1].push(i as i64);
                if j == start - 1 && start < b.len() {
                    start += 1;
                }
            }
        }
    }
    let mut end = a.len() as i64;
    for i in (0..b.len()).rev() {
        counters[i + 1].retain(|&x| x < end);
        end = *counters[i + 1].iter().max().unwrap();
    }
    counters[0].push(-1);
    counters[b.len() + 1].push(a.len() as i64);
    let mut best = 0;
    for i in 0..counters.len() - 1 {
        best = std::cmp::max(
            best,
            counters[i + 1].iter().max().unwrap() - counters[i].iter().min().unwrap() - 1,
        );
    }
    println!("{}", best);
}

