fn judge(s: &[char], t: &[char], start: usize, end: usize) -> bool {
    let mut index = 0;
    for i in 0..s.len() {
        if i >= start && i <= end {
            continue;
        }
        if s[i] == t[index] {
            index += 1;
        }
        if index == t.len() {
            break;
        }
    }
    index == t.len()
}

