fn run() {
    input! {
        s: chars,
        t: chars,
    }
    let mut dp = vec![0; t.len() + 1];
    dp[t.len()] = s.len();
    let mut j = t.len() - 1;
    for i in (0..s.len()).rev() {
        if s[i] == t[j] {
            dp[j] = i;
            j -= 1;
        }
        if j >= t.len() {
            break;
        }
    }
    let mut ans = dp[0];
    let mut j = 0;
    for i in 0..s.len() {
        if s[i] == t[j] {
            j += 1;
            ans = std::cmp::max(ans, dp[j] - i - 1);
        }
        if j >= t.len() {
            break;
        }
    }
    println!("{}", ans);
}

