fn main() {
    let s = read::<String>().chars().collect::<Vec<_>>();
    let mut t = read::<String>().chars().collect::<Vec<_>>();

    let mut fastest_poses = vec![];
    let mut slowest_poses = vec![];
    for i in 0..2 {
        let mut poses;
        if i == 0 {
            poses = &mut fastest_poses;
        } else {
            poses = &mut slowest_poses;
        }
        let mut alpha_poses = vec![vec![]; 26];
        if i == 0 {
            for j in 0..s.len() {
                let ch_idx = s[j].to_digit(36).unwrap() as usize - 10;
                alpha_poses[ch_idx].push(j);
            }
        } else {
            for j in (0..s.len()).rev() {
                let ch_idx = s[j].to_digit(36).unwrap() as usize - 10;
                alpha_poses[ch_idx].push(s.len() - 1 - j);
            }
        }

        if i == 1 {
            t.reverse();
        }

        let mut prev = 0;
        for (j, &tch) in t.iter().enumerate() {
            let tch_idx = tch.to_digit(36).unwrap() as usize - 10;
            let mut next;
            if j == 0 {
                next = alpha_poses[tch_idx][alpha_poses[tch_idx].lower_bound(&prev)];
            } else {
                next = alpha_poses[tch_idx][alpha_poses[tch_idx].upper_bound(&prev)];
            }
            poses.push(next);
            prev = next;
        }
    }
    let mut slowest_poses = slowest_poses
        .iter()
        .map(|x| s.len() - 1 - x)
        .collect::<Vec<_>>();
    slowest_poses.reverse();

    debug!(fastest_poses);
    debug!(slowest_poses);

    let mut ans = 0;
    for l in 0..s.len() {
        let found = fastest_poses.lower_bound(&l);
        if found == slowest_poses.len() {
            ans = max(ans, s.len() - l);
            continue;
        }
        ans = max(ans, slowest_poses[found] - l);
    }
    println!("{}", ans);
}

