fn main() {
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut scan = Scanner::default();

    // Read input
    let s: Vec<u8> = scan.next::<String>().bytes().collect();
    let t: Vec<u8> = scan.next::<String>().bytes().collect();

    let mut max_prefix: Vec<usize> = vec![0; s.len() + 1];
    max_prefix[0] = 0;
    for i in 1..(s.len()+1) {
        max_prefix[i] = max_prefix[i-1];
        if max_prefix[i] < t.len() && t[max_prefix[i]] == s[i-1] {
            max_prefix[i] += 1;
        }
    }

    let mut max_suffix: Vec<usize> = vec![0; s.len() + 1];
    max_suffix[0] = 0;
    for i in 1..(s.len()+1) {
        max_suffix[i] = max_suffix[i-1];
        if max_suffix[i] < t.len() && t[t.len()-1-max_suffix[i]] == s[s.len()-i] {
            max_suffix[i] += 1;
        }
    }

    let can_substr = |len| {
        for prefix in 0..(s.len()+1-len) {
            let suffix = s.len() - prefix - len;
            if max_prefix[prefix] + max_suffix[suffix] >= t.len() {
                return true;
            }
        }
        return false;
    };

    let mut l: usize = 0;
    let mut r: usize = s.len() - t.len() + 1;
    while r - l > 1 {
        let m = (l + r) / 2;
        if can_substr(m) {
            l = m;
        } else {
            r = m;
        }
    }
    writeln!(out, "{}", l).unwrap();
}

