fn solve(input: &mut BufRead, output: &mut Write) {
    let mut input = BufReader::new(input);

    let mut first = String::with_capacity(201);
    let mut second = String::with_capacity(201);

    input.read_line(&mut first).unwrap();
    input.read_line(&mut second).unwrap();

    let s = first.trim().as_bytes();
    let t = second.trim().as_bytes();

    let first = s.iter().position(|&it| it == t[0]).unwrap();
    let second = s.iter().rev().position(|&it| it == t[t.len() - 1]).unwrap();

    let mut answ = first.max(second);

    let mut pos = vec![first; t.len()];
    let mut pos_rev = vec![second; t.len()];


    let mut prev = first;
    for i in 0..t.len() {
        let pos1 = s.iter().skip(prev).position(|&it| it == t[i]).unwrap();
        prev += pos1;
        pos[i] = prev;
        prev += 1;
    }

    let mut rev = second;
    for i in (0..t.len()).rev() {
        let pos1 = s.iter().rev().skip(rev).position(|&it| it == t[i]).unwrap();
        rev += pos1;
        pos_rev[i] = rev;
        rev += 1;
    }

    for i in 0..t.len() - 1 {
        answ = answ.max((s.len() - pos_rev[i + 1] - 2) - pos[i])
    }

    answ = answ.max(s.len() - pos[pos.len() - 1] - 1);
    answ = answ.max(s.len() - pos_rev[0] - 1);

    writeln!(output, "{}", answ).unwrap();
}

