fn gcd(a : u64, b : u64) -> u64 {
    let mut t_a = if a > b { a } else { b };
    let mut t_b = if t_a == a { b } else { a };
    loop {
        if t_b == 0 {
            return t_a;
        } else {
            let t_a_mod_t_b = t_a % t_b;
            t_a = t_b;
            t_b = t_a_mod_t_b;
        }
    }
}

fn lcm(a : u64, b : u64) -> u64 {
    let g = gcd(a, b);
    (a / g) * b
}

macro_rules! lcm_list {
    ($x:expr) => ($x);
    ($x:expr, $($y:expr),+) => (
        lcm($x, lcm_list!($($y),+))
    )
}

fn num_damaged_dragons(k : u64, l : u64, m : u64, n : u64, d : u64) -> u64 {
    let t_k = d / k;
    let t_l = d / l;
    let t_m = d / m;
    let t_n = d / n;
    let t_k_l = d / lcm_list!(k, l);
    let t_k_m = d / lcm_list!(k, m);
    let t_k_n = d / lcm_list!(k, n);
    let t_l_m = d / lcm_list!(l, m);
    let t_l_n = d / lcm_list!(l, n);
    let t_m_n = d / lcm_list!(m, n);
    let t_k_l_m = d / lcm_list!(k, l, m);
    let t_k_l_n = d / lcm_list!(k, l, n);
    let t_k_m_n = d / lcm_list!(k, m, n);
    let t_l_m_n = d / lcm_list!(l, m, n);
    let t_k_l_m_n = d / lcm_list!(k, l, m, n);
    let t_1 = t_k + t_l + t_m + t_n;
    let t_2 = t_k_l + t_k_m + t_k_n + t_l_m + t_l_n + t_m_n;
    let t_3 = t_k_l_m + t_k_l_n + t_k_m_n + t_l_m_n;
    let t_4 = t_k_l_m_n;
    t_1 - t_2 + t_3 - t_4
}

