fn go(s: &String, need: i32, pos: i32, i: usize) -> f64 {
  if i == s.as_bytes().len() {
    if need == pos {
      return 1f64;
    } else {
      return 0f64;
    }
  } else {
    if s.as_bytes()[i] == '+' as u8 {
      return go(s,need,pos+1,i+1);
    } else if s.as_bytes()[i] == '-' as u8 {
      return go(s,need,pos-1,i+1);
    } else if s.as_bytes()[i] == '?' as u8 {
      return (go(s,need,pos-1,i+1)+go(s,need,pos+1,i+1))*0.5;
    } else {
      panic!("");
    }
  }
}

