    h += m * 5.0 / 60.0 + s * 5.0 / 3600.0;
    m += s / 60.0;

    let (from, to) = {
        if t1 > t2 {
            (t2, t1)
        } else {
            (t1, t2)
        }
    };
    let mut count = 0;
    if from < h && h < to { count += 1; }
    if from < m && m < to { count += 1; }
    if from < s && s < to { count += 1; }

    if count == 0 || count == 3 {
        println!("YES");
    } else {
        println!("NO");
    }
}

fn read_line() -> String {
    let stdin = io::stdin();
    let mut buf = String::new();
    stdin.read_line(&mut buf).unwrap();
    buf
}

fn read_values<T>() -> Vec<T>
    where T: std::str::FromStr,
          T::Err: std::fmt::Debug
{
    read_line()
        .split(' ')
        .map(|a| a.trim().parse().unwrap())
        .collect()
}

macro_rules! parse_line {
    ($t: ty) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let a_str = a_str.trim();
        a_str.parse::<$t>().expect("parse error")
    });
    ($($t: ty),+) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let mut a_iter = a_str.split_whitespace();
        (
            $(
            a_iter.next().unwrap().parse::<$t>().expect("parse error"),
            )+
        )
    })
}

macro_rules! parse_line_to_vec {
    ($t: ty) => {{
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        (a_str
            .split_whitespace()
            .map(|x| x.parse::<$t>().unwrap())
            .collect::<Vec<$t>>())
    }};
}

fn solve() {
    let (h, m, s, t1, t2) = parse_line!(i32, i32, i32, i32, i32);
    let h = h * 5 * 2 + if m > 0 || s > 0 {1} else {0};
    let m = m * 2 + if s > 0 {1} else {0};
    let s = s * 2;
    let t1 = t1 * 5 * 2;
    let t2 = t2 * 5 * 2;
    let min = std::cmp::min(t1, t2);
    let max = std::cmp::max(t1, t2);
    let correct = (h > max || h < min) && (m > max || m < min) && (s > max || s < min);
    let incorrect = h > min && h < max && m > min && m < max && s > min && s < max;
    if correct || incorrect {
        println!("YES");
    }else{
        println!("NO");
    }
}

