#[allow(non_snake_case, non_upper_case_globals)]
fn main() {
    let num_cases: usize = 1;//read();

    for _case_num in 1..=num_cases {
        let n = read!(usize);
        let a0 = read!(u64);
        let x = read!(u64);
        let y = read!(u64);
        let k = read!(usize);
        let M = read!(u64);

        let npow = mir(n as _).pow_vec(k-1);

        let mut C = 1usize;
        for i in 2..k {
            C = C / C.gcd(i) * i;
        }
        let mut dp = vec![mi(0); C];

        let mut ans = mi(0);
        let mut a = a0;
        for _ in 0..n {
            let q = (a as usize) / C;
            let r = (a as usize) % C;

            ans += mir(q as _);
            dp[r] = mir(dp[r].val() + 1);
            a = (a * x + y) % M;
        }
        ans *= mir((k * C) as _) * npow[k-1];

        for i in 1..=k {
            let mut dn = vec![mi(0); C];
            for j in 0..C {
                ans += dp[j] * npow[k-i] * mir(j as _);
                dn[j] += dp[j] * mir((n-1) as _);
                dn[j - j % i] += dp[j];
            }
            dp = dn;
        }

        println!(ans);
    }

    out_flush();
}

