#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Affine(ModInt, ModInt);

impl Default for Affine {
    fn default() -> Self {
        Self(mi(1), mi(0))
    }
}

impl Affine {
    fn compose(self, rhs: Self) -> Self {
        Self(self.0 * rhs.0, self.1 * rhs.0 + rhs.1)
    }

    fn invoke(self, x: ModInt) -> ModInt {
        self.0 * x + self.1
    }
}

impl Add for Affine {
    type Output = Affine;

    fn add(self, rhs: Self) -> Self::Output {
        Affine(self.0 + rhs.0, self.1 + rhs.1)
    }
}

impl Mul<ModInt> for Affine {
    type Output = Affine;

    fn mul(self, rhs: ModInt) -> Self::Output {
        Affine(self.0 * rhs, self.1 * rhs)
    }
}


