fn main() {
    let num_cases: usize = 1;//read();

    for _case_num in 1..=num_cases {
        let n = read!(usize);
        let a0 = read!(u64);
        let x = read!(u64);
        let y = read!(u64);
        let k = read!(usize);
        let M = read!(u64);

        let p1 = mi(n).inv();
        let p0 = mi(1) - p1;
        let mut dp = vec![Affine(p1, mi(0)); 1];
        for i in (1..k).rev() {
            let c0 = dp.len();
            let c1 = c0 / c0.gcd(i) * i;
            dp = (0..c1).map(|j| {
                let s = j % i;
                let d1 = Affine::default() + Affine(mi(1), -mir(s as _)).compose(dp[(j - s) % c0]);
                let d0 = dp[j % c0];
                d1 * p1 + d0 * p0
            }).collect();
            //dbg!("tick");
        }

        //dbg!(&dp);
        let C = dp.len();
        let mut ans = mi(0);
        let mut a = a0;
        for _ in 0..n {
            ans += dp[(a as usize) % C].invoke(mir(a as _));
            a = (a * x + y) % M;
        }

        ans *= mi(n).pow(k as _);
        println!(ans);
    }

    out_flush();
}

