#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Affine(ModInt, ModInt);

impl Default for Affine {
    fn default() -> Self {
        Self(mi(1), mi(0))
    }
}

impl Affine {
    fn compose(self, rhs: Self) -> Self {
        Self(self.0 * rhs.0, self.1 * rhs.0 + rhs.1)
    }

    fn invoke(self, x: ModInt) -> ModInt {
        self.0 * x + self.1
    }
}

impl Add for Affine {
    type Output = Affine;

    fn add(self, rhs: Self) -> Self::Output {
        Affine(self.0 + rhs.0, self.1 + rhs.1)
    }
}

impl Mul<ModInt> for Affine {
    type Output = Affine;

    fn mul(self, rhs: ModInt) -> Self::Output {
        Affine(self.0 * rhs, self.1 * rhs)
    }
}


#[allow(non_snake_case, non_upper_case_globals)]
fn main() {
    let num_cases: usize = 1;//read();

    for _case_num in 1..=num_cases {
        let n = read!(usize);
        let a0 = read!(u64);
        let x = read!(u64);
        let y = read!(u64);
        let k = read!(usize);
        let M = read!(u64);

        let ninv = mi(n).inv();
        let mut dp = vec![Affine(ninv, mi(0)); 1];
        for i in (1..k).rev() {
            let c0 = dp.len();
            let c1 = c0 / c0.gcd(i) * i;
            dp = (0..c1).map(|j| {
                let s = j % i;
                let yes = Affine::default() + Affine(mi(1), -mi(s)).compose(dp[(j - s) % c0]);
                let no = dp[j % c0];
                (yes + no * mi(n - 1)) * ninv
            }).collect();
            //dbg!("tick");
        }

        //dbg!(&dp);
        let C = dp.len();
        let mut ans = mi(0);
        let mut a = a0;
        for _ in 0..n {
            ans += dp[(a as usize) % C].invoke(mir(a as _));
            a = (a * x + y) % M;
        }

        ans *= mi(n).pow(k as _);
        println!(ans);
    }

    out_flush();
}

pub mod solution {

use crate::io::input::Input;
use crate::io::output::output;
use crate::math::gcd::{gcd, lcm};
use crate::math::modulo::Mod_998_244_353;
use crate::misc::num_traits::ConvI32;
use crate::{dbg, out, out_line};

type Mod = Mod_998_244_353;

fn solve(input: &mut Input, _test_case: usize) {
    let n = input.usize();
    let a0 = input.i64();
    let x = input.i64();
    let y = input.i64();
    let k = input.usize();
    let m = input.i64();

    let mut max = 1;
    for x in 2..=k {
        max = lcm(max, x);
    }

    let pr_choose = Mod::ONE / Mod::new(n as i32);
    let pr_not_choose = Mod::ONE - pr_choose;

    let mut dp = vec![Mod::ZERO; max];
    for i in (1..=k).rev() {
        for start in (0..max).step_by(i) {
            for shift in (0..i).rev() {
                let j = start + shift;
                dp[j] = pr_choose * (dp[start] + Mod::new(j as i32)) + pr_not_choose * dp[j];
            }
        }
    }

    let f = |value: i64| -> Mod {
        let value = value.to_i32() as usize;
        let more = value / dp.len() * dp.len();
        dp[value - more] + pr_choose * Mod::new(k as i32) * Mod::new(more as i32)
    };
    let mut res = f(a0);
    let mut prev = a0;
    for _ in 1..n {
        prev = (prev * x + y) % m;
        res += f(prev);
    }
    res *= Mod::new(n as i32).pown(k);
    out_line!(res);
}

pub(crate) fn run(mut input: Input) -> bool {
    solve(&mut input, 1);
    output().flush();
    input.skip_whitespace();
    input.peek().is_none()
}

}
