    }
    let mut counts = vec![0i64; (height + width + 10) as usize];
    for i in 0..=(height + width) {
        let k = i + a + b;
        if i == 0 {
            counts[i as usize] = 0;
        } else if k < c {
            counts[i as usize] = 0;
        } else if c <= k && k <= d {
            counts[i as usize] = k - c + 1;
        } else if d < k {
            counts[i as usize] = d - c + 1;
        }
    }
    debug!(counts);
    let mut ans = 0;
    for i in 0..=(height + width) {
        let i = i as usize;
        ans += counts[i] * appear[i];
    }
    echo!(ans);
}

macro_rules! parse_line {
    ($t: ty) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let a_str = a_str.trim();
        a_str.parse::<$t>().expect("parse error")
    });
    ($($t: ty),+) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let mut a_iter = a_str.split_whitespace();
        (
            $(
            a_iter.next().unwrap().parse::<$t>().expect("parse error"),
            )+
        )
    })
}

#[allow(unused_macros)]
macro_rules! parse_line_to_vec {
    ($t: ty) => {{
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        (a_str
            .split_whitespace()
            .map(|x| x.parse::<$t>().unwrap())
            .collect::<Vec<$t>>())
    }};
}

