fn solve(writer: &mut std::io::BufWriter<std::io::Stdout>) {
    let (a, b, c, d) = parse_line!(u64, u64, u64, u64);
    let mut result = 0;
    // for x in a..=b {
    //     for y in b..=c {
    //         for z in c..=d {
    //             if x + y > z {
    //                 result += 1;
    //             }
    //         }
    //     }
    // }
    // eprintln!("{}", result);
    // result = 0;
    for x in a..=b {
        if c - b + 1 >= x {
            if d - c + 1 >= x {
                result += x * (x + 1) / 2;
            }else{
                let grow = d - c + 1;
                let fix = x - grow;
                result += grow * (grow + 1) / 2 + fix * grow;
            }
        }else{
            if d - c + 1 >= x {
                let min = c - b + 1;
                result += (x - min + 1 + x) * min / 2;
            }else{
                if d - b + 1 >= x {
                    let grow = d - b + 1 - x;
                    result += (d - c + 1 - grow + d - c) * grow / 2 +
                        (c - b + 1 - grow) * (d - c + 1);
                }else{
                    result += (c - b + 1) * (d - c + 1);
                }
            }
        }
    }
    writeln!(writer, "{}", result).unwrap();
}

