fn read_string() -> String {
    let mut string: String = String::new();

    std::io::stdin().read_line(&mut string)
        .ok()
        .expect("Error read line!");
    return string;
}

fn koutsu_count(koutsu : &HashMap<&str, usize> ) -> usize
{
    koutsu.values().max().unwrap().to_owned()
}

fn shuntsu_count(shuntsu : &HashMap<&str, HashSet<usize>> ) -> usize
{
    shuntsu.values().map(|x| suit_set_count(&x))
        .max().to_owned().unwrap()

}

fn suit_set_count(set : &HashSet<usize>) -> usize
{
    if set.len() <= 1  { return  set.len() }

    let mut list :Vec<_> = set.iter().collect();
    list.sort();
    let mut currrent_count = 1;
    let mut max_count = 1;
    let mut prev = list[0];
    for item in list
    {
        match item - prev
        {
            i if i > 2  =>
            {
                max_count = max(currrent_count, max_count);
                currrent_count = 1;
            }
            1 =>
            {
                currrent_count += 1;
                max_count = max(currrent_count, max_count);
            }
            2 =>
            {
                max_count = max(2, max_count);
                currrent_count = 1;
            }
            _ => { }

        }
        prev = item;
    }
    max_count
}

