        let value = &elem[0..1].parse().unwrap();
        let suit = &elem[1..2];
        shuntsu.entry(suit).or_default().insert(*value);

    }
    println!("{}", 3 - max(koutsu_count(&koutsu) ,shuntsu_count(&shuntsu)))

}

