use std::cmp::*;
use std::*;
use io::*;

struct Parser {
    tokens : Vec<String>,
}

impl Parser {
    fn new() -> Parser {
        Parser {
            tokens : Vec::new()
        }
    }

    fn renew_tokens(&mut self) -> () {
        let mut line = String::new();
        match stdin().read_line(&mut line) {
            Err(_) => {
                println!("Something terrible has happend!");
                process::exit(1);
            },
            _ => ()
        }

        let tmp : Vec<&str> = line.split_whitespace().collect();
        self.tokens = tmp.into_iter().map(String::from).collect();
        self.tokens.reverse();
    }

    fn get_token(&mut self) -> String {
        let mut res = String::from("");

        loop {
            if self.tokens.len() == 0 {
                self.renew_tokens();
                continue;
            }

            if let Some(s) = self.tokens.last() {
                res = s.clone();
                self.tokens.pop();
            }
            if res != "" {
                return res;
            }
        }
    }

    fn get_int_token(&mut self) -> String {
        let mut res = String::from("");
        let has_digit = |s: &String| -> bool {
            for (_, c) in s.chars().enumerate() {
                if '0' <= c && c <= '9' {
                    return true;
                }
            }
            false
        };

        loop {
            if self.tokens.len() == 0 {
                self.renew_tokens();
                continue;
            }

            if let Some(s) = self.tokens.last() {
                if has_digit(s) {
                    res = s.clone();
                }
            }

            self.tokens.pop();
            if res != "" {
                return res;
            }
        }
    }

    fn get_i32(&mut self) -> i32 {
        let token : String = self.get_int_token();
        let mut entered = false;
        let mut num : i32 = 0;

        for (_, c) in token.chars().enumerate() {
            if !entered {
                if let Some(tmp) = c.to_digit(10) {
                    num = tmp as i32;
                    entered = true;
                }
            }
            else {
                if let Some(tmp) = c.to_digit(10) {
                    num = num * 10 + (tmp as i32);
                }
                else {
                    break;
                }
            }
        }
        return num;
    }

    fn get_i64(&mut self) -> i64 {
        let token : String = self.get_int_token();
        let mut entered = false;
        let mut num : i64 = 0;

        for (_, c) in token.chars().enumerate() {
            if !entered {
                if let Some(tmp) = c.to_digit(10) {
                    num = tmp as i64;
                    entered = true;
                }
            }
            else {
                if let Some(tmp) = c.to_digit(10) {
                    num = num * 10 + (tmp as i64);
                }
                else {
                    break;
                }
            }
        }
        return num;
    }
}



fn main() {
    let mut cin = Parser::new();

    let b = cin.get_i64();
    let g = cin.get_i64();
    let n = cin.get_i64();

    let mut mnb :i64 = i64::MAX;
    let mut mng :i64 = i64::MAX;

    for i in 0..=b {
        if n - i <= g {
            mng = n - i;
        }
    }
    for i in 0..=g {
        if n - i <= b {
            mnb = n - i
        }
    }

