use std::io;

fn gcd(a: u64, b: u64) -> u64 {
  if a < b {
    return gcd(b, a);
  }
  if b == 0 {
    return a;
  }
  return gcd(b, a % b);
}

fn main() {
  let mut size = String::new();
  io::stdin().read_line(&mut size).unwrap();
  let size: Vec<&str> = size.split(" ").collect();
