fn sieve_of_eratosthene(n: usize) -> Vec<bool> {
    let mut is_prime = vec![true; std::cmp::max(n, 2)];

    is_prime[0] = false;
    is_prime[1] = false;


    let mut i = 2;
    loop {
        while i < n && !is_prime[i] {
            i += 1;
        }

        let cur_prime = i;

        let mut q = 2;
        while q * cur_prime < n {
            is_prime[q * cur_prime] = false;
            q += 1;
        }

        i += 1;
        if i >= n {
            return is_prime;
        }
    }
}

fn primes(is_prime: &Vec<bool>) -> Vec<usize> {
    let mut primes = Vec::new();
    for i in 0..is_prime.len() {
        if is_prime[i] {
            primes.push(i);
        }
    }

    primes
}

fn is_number_good(prime: &Vec<usize>, n: usize) -> bool {
    let mut firstmult = 0;

    for i in 0..prime.len() {
        if n % prime[i] == 0 {
            firstmult = prime[i];
            break;
        }
    }

    let mut secmult = 0;
    for i in 0..prime.len() {
        if n % prime[i] == 0 && prime[i] != firstmult {
            secmult = prime[i];
            break;
        }
    }

    if secmult == 0 {
        return false;
    }

    for i in 0..prime.len() {
        if n % prime[i] == 0 && prime[i] != firstmult && prime[i] != secmult {
                return false
            }
    }

    true
}
