pub struct TokenReader {
    reader: std::io::Stdin,
    tokens: Vec<String>,
    index: usize,
}

impl TokenReader {
    pub fn new() -> Self {
        Self {
            reader: std::io::stdin(),
            tokens: Vec::new(),
            index: 0,
        }
    }

    pub fn next<T>(&mut self) -> T
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index += 1;
        self.tokens[self.index - 1].parse().unwrap()
    }

    pub fn vector<T>(&mut self) -> Vec<T>
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index = self.tokens.len();
        self.tokens.iter().map(|tok| tok.parse().unwrap()).collect()
    }

    pub fn load_next_line(&mut self) {
        let mut line = String::new();
        self.reader.read_line(&mut line).unwrap();

        self.tokens = line
            .split_whitespace()
            .map(String::from)
            .collect();
        self.index = 0;
    }
}

fn tide(k: usize, time: usize) -> usize {
    let time = time % (2 * k);
    if time <= k {
        time
    } else {
        2 * k - time
    }
}

fn depth(k: usize, depths: &Vec<usize>, time: usize, index: usize) -> usize {
    depths[index] + tide(k, time)
}

fn prev_time(k: usize, time: usize) -> usize {
    if time == 0 {
        2 * k - 1
    } else {
        time - 1
    }
}

fn possible(k: usize, l: usize, depths: &Vec<usize>) -> bool {
    let mut dp = vec![vec![false; 2 * k]; depths.len()];
    for i in 0..2 * k {
        if depth(k, depths, i, 0) <= l {
            dp[0][i] = true;
        }
    }

    for i in 1..depths.len() {
        for t in 0..2 * k {
            let p = prev_time(k, t);
            let d = depth(k, depths, t, i);

            if d > l {
                continue;
            } else if dp[i - 1][p] {
                dp[i][t] = true;
            } else if dp[i][p] {
                dp[i][t] = true;
            }
        }
    }
    dp[depths.len() - 1].iter().any(|&b| b)
}

fn main() {
    let mut reader = TokenReader::new();
    let tests = reader.next();

    for _ in 0..tests {
        let _ = reader.next::<usize>();
        let k = reader.next();
        let l = reader.next();
        let depths = reader.vector();

        let res = possible(k, l, &depths);
        println!("{}", if res { "Yes" } else { "No" });
    }
}

