fn calc_depth(d: &Vec<i64>, p: &Vec<i64>, ki: usize, ni: usize) -> i64 {
    d[ni - 1] + p[ki]
}

fn solve() -> bool {
    let v = read_vec::<usize>();
    let (n, k, l) = (v[0], v[1], v[2] as i64);
    let d = read_vec::<i64>();
    let p = (0..2 * k)
        .map(|x| if x <= k { x as i64 } else { (2 * k - x) as i64 })
        .collect::<Vec<_>>();

    let mut dp = vec![vec![false; 2 * k]; n + 1];
    for ki in 0..2 * k {
        dp[0][ki] = true;
    }

    for ni in 1..n + 1 {
        for ki in 0..2 * k {
            let next_k = (ki + 1) % (2 * k);
            if dp[ni - 1][ki] && calc_depth(&d, &p, next_k, ni) <= l {
                dp[ni][next_k] = true;
            }
        }
        for ki in 0..2 * k {
            let next_k = (ki + 1) % (2 * k);
            if dp[ni][ki] && calc_depth(&d, &p, next_k, ni) <= l {
                dp[ni][next_k] = true;
            }
        }
    }

    dp[n].iter().any(|&x| x)
}

fn main() {
    let n = read::<usize>();
    for i in 0..n {
        if solve() {
            println!("Yes");
        } else {
            println!("No");
        }
    }
}

