macro_rules! recursive_fn {
    () => {};
    ($name0:ident $trait0:ident $_:ident $__:ident, $($name:ident $trait:ident $Arg:ident $arg:ident,)*) => {
        pub trait $trait0<$($Arg,)* Output> {
            fn call(&mut self, $($arg: $Arg,)*) -> Output;
        }

        pub struct $name0<F, $($Arg,)* Output>
        where
            F: FnMut(&mut dyn $trait0<$($Arg,)* Output>, $($Arg,)*) -> Output,
        {
            f: std::cell::UnsafeCell<F>,
            $(
                $arg: PhantomData<$Arg>,
            )*
            phantom_output: PhantomData<Output>,
        }

        impl<F, $($Arg,)* Output> $name0<F, $($Arg,)* Output>
        where
            F: FnMut(&mut dyn $trait0<$($Arg,)* Output>, $($Arg,)*) -> Output,
        {
            pub fn new(f: F) -> Self {
                Self {
                    f: std::cell::UnsafeCell::new(f),
                    $(
                        $arg: PhantomData,
                    )*
                    phantom_output: PhantomData,
                }
            }
        }

        impl<F, $($Arg,)* Output> $trait0<$($Arg,)* Output> for $name0<F, $($Arg,)* Output>
        where
            F: FnMut(&mut dyn $trait0<$($Arg,)* Output>, $($Arg,)*) -> Output,
        {
            fn call(&mut self, $($arg: $Arg,)*) -> Output {
                unsafe { (&mut *self.f.get())(self, $($arg,)*) }
            }
        }

        recursive_fn!{$($name $trait $Arg $arg,)*}
    };
}

recursive_fn! {
