    RecursiveFn10 Callable10 Arg10 arg10,
    RecursiveFn9 Callable9 Arg9 arg9,
    RecursiveFn8 Callable8 Arg8 arg8,
    RecursiveFn7 Callable7 Arg7 arg7,
    RecursiveFn6 Callable6 Arg6 arg6,
    RecursiveFn5 Callable5 Arg5 arg5,
    RecursiveFn4 Callable4 Arg4 arg4,
    RecursiveFn3 Callable3 Arg3 arg3,
    RecursiveFn2 Callable2 Arg2 arg2,
    RecursiveFn1 Callable1 Arg1 arg1,
    RecursiveFn0 Callable0 Arg0 arg0,
}

