// gcd, x, y
pub fn extended_gcd(a: i64, b: i64) -> (i64, i64, i64) {
    if a == 0 {
        (b, 0, 1)
    } else {
        let (g, y, mut x) = extended_gcd(b % a, a);
        x -= (b / a) * y;
        (g, x, y)
    }
}

pub trait HasConstVal {
    const VAL: i64;
}

// const of V has to be prime
#[derive(Copy, Clone, Eq, PartialEq)]
pub struct ModBase<M: HasConstVal + Copy> {
    v: i64,
    phantom: PhantomData<M>,
}

impl<M: HasConstVal + Copy> ModBase<M> {
    pub fn new(mut v: i64) -> Self {
        v %= M::VAL;
        if v < 0 {
            v = v + M::VAL;
        }
        Self {
            v,
            phantom: PhantomData,
        }
    }

    pub fn inv(&self) -> Self {
        let (_, x, _) = extended_gcd(self.v, M::VAL);
        Self::new(x)
    }

    pub fn pow(&self, n: usize) -> Self {
        let v = self.v;
        let mut res = Self::new(1);
        for _ in 0..n {
            res *= v;
        }
        res
    }
}

impl<M: HasConstVal + Copy> ops::Add<i64> for ModBase<M> {
    type Output = Self;

    fn add(self, rhs: i64) -> Self {
        Self::new(self.v + rhs)
    }
}

impl<M: HasConstVal + Copy> ops::Add for ModBase<M> {
    type Output = Self;

    fn add(self, rhs: Self) -> Self {
        Self::new(self.v + rhs.v)
    }
}

impl<M: HasConstVal + Copy> ops::AddAssign<i64> for ModBase<M> {
    fn add_assign(&mut self, rhs: i64) {
        self.v = (self.v + rhs) % M::VAL;
    }
}

impl<M: HasConstVal + Copy> ops::AddAssign for ModBase<M> {
    fn add_assign(&mut self, rhs: Self) {
        self.v = (self.v + rhs.v) % M::VAL;
    }
}

