#[allow(non_snake_case, non_upper_case_globals)]
fn main() {
    let num_cases: usize = 1;//read();

    for _case_num in 1..=num_cases {
        let p1 = read!(usize);
		let t1 = read!(i64);
		let p2 = read!(usize);
		let t2 = read!(i64);
		let h = read!(usize);
		let s = read!(usize);

		let x1 = p1 - s;
		let x2 = p2 - s;
		let x3 = p1 + p2 - s;

		let inf = i64::MAX;
		let mut ans = inf;
		let mut dp = vec![inf; h+1];
		dp[0] = 0;

		for i in 0..h { if dp[i] != inf {
			let t = dp[i];

			let mut k1 = 0;
			let mut k2 = 0;
			let mut dm = 0;
			loop {
				if i + dm >= h {
					ans.chmin(t + max(k1 * t1, k2 * t2));
					break;
				}
				dp[min(h, i+dm+x3)].chmin(t + max((k1+1) * t1, (k2+1) * t2));

				if (k1 + 1) * t1 < (k2 + 1) * t2 {
					k1 += 1;
					dm += x1;
				} else {
					k2 += 1;
					dm += x2;
				}
			}
		}}

		//println!("{:?}", &dp);

		ans.chmin(dp[h]);
		println!(ans);
    }

    out_flush();
}

fn run() {
    input! {
        a: (usize, i64),
        b: (usize, i64),
        e: (usize, usize),
    }
    let inf = std::i64::MAX / 2;
    let mut memo = vec![inf; e.0 + 1];
    for i in 0..=e.0 {
        for j in 0..=e.0 {
            let d = e.0.min(i * (a.0 - e.1) + j * (b.0 - e.1));
            let t = (i as i64 * a.1).max(j as i64 * b.1);
            memo[d] = memo[d].min(t);
        }
    }
    for i in 1..=e.0 {
        for j in 1..=e.0 {
            let t = (i as i64 * a.1).max(j as i64 * b.1);
            let d = (i - 1) * (a.0 - e.1) + (j - 1) * (b.0 - e.1) + a.0 + b.0 - e.1;
            for k in 0..=(e.0 / d + 1) {
                let d = (k * d).min(e.0);
                memo[d] = memo[d].min(t * k as i64);
            }
        }
    }
    for i in (0..e.0).rev() {
        memo[i] = memo[i].min(memo[i + 1]);
    }
    for i in 1..=e.0 {
