use std::cmp::{max, min};
fn main() {
    let content = io::stdin_to_string();
    let mut rd = io::Parser::new(&content);
    let (p1, t1): (i64, i64) = rd.read();
    let (p2, t2): (i64, i64) = rd.read();
    let (h, s): (i64, i64) = rd.read();
    let mut f: Vec<i64> = (0..=h)
        .map(|y| {
            (0..=y)
                .map(|x1| max(x1 * t1, (y - x1 * (p1 - s) + p2 - s - 1) / (p2 - s) * t2))
                .min()
                .unwrap()
        })
        .collect();
    let t: Vec<i64> = (0..=h)
        .map(|y| {
            (1..=y)
                .map(|x1| {
                    [
                        x1 * t1,
                        (y - s - x1 * (p1 - s) + p2 - s - 1) / (p2 - s) * t2,
                        t2,
                    ]
                    .iter()
                    .copied()
                    .max()
                    .unwrap()
                })
                .min()
                .unwrap_or(i64::MIN)
        })
        .collect();
    for i in 1..=(h as usize) {
        for j in 1..=i {
            f[i] = min(f[i], f[i - j] + t[j]);
        }
    }
    println!("{}", f[h as usize]);
}

