pub struct Scanner<B> {
    reader: B,
    buf_str: Vec<u8>,
    buf_iter: std::str::SplitWhitespace<'static>,
}
impl<B: BufRead> Scanner<B> {
    pub fn new(reader: B) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_whitespace(),
        }
    }
    pub fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = std::str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_whitespace())
            }
        }
    }

    pub fn next_split<T: std::str::FromStr>(&mut self) -> Vec<T> {
        loop {
            let mut v = Vec::new();
            while let Some(token) = self.buf_iter.next() {
                v.push(token.parse().ok().expect("Failed parse"));
            }
            if v.len() > 0 {
                return v;
            }

            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = std::str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_whitespace())
            }
        }
    }
}

// #[derive(Debug, Clone, Default, Copy)]
fn lcm(first: usize, second: usize) -> usize {
    first * second / gcd(first, second)
}

fn gcd(first: usize, second: usize) -> usize {
    let mut max = first;
    let mut min = second;
    if min > max {
        let val = max;
        max = min;
        min = val;
    }

    loop {
        let res = max % min;
        if res == 0 {
            return min;
        }

        max = min;
        min = res;
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stdout = io::stdout();
    let lock = stdout.lock();
    let stdin = io::stdin();
    let mut ow = io::BufWriter::new(lock);
    let mut scan = Scanner::new(stdin.lock());
    // let n_tests = scan.next::<usize>();
    let n_tests = 1;
    for _t_num in 1..=n_tests {
        let p1 = scan.next::<i64>();
        let t1 = scan.next::<i64>();
        let p2 = scan.next::<i64>();
        let t2 = scan.next::<i64>();
        let h = scan.next::<i64>();
        let s = scan.next::<i64>();

        let mut dp = vec![i64::MAX; h as usize + 1];
        let mut best = i64::MAX;
        dp[0] = 0;
        for th in (0..h) {
            let st = dp[th as usize];
            if st == i64::MAX {
                continue;
            }
            for (src, other) in [((p1, t1), (p2, t2)), ((p2, t2), (p1, t1))] {
                //fire 1 continously
                let d = src.0 - s;
                if d == 0 {
                    continue;
                }
                let d2 = other.0 - s;
                for i in 0..=h {
                    let c2 = (i * src.1) / other.1;
                    let td2 = c2 * d2;
                    let td1 = d * i;
                    if th + td1 + td2 >= h {
                        best = std::cmp::min(best, st + i * src.1);
                        // println!("{} {} {} {} {:?}", best, st, i, c2, src);
                        break;
                    }
                    let dd = (src.0 + other.0) - s;
                    let nt = std::cmp::max((i + 1) * src.1, (c2 + 1) * other.1) + st;
                    if th + td1 + td2 + dd >= h {
                        best = std::cmp::min(best, nt);
                        // println!("b{} {} {} {} {:?}", best, st, i, c2, src);
                    } else {
                        dp[(th + td1 + td2 + dd) as usize] =
                            std::cmp::min(nt, dp[(th + td1 + td2 + dd) as usize]);
                    }
                }
            }
        }
        // writeln!(ow, "{:?}", dp[0]);
        writeln!(ow, "{:?}", best);
        // writeln!(ow, "{}", bops);
    }
    Ok(())
}

