fn solve() {
    let n: usize = get();
    let s: Vec<char> = get_word().chars().collect();
    let m = s.len();
    let mut rev = vec![vec![0; m + 1]; 2];
    for i in 0 .. m {
        let idx = if s[i] == '(' { 0 } else { 1 };
        let opp = if s[i] == '(' { ')' } else { '(' };
        let mut grow = s[0 .. i].to_vec();
        grow.push(opp);
        let mut aa = 0;
        for j in 0 .. i + 1 {
            if grow[j ..] == s[.. i + 1 - j] {
                aa = i + 1 - j;
                break;
            }
        }
        rev[1 - idx][i] = aa;
        rev[idx][i] = i + 1;
    }
    rev[0][m] = m;
    rev[1][m] = m;
    let mut dp = vec![vec![vec![ModInt::new(0); m + 1]; n + 1]; 2 * n + 1];
    dp[0][0][0] = ModInt::new(1);
    for i in 0 .. 2 * n {
        for j in 0 .. n + 1 {
            for k in 0 .. m + 1 {
                if j < n {
                    dp[i + 1][j + 1][rev[0][k]] =
                        dp[i + 1][j + 1][rev[0][k]] + dp[i][j][k];
                }
                if j > 0 {
                    dp[i + 1][j - 1][rev[1][k]] =
                        dp[i + 1][j - 1][rev[1][k]] + dp[i][j][k];
                }
            }
        }
    }
    println!("{}", dp[2 * n][0][m]);
}

