use std::io;
use std::mem::swap;
use std::str;

fn has_valid_prime_factors(n: i64) -> bool {
    let mut n = n;
    while n % 2 == 0 {
        n /= 2;
    }
    while n % 3 == 0 {
        n /= 3;
    }
    while n % 5 == 0 {
        n /= 5;
    }
    n == 1
}

fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn factorize(n: i64) -> Vec<(i64, i64)> {
    let mut n = n;
    let mut p = 2;
    let mut ans = Vec::new();
    while p * p <= n && n > 1 {
        let mut expo = 0;
        while n % p == 0 {
            expo += 1;
            n /= p;
        }
        if expo > 0 {
            ans.push((p, expo));
        }
        p += 1;
    }
    if n > 1 {
        ans.push((n, 1));
    }
    ans
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
    let mut a: i64 = scan.token();
    let mut b: i64 = scan.token();
    if a > b {
        swap(&mut a, &mut b);
    }

    // a and b must be reduced each to its gcd.
    // a should become gcd(a, b) only dividing it by 2, 3 or 5.
    // b should become gcd(a, b) only dividing it by 2, 3 or 5.
    // In other words, a / gcd(a, b) and b / gcd(a, b) must only have 2, 3 or 5 as prime factors.
    let g = gcd(a, b);
    if a == b || (has_valid_prime_factors(a / g) && has_valid_prime_factors(b / g)) {
        let factors_without_gcd = factorize((a / g) * (b / g));
        let ans = factors_without_gcd.iter().fold(0i64, |acc, val| acc + val.1);
        writeln!(out, "{}", ans).ok();
    } else {
        writeln!(out, "-1").ok();
    }
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());
    solve(&mut scan, &mut out);
}

pub struct Scanner<R> {
    reader: R,
    buffer: Vec<String>,
}

impl<R: io::BufRead> Scanner<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![],
        }
    }

    pub fn token<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }

    pub fn tokens<T: str::FromStr>(&mut self) -> Vec<T> {
        assert!(self.buffer.is_empty());
        let mut input = String::new();
        self.reader.read_line(&mut input).expect("Failed read");
        input
            .split_whitespace()
            .map(|x| x.parse().ok().expect("Failed parse"))
            .collect()
    }
}

struct Scan {
    buffer: std::collections::VecDeque<String>,
}

impl Scan {
    fn new() -> Scan {
        Scan {
            buffer: std::collections::VecDeque::new(),
        }
    }

    fn next_line(&self) -> String {
        let mut line = String::new();
        std::io::stdin().read_line(&mut line).expect("Fail to read");
        line
    }

    fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop_front() {
                break token.parse::<T>().ok().unwrap();
            }
            let line = self.next_line();
            self.buffer = line.split_whitespace().map(String::from).collect();
        }
    }
}

fn get_order(x: usize, y: usize) -> usize {
    if x == 0 {
        return 0;
    }
    let mut x = x;
    let mut count = 0usize;
    while x % y == 0 {
        x /= y;
        count += 1;
    }
    count
}

fn _main() {
    let mut scan = Scan::new();
    let mut a: usize = scan.next();
    let mut b: usize = scan.next();
    let mut result = 0usize;
    let possible: Vec<usize> = vec![2, 3, 5];
    for i in possible {
        let ia = get_order(a, i);
        let ib = get_order(b, i);
        let diff = ia.max(ib) - ia.min(ib);
        result += diff;

        if ia > ib {
            a /= i.pow(diff as u32);
        } else if ia < ib {
            b /= i.pow(diff as u32);
        }
    }
    if a != b {
        println!("-1");
    } else {
        println!("{}", result);
    }
}

