    let mut result = 0usize;
    if a2 >= 2 {
        let val = {
            let a1 = a1 + 1;
            let a2 = a2 - 2;
            minval(a1.max(a2), a1.min(a2), depth + 1, table)
        };
        result = result.max(val);
    }
    if a1 >= 2 {
        let val = {
            let a1 = a1 - 2;
            let a2 = a2 + 1;
            minval(a1.max(a2), a1.min(a2), depth + 1, table)
        };
        result = result.max(val);
    }
    table[a1][a2] = result;
    result
}

