fn dfs(a: &[u64], k: usize, sup: bool, used: u64, b: &mut Vec<u64>) {
    if k == a.len() {
        b.push(used);
        return;
    }
    let y = if !sup {
        a[k]
    } else {
        6
    };
    for i in 0..=y {
        if used >> i & 1 == 0 {
            dfs(a, k + 1, sup || i < a[k], used | (1 << i), b);
        }
    }
}

