fn trivial_coincide(a_barrier: &LinkedList<i32>, b_barrier: &LinkedList<i32>) -> bool {
    let iter = a_barrier.iter().zip(b_barrier.iter());
    let mut difference = None;
    for (a, b) in iter {
        match difference {
            Some(diff) => {
                if (*a - *b) != diff {
                    return false;
                }
            },
            None => {
                difference = Some(*a - *b);
            }
        }
    }
    return true;
}

