pub fn process(n: i32, m: i32) -> u64 {
  let mut res: u64 = 0;
  for i in 1..=min(m, n) {
    for j in 1..=min(m, n) {
      if (i * i + j * j) % m != 0 { continue }
      let k = ((n - i) / m) as u64;
      let l = ((n - j) / m) as u64;
      res += ((k + 1) * (l + 1));
    }
  }
  res
}

