use std::io::{self, Write};

fn inv(mut a: i64, modulo: i64) -> i64 {
    let mut b: i64 = modulo - 2;
    let mut ans: i64 = 1;
    while b > 0 {
        if b & 1 == 1 {
            ans = (ans * a) % modulo;
        }
        a = (a * a) % modulo;
        b >>= 1;
    }
    ans
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut sc = cf_scanner::Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());

    let (n, modulo): (usize, i64) = (sc.next(), sc.next());

    let mut pow2: Vec<i64> = vec![1; n + 1];
    (1..=n).for_each(|i| pow2[i] = (2 * pow2[i-1]) % modulo);

    let mut fact: Vec<i64> = vec![1; n + 1];
    (1..=n).for_each(|i| fact[i] = (i as i64 * fact[i-1]) % modulo);

    let i_fact: Vec<i64> = (0..=n).map(|i| inv(fact[i], modulo)).collect();

    let mut choose: Vec<Vec<i64>> = vec![vec![0; n + 1]; n + 1];
    for i in 0..=n {
        for j in 0..=i {
            choose[i][j] = ((fact[i] * i_fact[j]) % modulo * i_fact[i - j]) % modulo;
        }
    }

    let mut dp: Vec<Vec<i64>> = vec![vec![0; n + 5]; n + 5];
    dp[0][0] = 1;
    for i in 1..=n {
        dp[i][i] = pow2[i-1];
        for j in 1..=i {
            for k in 1..j {
                if i < k + 1 {
                    break;
                } 
                dp[i][j] += ((pow2[k-1] * choose[j][k]) % modulo * dp[i - k - 1][j - k]) % modulo;
                dp[i][j] %= modulo;
            }
        }
    }

    let ans: i64 = (1..=n).fold(0 as i64, |x, y| (x + dp[n][y]) % modulo);

    writeln!(out, "{}", ans).unwrap();
}

