fn run<I: Input, O: Write>(mut kin: I, mut out: O) {
    let t: usize = 1; // kin.parse();
    for _ in 0..t {
        case(&mut kin, &mut out);
    }
} 
fn case<I: Input, O: Write>(mut kin: I, mut out: O) {
    let (n, m): (usize, u32) = kin.parse();
    set_var_mod(m);
    let mut dp = vec![vec![mint(0); n + 1]; n + 1]; // [count][pos]
    let mut miss = vec![mint(0); n + 1];
    miss[0] = mint(1);
    let mut any = vec![vec![mint(0); n + 1]; n + 1];
    for i in 1..=n {
        let mut dp_new = vec![vec![mint(0); n + 1]; n + 1];
        let mut any_new = vec![vec![mint(0); n + 1]; n + 1];
        for c in 0..i {
            let mut sum = mint(0);
            for j in 0..c {
                sum += dp[c][j] + any[c][j];
                dp_new[c + 1][j + 1] += sum;
            }
            let miss_new = sum;
            let mut sum = mint(0);
            for j in (0..c).rev() {
                sum += any[c][j];
                any_new[c + 1][j] += sum;
            }
            for j in 0..=c {
                any_new[c + 1][j] += miss[c];
            }
            miss[c] = miss_new;
        }
        dp = dp_new;
        any = any_new;
        // d!(dp, any, miss);
    }
    let s1: Mint = dp.iter().flatten().copied().sum();
    let s2: Mint = any.iter().flatten().copied().sum();
    let ans = s1 + s2;
    wln!(out, "{}", ans);
}
