fn run() {
    input! {
        n: usize,
        m: u32,
    }
    StaticMod::set_modulo(m);
    let pc = precalc::Precalc::new(n);
    let mut pow = vec![M::one(); n + 1];
    let two = M::new(2);
    for i in 1..=n {
        pow[i] = pow[i - 1] * two;
    }
    // dp[a][b]: 最後の空白がa, b個置いた
    let mut dp = vec![vec![M::zero(); n + 2]; n + 2];
    dp[0][0] = M::one();
    for i in 0..=n {
        for j in 0..=i {
            let way = dp[i][j];
            if way.is_zero() {
                continue;
            }
            for k in 1..=(n - i) {
                dp[i + k + 1][j + k] += pow[k - 1] * way * pc.comb(j + k, j);
            }
        }
    }
    let mut ans = M::zero();
    for dp in dp[n + 1].iter() {
        ans += *dp;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

