    let f = MemorizedFactorial::new(n * 2);
    let mut ans = M::zero();
    let mut dp = vec![vec![M::zero(); n + 1]; n + 1];
    let mut pre = vec![M::zero(); n + 1];
    for i in 1..=n {
        for j in 0..i {
            pre[i] += f.inv_fact[j] * f.inv_fact[i - j - 1];
        }
        pre[i] *= M::from(i).inv();
    }
    // processed, sikiri
    dp[0][0] = M::one();
    for i in 0..n {
        for j in 0..=i {
            let d = dp[i][j];
            if d.is_zero() {
                continue;
            }
            for k in 1..=n - i {
                let mut ni = i + k;
                let mut nj = j;
                if i > 0 {
                    ni += 1;
                    nj += 1;
                }
                if ni <= n {
                    dp[ni][nj] += d * pre[k];
                }
            }
        }
    }
    for j in 0..=n {
        ans += dp[n][j] * f.fact[n - j];
    }
    println!("{}", ans);
