enum Chess{
    W,
    B
}

fn parse()->Vec<Chess>{
    let mut input = String::new();
    stdin().read_line(&mut input).unwrap();
    let mut vec = vec!();

    for c in input.trim().chars(){
        if 'W' ==c{
            vec.push(Chess::W)
        }else{
            vec.push(Chess::B)
        }
    }
    vec
}
fn is_alternate(arr:Vec<Chess>)->bool{
    for c in 0..arr.len()-1{
         match arr[c]{
            Chess::W => match arr[c+1]{
                Chess::W => return false,
                _=> continue
            },
            Chess::B=>match arr[c+1]{
                Chess::W=> continue,
                _=> return false
            }
        } 
    } 
    true
}

