use matrix::*;
type Mat = SquareMatrix<M>;

impl SemiRing for M {
    fn zero() -> Self {
        M::zero()
    }
    fn one() -> Self {
        M::one()
    }
}

fn lcp(x: &[u8], y: &[u8]) -> usize {
    x.iter().zip(y).take_while(|p| *p.0 == *p.1).count()
}

fn run() {
    input! {
        n: usize,
        m: usize,
        s: [bytes; n],
    }
    let mut id = 0;
    let mut map = std::collections::BTreeMap::new();
    for s in s.iter() {
        for i in 0..s.len() {
            let s = s[i..].iter().cloned().collect::<Vec<_>>();
            map.entry(s).or_insert_with(|| {
                let v = id;
                id += 1;
                v
            });
        }
    }
    map.insert(vec![], id);
    id += 1;
    let mut edge = vec![];
    for (x, &src) in map.iter() {
        if x.is_empty() {
            for a in s.iter() {
                for b in s.iter() {
                    let len = lcp(a, b);
                    let a = a[len..].iter().cloned().collect::<Vec<_>>();
                    let b = b[len..].iter().cloned().collect::<Vec<_>>();
                    if !a.is_empty() && !b.is_empty() {
                        continue;
                    }
                    let mut pre = src;
                    for _ in 1..len {
                        edge.push((pre, id));
                        pre = id;
                        id += 1;
                    }
                    if a.is_empty() {
                        let dst = *map.get(&b).unwrap();
                        edge.push((pre, dst));
                    } else if b.is_empty() {
                        let dst = *map.get(&a).unwrap();
                        edge.push((pre, dst));
                    }
                }
            }
        } else {
            for a in s.iter() {
                let len = lcp(a, x);
                let a = a[len..].iter().cloned().collect::<Vec<_>>();
                let b = x[len..].iter().cloned().collect::<Vec<_>>();
                if !a.is_empty() && !b.is_empty() {
                    continue;
                }
                let mut pre = src;
                for _ in 1..len {
                    edge.push((pre, id));
                    pre = id;
                    id += 1;
                }
                if a.is_empty() {
                    let dst = *map.get(&b).unwrap();
                    edge.push((pre, dst));
                } else if b.is_empty() {
                    let dst = *map.get(&a).unwrap();
                    edge.push((pre, dst));
                }
            }
        }
    }
    let src = *map.get(&vec![]).unwrap();
    let mut dsu = DSU::new(id);
    for &(a, b) in edge.iter() {
        dsu.unite(a, b);
    }
    let mut index = vec![id; id];
    let mut p = 0;
    for i in 0..id {
        if dsu.same(i, src) {
            index[i] = p;
            p += 1;
        }
    }
    let mut mat = Mat::zero(p);
    for &(a, b) in edge.iter() {
        if index[a] < id {
            *mat.get_mut(index[a], index[b]) += M::one();
        }
    }
    let pow = mat.mat_pow(m);
    let ans = pow.get_at(index[src], index[src]);
    println!("{}", ans);
}

fn main() {
    run();
}

