fn pow_with_mod(mut a: i64, mut n: i64) -> i64 {
    let mut acc = 1;
    a = a % MOD;
    while n > 0 {
        if n & 1 == 1 {
            acc = (acc * a) % MOD;
        }
        a = (a * a) % MOD;
        n >>= 1;
    }
    acc
}

