    let pa = ModInt::new(pa);
    let pb = ModInt::new(pb);
    let pab = pa + pb;
    let pabinv = pab.inv();
    for i in (0..k).rev() {
        dp[i][k] = pa * pb.inv() + ModInt::new((i + k) as i64);
        for j in (1..k).rev() {
            let mut val = dp[i][j + 1] * pa;
            if i + j < k {
                val += dp[min(k, i + j)][j] * pb;
            } else {
                val += pb * ModInt::new((i + j) as i64);
            }
            dp[i][j] = val * pabinv;
        }
        let val = dp[i][1];
        dp[i][0] = val;
    }
    puts!("{}\n", dp[0][0]);
