fn solve() {
    let (a, x, y) = parse_line!(i64, i64, i64);
    if y <= 0 || y % a == 0 || x.abs() >= a {
        return println!("-1");
    }
    if y < a {
        if (x * 2).abs() < a {
            println!("1");
        }else{
            println!("-1");
        }
        return;
    }
    let y = y - a;
    let period = y / (2 * a);
    let left = y % (2 * a);
    if left < a {
        if (x * 2).abs() < a {
            println!("{}", 2 + period * 3);
        }else{
            println!("-1");
        }
    }else{
        if x < 0 {
            println!("{}", 3 + period * 3);
        }else if x > 0 {
            println!("{}", 4 + period * 3);
        }else{
            println!("-1");
        }
    }
}

