use crate::comprog_lib::scanner::Scanner;
use std::cmp::min;
use std::io::{self, Read, Write};
pub fn solve<R: Read, W: Write>(read: R, out: &mut W) -> io::Result<()> {
    let mut sc = Scanner::from(read);
    let n = sc.usize();
    let s = sc.token();
    let mut next = vec![[n; 26]; n + 1];
    for i in (0..n).rev() {
        next[i] = next[i + 1].clone();
        next[i][(s[i] - b'a') as usize] = i;
    }
    #[allow(non_snake_case)]
    let INF = std::i32::MAX;
    let mut dp = vec![vec![INF; n + 1]; n + 1];
    let mut dp2 = vec![vec![[INF; 26]; n + 1]; n + 1];
    for i in 0..=n {
        dp[i][i] = 0;
        for a in 0..26 {
            dp2[i][i][a] = 0;
        }
    }
    for len in 1..=n {
        for l in 0..=n - len {
            let r = l + len;
            for a in 0..26 {
                let mut x = len as i32;
                if (s[r - 1] - b'a') as usize == a {
                    x = min(x, dp2[l][r - 1][a]);
                }
                for k in l + 1..r {
                    x = min(x, dp2[l][k][a] + dp[k][r]);
                }
                dp2[l][r][a] = x;
            }
            dp[l][r] = dp2[l][r].iter().cloned().min().unwrap() + 1;
        }
    }
    let ans = dp[0][n];
    writeln!(out, "{}", ans)?;
    Ok(())
}
