fn rec(l: usize, r: usize, s: &[u8], memo: &mut [Vec<Option<usize>>]) -> usize {
	if l > r { return 0; }
	if let Some(res) = memo[l][r] {
		return res;
	}
	let mut res = r-l+1;
	for i in l+1..=r {
		m!(<, res, rec(l,i-1,s,memo) + rec(i,r,s,memo));
		if s[l] == s[i] {
			m!(<, res, rec(l+1,i-1,s,memo) + rec(i,r,s,memo));
		}
	}
	memo[l][r].replace(res);
	res
}

