fn solve() {
    let n = parse_line!(u64);
    let s: Vec<_> = parse_line!(String).bytes().map(|c| (c - b'0') as u64).collect();
    let l = s.len();
    let mut dp = vec![std::u64::MAX; l + 1];
    dp[0] = 0;
    let mut digits = vec![0; l + 1];
    for (i, &c) in s.iter().enumerate() {
        for j in (1..=i + 1).rev() {
            digits[j] = digits[j - 1] * 10 + c;
        }
        for j in 0..=i {
            if digits[j + 1] >= n {
                break;
            }
            if j > 0 && s[i - j] == 0 {
                continue;
            }
            dp[i + 1] = std::cmp::min(dp[i + 1], dp[i - j] * n + digits[j + 1]);
        }
    }
    println!("{}", dp[l]);
}

