pub struct Scanner<B> {
    reader: B,
    buffer: Vec<String>,
}

impl<B: BufRead> Scanner<B> {
    pub fn new(reader: B) -> Self {
        Self {
            reader,
            buffer: Vec::new(),
        }
    }

    pub fn next<T: FromStr>(&mut self) -> T
    where
        T::Err: ::std::fmt::Debug,
    {
        if let Some(front) = self.buffer.pop() {
            front.parse::<T>().expect(&front)
        } else {
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Line not read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
            self.next()
        }
    }
}

// Try Codeforces
// author: Leonardone @ NEETSDKASU


fn solve(n: i64, m: i64, k: i64) -> (i64, i64) {

    if k < n {
        return (k + 1, 1);
    }

    let e = k - n;
    let r = e / (m - 1);
    let c = e % (m - 1);

    let y = n - r;
    let x = if r % 2 == 0 { c + 2 } else { m - c }; 

    return (y, x);
}

fn main() {
    let mut stdin = String::new();
    std::io::Read::read_to_string(
        &mut std::io::stdin(),
        &mut stdin).unwrap();
    let mut stdin = stdin.split_whitespace();
    let mut get = || stdin.next().unwrap();
    macro_rules! get {
        ($t:ty) => (get().parse::<$t>().unwrap());
        () => (get!(i64));
    }

    let n = get!();
    let m = get!();
    let k = get!();

    if n * m < 20 {
        for e in 0..n*m {
            let (row, col) = solve(n, m, e);
            let (r, c) = brute_force(n, m, e);
            if row != r || col != c {
                //println!("error {} {} {}", n, m, e);
                //println!("solve {} {}", row, col);
                //println!("bf    {} {}", r, c);
                //panic!();
                break;
            }
        }
    }

    let (row, col) = solve(n, m, k);

    println!("{} {}", row, col);

}

fn brute_force(n: i64, m: i64, k: i64) -> (i64, i64) {
    let mut row = 1;
    let mut col = 1;
    let mut rem = k;

    if rem == 0 {
        return (row, col);
    }

    for _ in 0..n-1 {
        row += 1;
        rem -= 1;
        if rem == 0 {
            return (row, col);
        }
    }

    let mut state = 0;
    for _ in 0..rem {
        match state {
        0 => {
            col += 1;
            if col == m {
                state += 1;
            }
        },
        2 => {
            col -= 1;
            if col == 2 {
                state += 1;
            }
        },
        _ => {
            row -= 1;
            state = (state + 1) % 4;
        },
        }
    }
    return (row, col);
}

