fn min_points(nd : Vec<i32>, nums : Vec<i32>) -> i32 {
    let n = nd[0] as usize;
    let d = nd[1] ;

    let mut high : usize = 0;
    let mut ans : usize = 0;

    for  low in 0..n {
        while  high < n && nums[high] - nums[low] <= d {
            ans = max(ans, high - low);
            high += 1;
        }
    }

    (n-ans-1) as i32

}


