fn solve<Inner: BufRead, Output: Write>(inf: &mut Input<Inner>, ouf: &mut Output) {
	let (n, d) = read!(inf,usize,i32);
	let mut a = vec![0; n];
	for i in 0..n {
		a[i] = read!(inf,i32);
	}
	a.sort_unstable();
	let mut ans = n;
	for i in 0..n {
		for j in i..n {
			if a[j] - a[i] <= d {
				ans = min(ans, i + n - 1 - j);
			}
		}
	}
	writeln!(ouf, "{}", ans);
}

