fn count_pre(m: u64, n: u64) -> u64 {
    let mut ans = 0;
    let mut k = 0;
    while (m << k) <= n {
        if (m << k) + (1 << k) - 1 <= n {
            ans += 1 << k;
        } else {
            ans += n - (m << k) + 1;
        }
        k += 1;
    }
    ans
}

fn count(m: u64, n: u64) -> u64 {
    if m % 2 == 1 {
        count_pre(m, n)
    } else {
        count_pre(m, n) + count_pre(m + 1, n)
    }
}

fn run() {
    input! {
        n: u64,
        k: u64,
    }
    let mut ans = 1;
    let mut ok = 0;
    let mut ng = n / 2 + 1;
    while ng - ok > 1 {
        let m = (ok + ng) / 2;
        if count(2 * m + 1, n) >= k {
            ok = m;
        } else {
            ng = m;
        }
    }
    ans = std::cmp::max(ans, 2 * ok + 1);
    if count(2, n) >= k {
        let mut ok = 1;
        let mut ng = n / 2 + 1;
        while ng - ok > 1 {
            let m = (ok + ng) / 2;
            if count(2 * m, n) >= k {
                ok = m;
            } else {
                ng = m;
            }
        }
        ans = std::cmp::max(ans, 2 * ok);
    }
    println!("{}", ans);
}

