use std::io::stdin;
use std::cmp::max;

fn check(res: i64, k: i64, pow: i64, n:i64) -> bool{
    if res % 2 == 0 {
        res * pow + (k - 2 * pow + 1) <= n
    } else {
        let mut pow_k = 1;
        let mut b_k = k;
        loop {
            if b_k > 1{
                pow_k *= 2;
                b_k /= 2;
            } else { break; }
        }
        res * pow_k + (k - pow_k) <= n
    }
}

