use std::io::Write;

fn run() {
    input! {
        n: usize,
        m: usize,
        q: usize,
        val: [u32; n],
        e: [(usize1, usize1); m],
        ask: [(u8, usize1); q],
    }
    let mut dsu = DSU::new(n);
    let mut del = vec![false; m];
    for &(op, k) in ask.iter() {
        if op == 2 {
            del[k] = true;
        }
    }
    let mut add = vec![0; n];
    for (&(a, b), del) in e.iter().zip(del.iter()) {
        if !*del {
            if let Some((a, b)) = dsu.unite(a, b) {
                dsu.undo();
                add[b] = dsu.size(a);
                dsu.unite(a, b);
            }
        }
    }
    let mut width = vec![0; q];
    for (width, &(op, k)) in width.iter_mut().zip(ask.iter()).rev() {
        if op == 2 {
            let (a, b) = e[k];
            if let Some((a, b)) = dsu.unite(a, b) {
                dsu.undo();
                add[b] = dsu.size(a);
                dsu.unite(a, b);
            }
        } else {
            *width = dsu.size(k);
        }
    }
    let mut r = vec![];
    for i in 0..n {
        if i == dsu.root(i) {
            r.push(i);
        }
    }
    for r in r.windows(2) {
        let (a, b) = (r[0], r[1]);
        if let Some((a, b)) = dsu.unite(a, b) {
            dsu.undo();
            add[b] = dsu.size(a);
            dsu.unite(a, b);
        }
    }
    let mut index = vec![0; n];
    for i in 0..n {
        let mut pos = i;
        let mut sum = add[pos];
        while let Some(p) = dsu.parent(pos) {
            pos = p;
            sum += add[pos];
        }
        index[i] = sum;
    }
    for r in r.windows(2) {
        dsu.undo();
    }
    let mut seg = segment_tree::PURQ::new(n, (0, n), |a, b| std::cmp::max(*a, *b));
    for (i, &val) in val.iter().enumerate() {
        let k = index[i];
        seg.update_tmp(k, (val, k));
    }
    seg.update_all();
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    for (&(op, k), &width) in ask.iter().zip(width.iter()) {
        if op == 1 {
            let l = index[dsu.root(k)];
            let r = l + width;
            let (val, k) = seg.find(l, r);
            if k < n {
                seg.update(k, (0, n));
            }
            writeln!(out, "{}", val).ok();
        } else {
            dsu.undo();
        }
    }
}

