fn solve_part(v: &Vec<(usize, i64)>) -> Option<i64> {
    let diff = v[1].1 - v[0].1;
    let mut was_skipped = false;
    let mut skipped_id = v[0].0;
    let mut last = v[0].1 - diff;
    for (_, (pos, x)) in v.iter().enumerate() {
        if last + diff != *x {
            if was_skipped {
                return None;
            }
            was_skipped = true;
            skipped_id = *pos;
            continue;
        }
        last = *x;
    }
    Some(skipped_id as i64 + 1)
}

