struct Ring {
    p: Wrapping<i64>,
    f: Option<Vec<i64>>
}

impl Ring {
    fn new() -> Self { Self { p: Wrapping(998244353), f: None } }

    fn mult(&self, a:i64, b: i64) -> i64 {
        (((Wrapping(a) * Wrapping(b)) % self.p + self.p) % self.p).0
    }

    fn precompute_factorial(&mut self, v: i64) {
        let mut r = 1;
        let mut tmp = vec![1; v as usize + 1];
        for j in 2..=v {
            r = self.mult(r, j);
            tmp[j as usize] = r;
        }
        self.f = Some(tmp);
    }

    fn factorial(&mut self, v: i64) -> i64 {
        if let None = self.f {
            self.precompute_factorial(v);
        }
        self.precompute_factorial(v);
        *self.f.as_ref().unwrap().get(v as usize).unwrap()
    }

    fn bin_pow(&self, mut n:i64, mut k: i64) -> i64 {
        let mut res = 1;
        while k > 0 {
            if k & 1 == 1 {
                res = self.mult(res, n);
            }
            n = self.mult(n, n);
            k >>= 1;
        }
        res
    }

    fn inverse(&self, n:i64) -> i64 {
        self.bin_pow(n, self.p.0-2)
    }
}


S!(SolutionA self {
    let n: i64 = self.rw().scan();
    let m: i64 = self.rw().scan();
    let mut ans;
    if m <= 2 {
        ans = 0;
    } else {
        let mut r = Ring::new();
        let a = r.factorial(m);
        let bp = r.factorial(n-1);
        let bz = r.factorial(m-(n-1));
        let br = r.inverse(bz);
        let b = r.inverse(bp);
        ans  = r.mult(a, b);
        ans = r.mult(ans, br);
        ans = r.mult(ans, n-2);
        ans = r.mult(ans, r.bin_pow(2, n-3));
    }
    writeln!(self.rw(), "{}", ans).unwrap();
});

