struct Scanner<R> {
    reader: R,
    buf_str: Vec<u8>,
    buf_iter: str::SplitAsciiWhitespace<'static>,
}

impl<R: io::BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_ascii_whitespace(),
        }
    }

    fn t<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_ascii_whitespace())
            }
        }
    }
}

trait RW<B: BufRead, W: Write> {
    fn reader(&mut self) -> &mut Scanner<B>;
    fn writer(&mut self) -> &mut W;
}

enum RWE<'a> {
    InMemory(Scanner<Cursor<&'a str>>, Vec<u8>),
    Stdio(
        Scanner<std::io::StdinLock<'a>>,
        std::io::BufWriter<std::io::StdoutLock<'a>>,
    ),
}

impl<'a> RWE<'a> {
    fn scan<T: str::FromStr>(&mut self) -> T {
        match self {
            RWE::InMemory(r, _) => r.t(),
            RWE::Stdio(r, _) => r.t(),
        }
    }
}

impl<'a> std::io::Write for RWE<'a> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            RWE::InMemory(_, w) => w.write(buf),
            RWE::Stdio(_, w) => w.write(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            RWE::InMemory(_, w) => w.flush(),
            RWE::Stdio(_, w) => w.flush(),
        }
    }
}

trait Solution<'a> {
