mod scanner {
    use std::io::{Read, Stdin, stdin};
    use std::str::FromStr;

    pub struct Scanner<T: Read> {
        source: T,
        buffer: Vec<u8>,
        available: usize,
        ptr: usize
    }

    impl<T: Read> Scanner<T> {
        pub fn new(source: T) -> Scanner<T> {
            const BUFFER_SIZE: usize = 32 * 1024 * 1024; // 32 MB of buffer size
            Scanner {
                source,
                buffer: vec![0u8; BUFFER_SIZE],
                available: 0,
                ptr: 0
            }
        }

        fn read_block(&mut self) {
            self.available = self.source.read(self.buffer.as_mut()).unwrap();
            self.ptr = 0;
        }

        fn read_byte(&mut self) -> Option<u8> {
            if self.ptr >= self.available {
                self.read_block();
                if self.available == 0 {
                    // Hit EOF.
                    return None;
                }
            }

            let value = self.buffer[self.ptr];
            self.ptr += 1;

            Some(value)
        }

        pub fn read_token(&mut self) -> Option<String> {
            // Skip any leading whitespace characters.
            let mut b;
            loop {
                b = match self.read_byte() {
                    Some(b) => b,
                    None => return None
                };
                if !(b as char).is_ascii_whitespace() {
                    break;
                }
            }

            let mut buffer = String::new();
            loop {
                if (b as char).is_ascii_whitespace() {
                    break;
                }

                buffer.push(b as char);
                b = match self.read_byte() {
                    Some(b) => b,
                    None => break
                };
            }

            Some(buffer)
        }

        pub fn read<U: FromStr>(&mut self) -> Option<U> {
            let token = self.read_token()?;
            <U as FromStr>::from_str(token.as_str()).ok()
        }
    }

    impl Scanner<Stdin> {
        pub fn from_stdin() -> Scanner<Stdin> {
            Scanner::new(stdin())
        }
    }
}

