const MOD: i64 = 998244353i64;

struct Binom {
    fact: Vec<i64>,
    inv: Vec<i64>,
    factinv: Vec<i64>,
}

impl Binom {
    fn new(max_n: usize) -> Self {
        let mut b = Binom {
            fact: vec![0i64; max_n + 1],
            inv: vec![0i64; max_n + 1],
            factinv: vec![0i64; max_n + 1],
        };

        b.fact[0] = 1;
        for i in 1..=max_n {
            b.fact[i] = b.fact[i - 1] * i as i64 % MOD;
        }

        b.inv[1] = 1;
        for i in 2..=max_n {
            b.inv[i] = (-MOD / i as i64 * b.inv[(MOD % i as i64) as usize] % MOD + MOD) % MOD;
        }

        b.factinv[0] = 1;
        for i in 1..=max_n {
            b.factinv[i] = b.factinv[i - 1] * b.inv[i] % MOD;
        }

        b
    }

    fn binom(&self, n: i64, m: i64) -> i64 {
        let n = n as usize;
        let m = m as usize;
        self.fact[n] * self.factinv[m] % MOD * self.factinv[n - m] % MOD
    }
}

fn fast_pow(mut base: i64, mut e: i64) -> i64 {
    let mut res = 1i64;
    while e > 0 {
        if e & 1 == 1 {
            res = res * base % MOD;
        }
        base = base * base % MOD;
        e >>= 1;
    }

    res
}

fn main() {
    let mut reader = Scanner::from_stdin();
    let binom = Binom::new(200000);

    let n: i64 = reader.read().unwrap();
    let m: i64 = reader.read().unwrap();
    if n <= 2 {
        println!("0");
        return;
    }

    let ans = binom.binom(m, n - 1) * (n - 2) % MOD * fast_pow(2i64, n - 3) % MOD;
    println!("{}", ans);
}

