fn solve<Inner: BufRead, Output: Write>(inf: &mut Input<Inner>, ouf: &mut Output) {
	let (p, mut y) = read!(inf,i32,i32);
	while y > p {
		let mut fl = true;
		let mut i = 2;
		while i * i <= y {
			if y % i == 0 {
				if i <= p {
					fl = false;
				}
				break;
			}
			i += 1;
		}
		if fl {
			writeln!(ouf, "{}", y);
			return;
		}
		y -= 1;
	}
	writeln!(ouf, "-1");
}

use std::io;
use std::fs::File;
use std::cmp;

fn main() {
    let stdin = io::stdin();
    let buf :Box<io::BufRead> = if cfg!(feature = "intxt") {
        eprintln!("file mode");
        let file = File::open("in.txt").unwrap();
        Box::new(io::BufReader::new(file))
    } else {
        eprintln!("stdin mode");
        Box::new(stdin.lock())
    };
    let mut sc = Scanner::new(buf);

    let (p, y) :(i32, i32) = (sc.next(), sc.next());

    for x in (p+1..y+1).rev() {
        let mut prime = true;
        let md = cmp::min(p, (x as f32).sqrt() as i32) + 1;
        for d in 2..md {
            if x % d == 0 {
                prime = false;
                break;
            }
        }
        if prime {
            println!("{}", x);
            return;
        }
    }
    println!("{}", -1);
}


struct Scanner<B: io::BufRead> {
    reader: B,
    buffer: Vec<String>,
}

impl<B: io::BufRead> Scanner<B> {
    fn new(reader: B) -> Self {
        Self {
            reader,
            buffer: Vec::new(),
        }
    }

    fn next<T: std::str::FromStr>(&mut self) -> T
    where
        T::Err: std::fmt::Debug,
    {
        if let Some(s) = self.buffer.pop() {
            T::from_str(&s).unwrap()
        } else {
            let mut s = String::new();
            let r = self.reader.read_line(&mut s).unwrap();
            assert!(r > 0);
            self.buffer = s.split_whitespace().rev().map(String::from).collect();
            return self.next();
        }
    }
}

