use std::cmp::*;
use std::collections::BTreeMap;

fn run() {
    input! {
        n: usize,
        p: [usize; n],
    }
    let mut cnt = [0; 2];
    for p in p.iter() {
        if *p == 0 {
            continue;
        }
        cnt[*p % 2] += 1;
    }
    let even = n / 2 - cnt[0];
    let odd = (n + 1) / 2 - cnt[1];
    let inf = n;
    let mut dp = BTreeMap::<(usize, usize, usize), usize>::new();
    dp.insert((0, even, odd), 0);
    dp.insert((1, even, odd), 0);
    for p in p.iter().rev() {
        let mut next = BTreeMap::<(usize, usize, usize), usize>::new();
        for ((b, x, y), v) in dp {
            if *p == 0 {
                if x > 0 {
                    let po = next.entry((0, x - 1, y)).or_insert(inf);
                    *po = min(*po, v + (b ^ 0));
                }
                if y > 0 {
                    let po = next.entry((1, x, y - 1)).or_insert(inf);
                    *po = min(*po, v + (b ^ 1));
                }
            } else {
                let po = next.entry((*p % 2, x, y)).or_insert(inf);
                *po = min(*po, v + (b ^ (*p & 1)));
            }
        }
        dp = next;
    }
    let mut ans = inf;
    for (_, v) in dp {
        ans = min(ans, v);
    }
    println!("{}", ans);
}

fn main() {
    run();
}

