use std::cmp::Ordering::{self, Greater, Less};
use std::cmp::{max, min};
use std::collections::{BTreeMap, BTreeSet, BinaryHeap, HashMap, HashSet, VecDeque};
use std::error::Error;
use std::io::{self, BufReader, BufWriter, Read, Write};
use text_scanner::{scan, scan_iter, scanln, scanln_iter};
use utils::adj4_iter;

fn run() {
    let n: usize = scan();
    let p: Vec<usize> = scan_iter().collect();
    let mut zero = 0;
    let mut one = 0;
    for i in 1..n + 1 {
        if !p.contains(&i) {
            if i % 2 == 0 {
                zero += 1;
            } else {
                one += 1;
            }
        }
    }
    let mut dp = vec![vec![vec![vec![i32::max_value(); 2]; one + 1]; zero + 1]; n + 1];
    dp[0][0][0][0] = 0;
    dp[0][0][0][1] = 0;
    for i in 0..n {
        for z in 0..zero + 1 {
            for o in 0..one + 1 {
                for cur in 0..2 {
                    if dp[i][z][o][cur] == i32::max_value() {
                        continue;
                    }
                    for next in 0..2 {
                        if p[i] != 0 && p[i] % 2 != next {
                            continue;
                        }
                        let nz = if p[i] == 0 && next == 0 { z + 1 } else { z };
                        let no = if p[i] == 0 && next == 1 { o + 1 } else { o };
                        if nz > zero || no > one {
                            continue;
                        }
                        let nvalue =
                            dp[i][z][o][cur] + if cur as i32 != next as i32 { 1 } else { 0 };
                        dp[i + 1][nz as usize][no as usize][next as usize].set_min(nvalue);
                    }
                }
            }
        }
    }
    let mut ans = i32::max_value();
    for z in 0..zero + 1 {
        for o in 0..one + 1 {
            for cur in 0..2 {
                ans.set_min(dp[n][z][o][cur]);
            }
        }
    }
    println!("{}", ans);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}

