fn read_line() -> String {
    let stdin = std::io::stdin();
    let mut line = String::new();
    stdin.read_line(&mut line).unwrap();
    line.trim().into()
}

macro_rules! scan_line {
    ($($ty: ty),*) => {{
        let line = read_line();
        let mut iter = line.split_whitespace();
        ($(iter.next().unwrap().parse::<$ty>().unwrap()),*)
    }}
}

fn main() {
    let (n, a, b) = scan_line!(i32, i32, i32);
    let mut lo = 1;
    let mut hi = n;
    let mut max_min = 0;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let ap = a / mid;
        let bp = b / (n - mid);
        max_min = std::cmp::max(max_min, std::cmp::min(ap, bp));
        if ap == bp {
            break;
        } else if ap < bp {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    println!("{}", max_min);
}

use std::io;
pub struct Scanner<B> {
    reader: B,
    buffer: Vec<String>,
}

impl<B: io::BufRead> Scanner<B> {
    pub fn new(reader: B) -> Self {
    Self {
        reader,
        buffer: Vec::new(),
    }
}

pub fn next<T: ::std::str::FromStr>(&mut self) -> T
    where
        T::Err: ::std::fmt::Debug,
    {
        if let Some(front) = self.buffer.pop() {
            front.parse::<T>().expect(&front)
        } else {
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Line not read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
            self.next()
        }
    }
}

fn main() {
    try_main().unwrap();
}

fn try_main() -> Result<(), Box<std::error::Error>> {
    let stdin = io::stdin();
    let mut sc = Scanner::new(stdin.lock());
    let n : usize = sc.next();
    let a : usize = sc.next();
    let b : usize = sc.next();
    let mut mc : usize = 0;
    for to_a in 1..n {
        let to_b = n.checked_sub(to_a).unwrap();
        let num_a = a / to_a;
        let num_b = b / to_b;
        mc = std::cmp::max(std::cmp::min(num_a, num_b), mc);
    }
    println!("{}", mc);
    Ok(())
}

