use std::io;

fn main() {
	let mut input = String::new();
	io::stdin().read_line(&mut input).unwrap();

	let mut iter = input.split_whitespace();
	let n: u16 = iter.next().unwrap().parse().unwrap();
	let a: u16 = iter.next().unwrap().parse().unwrap();
	let b: u16 = iter.next().unwrap().parse().unwrap();
	let lower: u16 = if a < b { a } else { b };

	let mut max: u16 = if a > b { a } else { b };
	let mut min: u16 = 1;
	let mut x: u16 = 1;

	while min <= max {
		let cur = (max + min) / 2;

		if cur <= lower && a / cur + b / cur >= n {
			x = cur;
			min = cur + 1;
		} else {
			max = cur - 1;
		}
	}

	println!("{}", x);
}

