fn main() {
	let mut inp = my_input::default();
	let out = &mut BufWriter::new(stdout());
	let n = inp.scan::<usize>();
	let m = inp.scan::<usize>();
	let T:Vec<usize> = (0..n).map(|_| inp.scan::<usize>()).collect();
	let mut acnt = vec![0 as usize; 101];
	let mut ans:Vec<usize> = Vec::new();
	for i in T {
		let mut cnt = 0 as usize;
		let mut sum = i as usize;
		for j in 1..101 {
			let mut C = min(acnt[j], (m - sum) / j);
			sum += j * C;
			cnt += acnt[j] - C;
		}
		ans.push(cnt);
		acnt[i] += 1;
	}
	for i in ans {
		write!(out, "{} ", i);
	}
}

#[derive(Default)]
struct my_input {
	buffer: Vec<String>
}

impl my_input {
	fn scan<T: std::str::FromStr>(&mut self) -> T {
		loop {
			if let Some(token) = self.buffer.pop() {
				return token.parse().ok().expect("Parsing Error");
			}
			let mut s = String::new();
			stdin().read_line(&mut s).expect("Reading Error");
			self.buffer = s.split_whitespace().rev().map(String::from).collect();
		}
	}
}

