    let mut bout = BufWriter::new(stdout());

    let n = input.u();
    let m = input.i();
    let mut c = vec![0; 101];
    let mut sum = 0;
    for _ in 0..n {
        let t = input.i();
        sum += t;
        let mut s = sum - m;
        let mut res = 0;
        if s > 0 {
            for i in (1..101).rev() {
                let x = c[i as usize];
                if x * i <= s {
                    s -= x * i;
                    res += x;
                } else {
                    res += (s + i - 1) / i;
                    break;
                }
            }
        }
        c[t as usize] += 1;
        write!(bout, "{} ", res).ok();
    }
}

