fn read_vector<T>(stdin: &io::Stdin) -> Vec<T>
where
    T: std::str::FromStr,
    <T as std::str::FromStr>::Err: std::fmt::Debug,
{
    let mut s = String::new();
    stdin.read_line(&mut s).unwrap();
    s = s.trim().to_string();
    let mut v: Vec<T> = Vec::new();
    for n in s.split_whitespace() {
        let i: T = n.parse().unwrap();
        v.push(i);
    }
    v
}

fn read_one<T>(stdin: &io::Stdin) -> T
where
    T: std::str::FromStr,
    <T as std::str::FromStr>::Err: std::fmt::Debug,
{
    let mut s = String::new();
    stdin.read_line(&mut s).unwrap();
    s.trim().split_whitespace().next().unwrap().parse().unwrap()
}

