use std::io;
use std::str;

const MOD: i128 = 1_000_000_007;

fn modpow(a: i128, b: i128) -> i128 {
    let mut a = a;
    let mut b = b;
    let mut ans = 1;
    while b > 0 {
        if b % 2 != 0 {
            ans = (ans * a) % MOD;
        }
        a = (a * a) % MOD;
        b /= 2;
    }
    ans
}

fn modinv(a: i128) -> i128 {
    modpow(a, MOD - 2) % MOD
}

fn modadd(a: i128, b: i128) -> i128 {
    let mut ans = (a + b) % MOD;
    if ans < 0 {
        ans += MOD;
    }
    ans
}

fn modmult(a: i128, b: i128) -> i128 {
    let mut ans = (a * b) % MOD;
    if ans < 0 {
        ans += MOD;
    }
    ans
}

fn moddiv(a: i128, b: i128) -> i128 {
    (a * modinv(b)) % MOD
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
    let a: i128 = scan.token();
    let b: i128 = scan.token();
    let n: i128 = scan.token();
    let x: i128 = scan.token();
    let mut ans;
    if n == 0 {
        ans = x % MOD;
    } else if n == 1 {
        ans = modadd(modmult(a, x), b);
    } else if a == 1 {
        ans = modadd(x, modmult(b, n));
    } else {
        ans = modpow(a, n);
        ans = modmult(ans, x);
        let mut quotient = modpow(a, n);
        quotient = modadd(quotient, -1);
        quotient = moddiv(quotient, a - 1);
        let mut part = b % MOD;
        part = modmult(part, quotient);
        ans = modadd(ans, part);
        // ans = ((modpow(a, n) * x) % MOD + ((b * (modpow(a, n) - 1).rem_euclid(MOD)) % MOD * modinv(a - 1)) % MOD) % MOD;
    }
    writeln!(out, "{}", ans).ok();
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());
    solve(&mut scan, &mut out);
}

pub struct Scanner<R> {
    reader: R,
    buffer: Vec<String>,
}

impl<R: io::BufRead> Scanner<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![],
        }
    }

    pub fn token<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }

    pub fn tokens<T: str::FromStr>(&mut self) -> Vec<T> {
        assert!(self.buffer.is_empty());
        let mut input = String::new();
        self.reader.read_line(&mut input).expect("Failed read");
        input
            .split_whitespace()
            .map(|x| x.parse().ok().expect("Failed parse"))
            .collect()
    }
}

