fn notebooks_amount(friends: i32, sheets_per_notebook: i32) -> i32 {
    let red_notebook_amount = (friends * RED) / sheets_per_notebook
        + if (friends * RED) % sheets_per_notebook != 0 { 1 } else { 0 };
    let green_notebook_amount = friends * GREEN / sheets_per_notebook
        + if (friends * GREEN) % sheets_per_notebook != 0 { 1 } else { 0 };
    let blue_notebook_amount = friends * BLUE / sheets_per_notebook
        + if (friends * BLUE) % sheets_per_notebook != 0 { 1 } else { 0 };

    let total_amount = red_notebook_amount + green_notebook_amount + blue_notebook_amount;

    total_amount
}

