fn run() {
    input! {
        n: usize,
        s: chars,
    }
    let s: Vec<usize> = s.into_iter().map(|c| {
        match c {
            'V' => 0,
            'K' => 1,
            _ => 2,
        }
    }).collect();
    let mut cnt = [0; 3];
    for k in s.iter() {
        cnt[*k] += 1;
    }
    let inf = n * (n + 1) / 2 + 1;
    // [末尾がV][使ったVの数][使ったKの数][使ったそれ以外]
    let mut dp = vec![vec![vec![vec![inf; cnt[2] + 1]; cnt[1] + 1]; cnt[0] + 1]; 2];
    dp[0][0][0][0] = 0;
    for v in 0..=cnt[0] {
        for k in 0..=cnt[1] {
            for a in 0..=cnt[2] {
                let x = dp[0][v][k][a];
                let y = dp[1][v][k][a];
                let z = [v, k, a];
                let count = |p: usize| -> usize {
                    let mut val = [0; 3];
                    let mut ans = 0;
                    for &q in s.iter() {
                        val[q] += 1;
                        if q == p && val[q] > z[p] {
                            break;
                        }
                        if val[q] > z[q] {
                            ans += 1;
                        }
                    }
                    ans
                };
                if v + 1 <= cnt[0] {
                    let val = min(x, y) + count(0);
                    dp[1][v + 1][k][a].chmin(val);
                }
                if k + 1 <= cnt[1] {
                    let val = x + count(1);
                    dp[0][v][k + 1][a].chmin(val);
                }
                if a + 1 <= cnt[2] {
                    let val = min(x, y) + count(2);
                    dp[0][v][k][a + 1].chmin(val);
                }
            }
        }
    }
    let (v, k, a) = (cnt[0], cnt[1], cnt[2]);
    let ans = min(dp[0][v][k][a], dp[1][v][k][a]);
    println!("{}", ans);
}

