use std::iter::{once, repeat};

fn main() {
    read!(n = u16, a = u16_, x = u16_, b = u16_, y = u16_);
    let iter1 = (a..)
        .map(|i| i % n)
        .take_while(|&i| i != x)
        .chain(once(x));
    let iter2 = repeat((0..n).rev()).flatten()
        .skip_while(|&i| i != b)
        .take_while(|&i| i != y)
        .chain(once(y));
    let ans = iter1.zip(iter2).any(|(i, j)| i == j);
    YN(ans);
}

use std::io;

macro_rules! parse_line {
    ($($t: ty), +) => {{
        let mut a_line = String::new();
        io::stdin().read_line(&mut a_line).expect("read error");
        let mut a_line_iter = a_line.split_whitespace();
        (
            $(
                a_line_iter.next().unwrap().parse::<$t>().expect("parse error"),
            )+
        )
    }};
}

fn main() {
    let (n, mut a, x, mut b, y) = parse_line!(i32, i32, i32, i32, i32);
    let mut ok = false;
    loop {
        if a == b {
            ok = true;
        }
        if a == x || b == y {
            break;
        }
        match a == n {
            true => a = 1,
            false => a += 1,
        }
        match b == 1 {
            true => b = n,
            false => b -= 1,
        }
    }
    match ok {
        true => println!("YES"),
        false => println!("NO"),
    }
}

