fn bruteforce(n: u64) -> u64 {
    let mut set = HashSet::<u64>::new();

    for a in 0..=n {
        for b in 0..=(n - a) {
            for c in 0..=(n - a - b) {
                set.insert(4 * a + 9 * b + 49 * c);
            }
        }
    }

    set.len() as u64
}

fn main() {
    let (n,) = parse_line!(u64);

    let answer = if n < 11 {
        bruteforce(n)
    } else {
        // The items {0, 4, 8, 9, 12, 13, 16, 17, 18, 20, 21, 22} are always reachable.
        let mut answer = 12u64;

        // The range 24 -- (67 + 49(n - 11)) = 49n - 472 is always reachable.
        answer += (49 * n - 472) - 24 + 1;

        // Now, the only numbers for which we don't know the answer are those in the range
        // [49n - 471, 49n]. For those, we brute-force the check.
        //
        // Formally, we wonder how many numbers in the range [49n - 471, 49n] can be written in the
        // form 4a + 9b + 49c with a + b + c <= n and a, b, c >= 0.
        //
        // The important observation is that if c <= n - 12, there is no way
        // 4a + 9b + 49c >= 49n - 471. Indeed, we have
        //               4a + 9b + 49c <= 9(n - c) + 49c
        //                             =  9n + 40c
        //                             <= 9n + 40(n - 12)
        //                             <= 49n - 40 * 12
        //                             <  49n - 471.
        //
        // For this reason, we know that c is in the range n - 11 .. n. This does not leave many
        // cases to check.
        let mut tailset = HashSet::<u64>::new();
        for c in (n - 11)..=n {
            for b in 0..=(n - c) {
                for a in 0..=(n - c - b) {
                    assert!(a + b + c <= n);

                    let candidate = 4 * a + 9 * b + 49 * c;
                    if candidate >= n * 49 - 471 {
                        tailset.insert(candidate);
                    } 
                }
            } 
        }

        answer += tailset.len() as u64;
        answer
    };

    println!("{}", answer);
}

