    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}
// ---------- end input macro ----------

fn run() {
    input! {
        n: u64,
    }
    let mul = |a: &[(u64, u64)], b: &[(u64, u64)]| -> Vec<(u64, u64)> {
        let mut c = vec![];
        for a in a.iter() {
            for b in b.iter() {
                c.push((a.0 + b.0, a.1 + b.1 - 1));
            }
        }
        c.sort_unstable();
        c.dedup_by(|a, b| {
            a.0 <= b.1 && {
                b.1.chmax(a.1);
                true
            }
        });
        c
    };
    let mut t = vec![(0, 1)];
    let mut s = vec![(1, 2), (5, 6), (10, 11), (50, 51)];
    let mut n = n;
    while n > 0 {
        if n & 1 == 1 {
            t = mul(&t, &s);
        }
        s = mul(&s, &s);
        n >>= 1;
    }
    let ans = t.iter().fold(0, |s, a| s + a.1 - a.0);
    println!("{}", ans);
}

fn main() {
    run();
}

