fn less(n: u64, m: u64, val: u64) -> u64 {
    let mut ptr = 0;
    for i in 1..=n {
        ptr += std::cmp::min(m, val / i);
    }
    return ptr;
}

fn solve(writer: &mut std::io::BufWriter<std::io::Stdout>) {
    let (n, m, k) = parse_line!(u64, u64, u64);
    let mut l = 0;
    let mut r = n * m + 1;
    while l + 1 < r {
        let mid = (l + r) / 2;
        if less(n, m, mid) < k {
            l = mid;
        }else{
            r = mid;
        }
    }
    writeln!(writer, "{}", r).unwrap();
}

