use std::cmp::*;

fn run() {
    input! {
        n: usize,
        p: [(chars, i32, i32); n],
    }
    let p = p
        .into_iter()
        .map(|p| ((p.0[0] == 'B') as usize, p.1, p.2))
        .collect::<Vec<_>>();
    let mut sum = vec![([0, 0], 0, 0)];
    for &(x, y, z) in p.iter() {
        for i in 0..sum.len() {
            let (mut a, mut b, mut c) = sum[i];
            a[x] += 1;
            b += y;
            c += z;
            sum.push((a, b, c));
        }
    }
    let mut now = std::collections::BTreeMap::new();
    now.insert((0, 0, 0), 0);
    for _ in 0..n {
        let mut next = std::collections::BTreeMap::new();
        for ((bit, rem_a, rem_b), v) in now {
            assert!(rem_a == 0 || rem_b == 0);
            let (cnt, _, _) = sum[bit];
            for (i, &(_, a, b)) in p.iter().enumerate() {
                if bit >> i & 1 == 1 {
                    continue;
                }
                let p = max(0, a - cnt[0]);
                let q = max(0, b - cnt[1]);
                let add = max(0, max(p - rem_a, q - rem_b));
                let v = v + add;
                let po = next.entry((bit | (1 << i), rem_a + add - p, rem_b + add - q)).or_insert(v);
                *po = std::cmp::min(*po, v);
            }
        }
        now = next;
    }
    let ans = now.into_iter().map(|(_, v)| v).min().unwrap() + n as i32;
    println!("{}", ans);
}

fn main() {
    run();
}

