const INF: i64 = 1i64 << 60;
fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let mut cards = Vec::new();
    for _ in 0..n {
        let c: String = sc.ne();
        let r: i64 = sc.ne();
        let b: i64 = sc.ne();
        let is_r = c == "R";
        cards.push((is_r, r, b));
    }
    let sn = 1 << n;
    let rn = n * (n + 1) / 2;
    let mut dp = vec![vec![-INF; rn]; sn];
    dp[0][0] = 0;
    for s in 0..sn {
        let mut rnum = 0;
        let mut bnum = 0;
        for i in 0..n {
            if (s >> i) & 1 == 0 {
                continue;
            }
            if cards[i].0 {
                rnum += 1;
            } else {
                bnum += 1;
            }
        }
        for i in 0..rn {
            // println!("{:b}, i: {}, {}", s, i, dp[s][i]);
            if dp[s][i] == -INF {
                continue;
            }
            for j in 0..n {
                if (s >> j) & 1 == 1 {
                    continue;
                }
                let ns = s | (1 << j);
                let ni = min(rnum, cards[j].1) as usize + i;
                dp[ns][ni] = max(dp[ns][ni], dp[s][i] + min(bnum, cards[j].2));
            }
        }
    }
    let rsum = cards.iter().fold(0, |acc, &t| acc + t.1);
    let bsum = cards.iter().fold(0, |acc, &t| acc + t.2);
    let mut ans = INF;
    for i in 0..rn {
        ans = min(ans, max(rsum - i as i64, bsum - dp[sn - 1][i]));
        // println!("{}", ans);
    }
    println!("{}", ans + n as i64);
}

