fn find_distinct_lc(text: &str) -> u8 {
    let mut hash: HashMap<char, bool> = HashMap::new();
    let mut counter = 0;
    for i in text.chars() {
        match hash.get(&i) {
            Some(_) => (),
            _ => {
                hash.insert(i, true);
                counter += 1;
            }
        }
    }
    counter
