fn charCount(x: &str) -> i32 {
    let mut v: Vec<i32> = vec![0; 26];
    let mut res = 0;
    for c in x.bytes() {
        if v[(c-0x61) as usize] == 0 {
            res = res + 1;
            v[(c-0x61) as usize] = 1;
        }
    }
    res
