fn f(n: i64, l: i64, r: i64, t: i32, w: i32) -> i64 {
    let mut result = 0;
        if(n <= r) {
            if(n >= l) {
                result += 1;
            }
            if(w == 0) {
                result += f(2*n, l, r, t+1, w);
            }
            result += f(3*n, l , r, t, w+1);
        }
    return result;
}

