fn check_row(v: Vec<u8>) {
    let mut previous: Option<usize> = None;
    let mut one_before: Option<usize> = None;
    for (i, c) in v.into_iter().enumerate() {
        match c {
            0 => {
                one_before = previous;
                previous = Some(i);
            },
            2 => {
                one_before = Some(i);
                previous = Some(i);
            },
            1 => (),
            _ => panic!("Oops!"),
        }

        if let Some(b) = one_before {
            if i > b + 4 {
                println!("YES");
                std::process::exit(0);
            }
        } else if i >= 4 {
            println!("YES");
            std::process::exit(0);
        }
    }
}

fn main() {
    let mut grid: Vec<u8> = Vec::with_capacity(100);

    for _ in 0..10 {
        let mut input = String::new();
        std::io::stdin().read_line(&mut input).unwrap();
        for c in input.trim().chars() {
            match c {
                '.' => grid.push(0),
                'X' => grid.push(1),
                'O' => grid.push(2),
                _ => panic!("Invalid character"),
            }
        }
    }

    for i in 0..10 {
        let it = (0..100).filter_map(|k| if k / 10 == i {Some(grid[k])} else {None});
        check_row(it.collect());

        let it = (0..100).filter_map(|k| if k % 10 == i {Some(grid[k])} else {None});
        check_row(it.collect());
    }

    for i in 0..6 {
        check_row((i..10).zip(0..(10 - i)).map(|(i, j)| grid[10 * i + j]).collect());
        check_row((i..10).zip(0..(10 - i)).map(|(i, j)| grid[10 * j + i]).collect());
        check_row((i..10).zip((i..10).rev()).map(|(i, j)| grid[10 * j + i]).collect());
    }

    for i in 4..10 {
        check_row((0..i).rev().zip(0..i).map(|(i, j)| grid[10 * i + j]).collect());
    }

    println!("NO");
}

