struct Graph {
    graph: Vec<Vec<(usize, i64)>>,
    vec: Vec<i64>,
    edges: Vec<(usize, usize, i64)>,
    mark: Vec<i64>,
    dcost: Vec<i64>,
}

impl Graph {
    fn generate_next(&mut self, cnt: i64) -> usize {
        self.vec.push(cnt);
        self.vec.len() - 1
    }
    fn add_edge(&mut self, u: usize, v: usize, len: i64) {
        self.edges.push((u, v, len));
    }
}

fn dfs(l: usize, r: usize, depth: usize, parent: usize, table: &Vec<(Vec<i64>, usize, i64)>, graph: &mut Graph) {
    if l == r {
        if table[l].1 >= 2 {
            let nid = graph.generate_next(table[l].2);
            let mut d = 0;

            let pn = table[0].0.len();
            for i in depth..pn {
                d += table[l].0[i];
            }
            graph.add_edge(parent, nid, d);
        }
        return;
    }

    if table[l].0[depth] == table[r].0[depth] {
        if table[l].0[depth] == 0 {
            dfs(l, r, depth+1, parent, table, graph);
        } else {
            let nid = graph.generate_next(0);
            graph.add_edge(parent, nid, table[l].0[depth]);
            dfs(l, r, depth+1, nid, table, graph);
        }
        return;
    }

    let mut ll = l;
    let mut last_value = 0;
    let mut cparent = parent;
    while ll <= r {
        let mut rr = ll;
        while rr <= r && table[ll].0[depth] == table[rr].0[depth] {
            rr += 1;
        }
        // [ll, rr)
        let add_len = table[ll].0[depth] - last_value;
        assert!(add_len >= 0);
        if add_len == 0 {
            dfs(ll, rr-1, depth+1, parent, table, graph);
        } else {
            let nid = graph.generate_next(0);
            graph.add_edge(cparent, nid, add_len);
            dfs(ll, rr-1, depth+1, nid, table, graph);
            cparent = nid;
        }
        last_value = table[ll].0[depth];
        ll = rr;
    }
}


fn dfs2(now: usize, par: usize, g: &mut Graph) -> (i64, i64) {
    let mut total_mark = g.vec[now];
    let mut total_cost = 0;
    for (to, len) in g.graph[now].clone() {
        if to == par {
            continue;
        }
        let (m, c) = dfs2(to, now, g);
        total_mark += m;
        total_cost += c + m * len;
    }
    g.mark[now] = total_mark;
    g.dcost[now] = total_cost;
    (total_mark, total_cost)
}

fn dfs3(now: usize, par: usize, g: &mut Graph) -> i64 {
    let mut best = g.dcost[now];
    for (to, len) in g.graph[now].clone() {
        if to == par {
            continue;
        }
        let mark_back = g.mark[to];
        let dcost_back = g.dcost[to];
        let reduce_cost = g.dcost[to] + g.mark[to] * len;
        let reduce_mark = g.mark[to];


        g.dcost[to] += (g.dcost[now] - reduce_cost) + (g.mark[now] - reduce_mark) * len;
        g.mark[to] += (g.mark[now] - reduce_mark);

        best = min(best, dfs3(to, now, g));

        g.mark[to] = mark_back;
        g.dcost[to] = dcost_back;

    }
    // debug!(now, best);
    best
}

const LIMIT: usize = 5000;

fn main() {
    input! {
        n: usize,
        k: [usize; n]
    };

    let mut deg = vec![0; LIMIT+1];
    for k in k {
        if k == 0 {
            deg[1] += 1;
        } else {
            deg[k] += 1;
        }
    }
    let (primes, is_prime) = generate_primes(LIMIT+1);

    let mut pn = primes.len();
    let mut vec = vec![];
    // let mut edges = vec![];

    let mut l = LIMIT;
    while l >= 2 {
        let mut lw = l;
        while !is_prime[lw] {
            lw -= 1;
        }

        for num in (lw..=l).rev() {
            let mut ptbl = vec![0; pn];
            for i in 0..pn {
                let mut num = num as i64;
                while num >= primes[i] {
                    ptbl[i] += num / primes[i];
                    num /= primes[i];
                }
            }
            ptbl.reverse();
            vec.push((ptbl, num, deg[num]));
        }
        l = lw-1;
    }
    vec.push((vec![0; pn], 1, deg[1]));
    vec.sort();

    let mut graph = Graph { vec: vec![], edges: vec![], graph: vec![], mark: vec![], dcost: vec![] };
    graph.generate_next(deg[1]);

    dfs(0, vec.len()-1, 0, 0, &vec, &mut graph);

    let vn = graph.vec.len();

    let mut deg = graph.vec.clone();
    let mut g = vec![vec![]; vn];
    for &(u, v, len) in &graph.edges {
        g[u].push((v, len));
        g[v].push((u, len));
    }
    graph.graph = g;
    graph.mark = vec![0; vn];
    graph.dcost = vec![0; vn];

    dfs2(0, vn, &mut graph);

    // debug!(graph.graph);
    // debug!(graph.vec);

    let ans = dfs3(0, vn, &mut graph);
    println!("{}", ans);
}

