        for y in 1..x {
            if gcd(x, y) > 1 {
                continue;
            }
            // キャリー抜きで確定してる桁数の範囲でn以下なら0
            // xのキャリーがいくつ
            // yのキャリーがいくつ
            // xの出現
            // yの出現
            let m = 9 / x;
            let init = vec![vec![vec![vec![vec![ModInt::zero(); 1 << m]; 1 << m]; 9]; 9]; 2];
            let mut now = init.clone();
            let mut next = init.clone();
            now[0][0][0][0][0] = ModInt::one();
            for &digit in s.iter().rev() {
                next.clone_from(&init);
                for (cond, v) in now.iter().enumerate() {
                    for (cx, v) in v.iter().enumerate() {
                        for (cy, v) in v.iter().enumerate() {
                            for (bit_x, v) in v.iter().enumerate() {
                                for (bit_y, &v) in v.iter().enumerate() {
                                    for d in 0..10 {
                                        let carry_x = (cx + d * x) / 10;
                                        let carry_y = (cy + d * y) / 10;
                                        let dx = (cx + d * x) % 10;
                                        let dy = (cy + d * y) % 10;
                                        let nx = bit_x | if dx > 0 && dx % x == 0 {1 << (dx / x - 1)} else {0};
                                        let ny = bit_y | if dy > 0 && dy % y == 0 && dy / y <= m {1 << (dy / y - 1)} else {0};
                                        if dx < digit {
                                            next[0][carry_x][carry_y][nx][ny] += v;
                                        } else if dx > digit {
                                            next[1][carry_x][carry_y][nx][ny] += v;
                                        } else {
                                            next[cond][carry_x][carry_y][nx][ny] += v;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                std::mem::swap(&mut next, &mut now);
            }
            for (i, v) in now[0][0][0].iter().enumerate() {
                for (j, &v) in v.iter().enumerate() {
                    let mut ok = false;
                    for k in 0..m {
                        ok |= ((i >> k) & 1 == 1) && ((j >> k) & 1 == 1);
                    }
                    if ok && v.0 > 0 {
                        ans += v + v;
                    }
                }
            }
        }
    }
    println!("{}", ans);
}

