fn getline() -> String{
    let mut __ret = String::new();
    std::io::stdin().read_line(&mut __ret).ok();
    return __ret;
}

fn main() {
    let s = getline();
    let inp:Vec<_> = s.trim().split(' ').collect();
    let mut n: i32 = inp[0].parse().unwrap();
    let k: usize = inp[1].parse().unwrap();
    let mut ans = vec![];
    for i in 2..n-1 {
        while n%i == 0 {
            if ans.len() == k-1 {
                break;
            }
            ans.push(i);
            n /= i;
        }
    }
    if ans.len() == k-1 && n != 1 {
        for e in &ans {
            print!("{} ",e);
        }
        println!("{}",n);
    }else{
        println!("-1");
    }
}

