use std::cmp::{min, max};
use std::io::{BufWriter, stdin, stdout, Write};
const BITS: usize = 19;

#[derive(Default)]
struct Scanner {
    buffer: Vec<String>
}
impl Scanner {
    fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            stdin().read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}

fn main() {
    let mut scan = Scanner::default();
    let out = &mut BufWriter::new(stdout());

    let n: i32 = scan.next::<i32>();
    let m: i32 = scan.next::<i32>();

    let mut arr: Vec<(i32, i32)> = Vec::new();

    for _i in 0..m {
        let a: i32 = scan.next::<i32>();
        let b: i32 = scan.next::<i32>();
        arr.push((a, b));
    }

    arr.sort_by(|a, b| a.1.cmp(&b.1));
    arr.reverse();

    let mut total: i32 = 0;
    let mut total_boxes: i32 = 0;

    'outer: for (a, b) in arr.iter() {
        if total_boxes >= n {
            break;
        }
        'inner: for _i in 0..*a {
            if total_boxes >= n {
                break 'outer;
            }
            total_boxes += 1;
            total += *b;
        }
    }

    writeln!(out, "{}", total);
}

