static mut MOD: i64 = 0;

fn main() {
    let mut sc = Scanner::stdin();
    let mut wr = Writer::stdout();

    let (n, m) = scan!(sc, usize, i64);
    unsafe {
        MOD = m;
    }
    //let mut tree = SegmentTree::<MySpec>::new(vec![0; n + 1]);
    //tree.set(n, 1);
    // suffix[i] = sum of ways to get to i and later fields
    let mut suffix = vec![0; n + 1];
    suffix[n] = 1;

    for x in (1..=n).rev() {
        //let mut cnt = tree.query(x..);
        let mut cnt = suffix[x];
        //p!(x, cnt);

        for z in 2.. {
            if x * z > n {
                break;
            }
            //let inc = tree.query(x * z..((x + 1) * z).min(n + 1));
            let inc = suffix[x * z] - suffix.get((x + 1) * z).copied().unwrap_or(0);
            p!(x, z, inc);
            cnt = (cnt + inc) % m;
        }

        //tree.set(x, cnt);
        p!(x, cnt);
        suffix[x] = (suffix.get(x + 1).copied().unwrap_or(0) + cnt) % m;
        suffix[x - 1] = suffix[x];
        p!(x, suffix[x]);
    }

    //wr.write(tree.get(1)).unwrap();
    wr.write((suffix[1] - suffix[2] + m) % m).unwrap();
}

