fn main() {
    solve();
}

fn solve() {
    let mut ans: u64 = 0;
    let (N, M) = get!(usize, u64);
    
    let mut dp = vec![0; N + 5];
    dp[N] = 1;
    let mut sum = 0;
    for i in (1..=N).rev() {
        dp[i] += sum;
        dp[i] %= M;

        for j in 1..i {
            if j * j > i {
                break;
            }

            let b = i / (j + 1);
            let c = i / j;
            let d = (dp[i] * (c - b) as u64) % M;
            dp[j] += d;
            dp[j] %= M;

            if j != i / j {
                let a = i / j;
                if a == i {
                    continue;
                }
                let b = i / (a + 1);
                let c = i / a;
                let d = (dp[i] * (c - b) as u64) % M;
                dp[a] += d;
                dp[a] %= M;
            }
        }

        sum += dp[i];
        sum %= M;
    }
    let ans = dp[1] % M;

    echo!(ans);
}

