fn solve() {
    let (a, b) = parse_line!(u64, u64);
    let mut pos = 0;
    let mut count = 0;
    while pos != a * b {
        let closest_a = (pos / a + 1) * a;
        let closest_b = (pos / b + 1) * b;
        if closest_a < closest_b {
            count += closest_a - pos;
            pos = closest_a;
        }else if closest_b < closest_a {
            pos = closest_b;
        }else if closest_a == closest_b {
            if a > b {
                count += closest_a - pos;
            }
            pos = closest_a;
        }
    }
    if count * 2 == a * b {
        println!("Equal");
    }else if count * 2 > a * b {
        println!("Dasha");
    }else{
        println!("Masha");
    }
}

