    let mut v = get!(usize;;);

    v.sort();

    if v[0] == 1 {
        println!("YES");
        return;
    }

    while {
        let a = v[0];
        let b = v[1];
        let c = v[2];

        let t0 = 0;
        let t1 = 1;

        let mut t2 = 0;

        for t in 2..2000 {
            if !((t - t0) % a == 0 || (t - t1) % b == 0) {
                t2 = t;
                break;
            }
        }

        if (0..2000).all(|t| {
            (t >= t0 && (t - t0) % a == 0) || (t >= t1 && (t - t1) % b == 0)
                || (t >= t2 && (t - t2) % c == 0)
        }) {
            println!("YES");
            return;
        }

        v.next_permutation()
    } {}

    println!("NO");
}

