    let mut lines = stdin.lock().lines();

    let input_string = lines.next().unwrap().expect("input reading failed");
    let len = input_string.len();
    let iter = input_string.chars().take(len / 2 + 1);
    let mut reverse = input_string.chars().rev().take(len / 2 + 1);
    let mut palindrome = true;
    let mut same_char = true;

    // input string is non-empty
    let my_char = input_string.chars().nth(0).unwrap();

    for char_a in iter {
        if char_a != my_char {
            same_char = false;
        }

        let char_b = match reverse.next() {
            Some(c) => c,
            None => {
                break;
            }
        };

        if char_a != char_b {
            palindrome = false;
            break;
        }
    }

    let mut count = len;
    if palindrome {
        if same_char {
            count = 0;
        } else {
            count = len - 1;
        }
    }

    println!("{}", count);
}

