    let mut min = std::u64::MAX;
    let mut val: u64 = 1;
    for i in 2..n {
        if i * i > n {
            break;
        }
        if n % i != 0 {
            continue;
        }
        val *= i;
        let mut cnt = 0;
        while n % i == 0 {
            n /= i;
            cnt += 1;
        }
        max = std::cmp::max(max, cnt);
        min = std::cmp::min(min, cnt);
    }
    if n != 1 {
        max = std::cmp::max(max, 1);
        min = std::cmp::min(min, 1);
        val *= n;
