impl DSU {
    fn new(n: usize) -> Self {
        Self {
            p: (0..n).collect(),
            s: vec![1; n],
        }
    }

    fn find(&mut self, i: usize) -> usize {
        if self.p[i] != i {
            self.p[i] = self.find(self.p[i]);
        }
        self.p[i]
    }

    fn union(&mut self, mut i: usize, mut j: usize) -> usize {
        i = self.find(i);
        j = self.find(j);
        if i == j { return i; }
        let (i, j) = if self.s[i] < self.s[j] { (i, j) } else { (j, i) };
        self.p[i] = j;
        self.s[j] += self.s[i];
        j
    }

    fn classes(&self) -> impl Iterator<Item=&'_ usize> {
        self.p.iter().collect::<BTreeSet<_>>().into_iter()
    }
}

