fn solve() {
    let n: usize = get();
    let k = get();
    let m: i64 = get();
    let mut t: Vec<i64> = (0 .. k).map(|_| get()).collect();
    t.sort();
    let tsum: i64 = t.iter().sum();
    let mut ma = 0;
    for comp in 0 .. n + 1 {
        let rem = m - comp as i64 * tsum;
        if rem < 0 {
            break;
        }
        let mut remtask = Vec::new();
        for _ in 0 .. n - comp {
            remtask.append(&mut t.clone());
        }
        remtask.sort();
        let mut tot = 0;
        let mut pos = 0;
        while pos < remtask.len() {
            tot += remtask[pos];
            if tot > rem {
                break;
            }
            pos += 1;
        }
        ma = max(ma, comp * (t.len() + 1) + pos);
    }
    println!("{}", ma);
}

