// アリスとボブがゲームをする
// アリスはN個の宝を持っている。
// i個目の宝には A_i 枚のコインが入っている
// またM個の鍵がある
// j個目の鍵の値段はコインB_j枚である
//
// 最初、アリスは宝のいくつかに錠をつける
// j番目の錠はj番目の鍵でのみ開くことができる
// i番目の宝にj番目の錠をつけるのにかかるコストは C_{i, j} である
//
// 錠をつけ終わった後、ボブはいくつか鍵をアリスから買って宝を開ける
// (宝から手に入ったコイン) - (鍵を買うのに使ったコイン) > 0
// を満たす時、ボブの勝ちとなる
//
// アリスはボブが勝てないように錠をつける時、最小コストを求めよ
// 不可能なら-1を出力せよ
//
// 1 <= N, M <= 6
// 1 <= A_i, B_j <= 4
// 1 <= C_{i, j} <= 10^7
//
//
// メモ
// sum b < sum a なら-1
// そうでないなら錠を全部つければとりあえずは勝てる
// 愚直解ってなんだ？
// 錠を全探索
// その後鍵の買い方を全探索
// コストを計算して利得の最大値を計算、答えの更新
// これでいい
// 計算量 O(2^(NM) * 2^(M) * N) くらい？
// 当然間に合わん
// 鍵は全探索せずともフローで解ける
// 鍵、宝でそれぞれ頂点を作る
// src -> 鍵i にb_i
// 鍵j -> 宝i に錠がついてるならinf
// 宝i -> dst にa_i
// を張ってフローを流す
// sum a_i > (流量)
// ならボブの勝ち
// これでもまだ間に合わない
// 
// ボブは鍵を買わないことで常に0を達成できる
// アリスはボブの最適戦略がこれになるようにしたい
// つまりカットが常に宝->dst のところになるようにしたい
// N, M, A, B が小さいのでこれをそのままdpにする
// 宝についてループを回しつつ辺を張って流量を全部試す
// 辺を満たしたら次へ
// みたいな

fn run() {
    input! {
        n: usize,
        m: usize,
        a: [i32; n],
        b: [i32; m],
        c: [[i32; m]; n],
    }
    let mut memo = Map::new();
    memo.insert(b, 0);
    for (a, c) in a.into_iter().zip(c) {
        let mut dp = Map::new();
        for (b, v) in memo.into_iter() {
            dp.insert((a, b), v);
        }
        for (i, c) in c.into_iter().enumerate() {
            let mut next = dp.clone();
            for ((a, b), v) in dp {
                let v = v + c;
                for k in 1..=b[i].min(a) {
                    let mut b = b.clone();
                    b[i] -= k;
                    let a = a - k;
                    next.entry((a, b)).or_insert(v).chmin(v);
                }
            }
            dp = next;
        }
        memo = Map::new();
        for ((a, b), v) in dp {
            if a == 0 {
                memo.entry(b).or_insert(v).chmin(v);
            }
        }
    }
    let ans = memo.values().min().cloned().unwrap_or(-1);
    println!("{}", ans);
}

fn main() {
    run();
}

