fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn run() {
    input! {
        n: usize,
        p: [usize1; n],
    }
    let mut q = p.clone();
    q.sort();
    q.dedup();
    if q.len() < n {
        println!("-1");
        return;
    }
    let mut a = vec![];
    let mut used = vec![false; n];
    for i in 0..n {
        if used[i] {
            continue;
        }
        used[i] = true;
        let mut k = p[i];
        let mut c = 1;
        while k != i {
            used[k] = true;
            c += 1;
            k = p[k];
        }
        if c % 2 == 0 {
            a.push(c / 2);
        } else {
            a.push(c);
        }
    }
    a.sort();
    let ans = a.iter().fold(1, |s, a| s / gcd(s, *a) * *a);
    println!("{}", ans);
}

fn main() {
    run();
}

