fn can(m: usize, a: &[usize], p: &[(usize, usize)]) -> bool {
    let mut last = m;
    let mut free = 0;
    let mut rem = vec![];
    rem.extend_from_slice(a);
    for &(d, t) in p.iter().rev() {
        if d > m {
            continue;
        }
        if last > d {
            free += last - d;
            last = d;
        }
        while rem[t] > 0 && last > 0 {
            rem[t] -= 1;
            last -= 1;
        }
    }
    free += last;
    2 * rem.into_iter().fold(0, |s, a| s + a) <= free
}

fn run() {
    input! {
        n: usize,
        m: usize,
        a: [usize; n],
        p: [(usize, usize1); m],
    }
    let mut p = p;
    p.sort_by_key(|p| p.0);
    let mut ng = 0;
    let mut ok = 400_000;
    while ok - ng > 1 {
        let m = (ok + ng) / 2;
        if can(m, &a, &p) {
            ok = m;
        } else {
            ng = m;
        }
    }
    println!("{}", ok);
}

fn main() {
    run();
}

