use std::cmp;

fn calcu_size(ix: i32, iy: i32, n: i32, second: i32) -> i64 {
    let mut total = 0i64;
    // middle
    let lefty: i32 = cmp::max(iy - second, 1);
    let righty: i32 = cmp::min(iy + second, n);

    total += (righty - lefty) as i64 + 1;

    // upper
    for i in 0..cmp::min(second, ix - 1) {
        let _row = ix - i - 1;
        let lefty = cmp::max(iy - second + i + 1, 1);
        let righty = cmp::min(iy + second - i - 1, n);
        total += (righty - lefty) as i64 + 1;
    }

    // lower
    for i in 0..cmp::min(second, n - ix) {
        let _row = ix + i + 1;
        let lefty = cmp::max(iy - second + i + 1, 1);
        let righty = cmp::min(iy + second - i - 1, n);
        total += (righty - lefty) as i64 + 1;
    }

    return total;
}

fn main() {
    let mut input_str = String::new();
    std::io::stdin().read_line(&mut input_str).expect("read error");
    let mut iter = input_str.split_whitespace();
    let n: i32 = iter.next().unwrap().parse().unwrap();
    let x: i32 = iter.next().unwrap().parse().unwrap();
    let y: i32 = iter.next().unwrap().parse().unwrap();
    let c: i32 = iter.next().unwrap().parse().unwrap();

    let mut left = -1;
    let mut right = 2 * (((2.0 * (c as f64)).sqrt() as i32) + 1);
    while left != right - 1 {
        let mid = (left + right) >> 1;
        if calcu_size(x, y, n, mid) < c as i64 {
            left = mid;
        } else {
            right = mid;
        }
    }
    println!("{}", right);
}

